INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edwnh/dqmc/dqmc-advanced', 'community', 'edwnh', 'dqmc', 'edwnh/dqmc', 'dqmc-advanced', 16, 5, 30, '2026-02-21T00:09:14Z', '2026-03-06T06:43:05.241Z', 'a32db98cff4f5ebd0a83215f27c4dc5565f7b5b2c421c4f407cf49b5e7ebdfab', '{"id":"edwnh/dqmc/dqmc-advanced","name":"dqmc-advanced","description":{"en":"The dqmc-advanced skill enables advanced topics such as unequal-time measurements and analytic continuation for AI agents. It benefits developers working with time-dependent correlation functions and zero-frequency susceptibilities.","zh":"dqmc-advanced是一种高级AI工具，支持不等时间测量和分析性连续性，适用于开发高性能AI应用","ja":"dqmc-advancedは、高度なAIツールであり、不等時間測定と解析的連続性をサポートし、高性能AIアプリケーションの開発に適しています","ko":"dqmc-advanced는 고급 AI 도구로, 불균일 시간 측정 및 해석적 연속성을 지원하여 고성능 AI 애플리케이션 개발에 적합합니다","es":"dqmc-advanced es una herramienta para realizar mediciones avanzadas, incluyendo mediciones de tiempo desigual y continuación analítica de datos de tiempo imaginario a frecuencias reales","fr":"dqmc-advanced est un outil pour effectuer des mesures avancées, notamment des mesures de temps inégales et la poursuite analytique des données de temps imaginaire à des fréquences réelles","de":"dqmc-advanced ist ein Tool für erweiterte Messungen, einschließlich ungleichzeitiger Messungen und analytischer Fortsetzung von imaginären Zeitdaten auf reale Frequenzen","pt":"O dqmc-advanced é uma ferramenta de AI Agents que permite medições de tempo desigual e continuação analítica para tópicos avançados","ru":"dqmc-advanced - это инструмент ИИ Агентов, который позволяет проводить неравномерные измерения времени и аналитическое продолжение для продвинутых тем","ar":"dqmc-advanced هو أداة آلات الذكاء الاصطناعي التي تمكن القياسات الزمنية غير المتساوية والاستمرار التحليلي لمواضيع متقدمة"},"seo":{"title":{"en":"dqmc-advanced: Advanced Topics Setup Guide | AI Agent Skill","zh":"dqmc-advanced_SETUP指南：高级话题和技术","ja":"dqmc-advancedセットアップガイド：高度なトピックとテクノロジー","ko":"dqmc-advanced 설정 가이드: 고급 주제 및 기술","es":"Guía de configuración de dqmc-advanced para mediciones av...","fr":"Guide de configuration de dqmc-advanced pour des mesures ...","de":"Konfigurationsleitfaden für dqmc-advanced für erweiterte ...","pt":"Guia de Configuração dqmc-advanced: Tópicos Avançados de ...","ru":"Руководство по настройке dqmc-advanced: Продвинутые темы ...","ar":"دليل إعداد dqmc-advanced: مواضيع متقدمة لآلات الذكاء الاص..."},"description":{"en":"Unlock the full potential of dqmc-advanced with our expert guide. Learn how to enable unequal-time measurements and analytic continuation for advanced AI age...","zh":"了解dqmc-advanced的高级话题，如不等时间测量和分析性连续性，提高您的AI开发技能","ja":"dqmc-advancedの高度なトピック、例えば不等時間測定と解析的連続性について学び、AI開発スキルを高める","ko":"dqmc-advanced의 고급 주제, 예를 들어 불균일 시간 측정 및 해석적 연속성에 대해 배우고 AI 개발 실력을 향상시키세요","es":"Aprende a configurar dqmc-advanced para realizar mediciones de tiempo desigual y continuar analíticamente datos de tiempo imaginario a frecuencias reales","fr":"Découvrez comment configurer dqmc-advanced pour effectuer des mesures de temps inégales et poursuivre analytiquement les données de temps imaginaire à des fr...","de":"Erfahren Sie, wie Sie dqmc-advanced konfigurieren, um ungleichzeitige Messungen durchzuführen und imaginäre Zeitdaten analytisch auf reale Frequenzen fortzus...","pt":"Aprenda a configurar o dqmc-advanced para tópicos avançados, incluindo medições de tempo desigual e continuação analítica","ru":"Узнайте, как настроить dqmc-advanced для продвинутых тем, включая неравномерные измерения времени и аналитическое продолжение","ar":"تعلم كيفية إعداد dqmc-advanced لمواضيع متقدمة، بما في ذلك قياسات زمنية غير متساوية والاستمرار التحليلي"},"definition":{"en":"dqmc-advanced is a skill that provides advanced functionality for AI agents, including unequal-time measurements and analytic continuation.","zh":"dqmc-advanced是一种支持不等时间测量和分析性连续性的高级AI工具","ja":"dqmc-advancedは、不等時間測定と解析的連続性をサポートする高度なAIツールです","ko":"dqmc-advanced는 불균일 시간 측정 및 해석적 연속성을 지원하는 고급 AI 도구입니다","es":"dqmc-advanced es una herramienta de AI Agent para mediciones avanzadas de tiempo desigual y continuación analítica","fr":"dqmc-advanced est un outil d''agent IA pour des mesures avancées de temps inégales et de poursuite analytique","de":"dqmc-advanced ist ein Tool für künstliche Intelligenz-Agenten für erweiterte Messungen von ungleichzeitigen und analytischen Fortsetzungen","pt":"dqmc-advanced é uma ferramenta de AI Agents para tópicos avançados, como medições de tempo desigual e continuação analítica","ru":"dqmc-advanced - это инструмент ИИ Агентов для продвинутых тем, таких как неравномерные измерения времени и аналитическое продолжение","ar":"dqmc-advanced هو أداة آلات الذكاء الاصطناعي لمواضيع متقدمة، مثل القياسات الزمنية غير المتساوية والاستمرار التحليلي"},"features":{"en":["Enables unequal-time measurements by setting `period_uneqlt > 0` during file generation","Supports analytic continuation using maximum entropy for imaginary-time data","Required for zero-frequency susceptibilities (`nnrw0`, `zzrw0`) and D-wave pair susceptibility (`dwq0t`)","Allows for time-dependent correlation functions","Increases runtime and memory usage due to unequal-time measurements"],"zh":["支持不等时间测量（period_uneqlt > 0）","分析性连续性，用于将虚时间数据继续到实频率","适用于零频率磁化率和D波对磁化率等应用","支持时间相关函数计算"],"ja":["不等時間測定（period_uneqlt > 0）をサポート","解析的連続性、虚時間データを実頻率に続ける","零頻率磁化率やD波ペア磁化率などのアプリケーションに適しています","時間相関関数の計算をサポート"],"ko":["불균일 시간 측정（period_uneqlt > 0） 지원","해석적 연속성, 가상 시간 데이터를 실제 주파수에 연장","零 주파수 자화율 및 D파 쌍 자화율 등 애플리케이션에 적합","시간 상관 함수 계산 지원"],"es":["Mediciones de tiempo desigual con `period_uneqlt`","Continuación analítica de datos de tiempo imaginario a frecuencias reales","Soporte para susceptibilidades de frecuencia cero","Soporte para funciones de correlación dependientes del tiempo","Opción para aumentar la precisión con `maxent`"],"fr":["Mesures de temps inégales avec `period_uneqlt`","Poursuite analytique des données de temps imaginaire à des fréquences réelles","Prise en charge des susceptibilités de fréquence zéro","Prise en charge des fonctions de corrélation dépendantes du temps","Option pour augmenter la précision avec `maxent`"],"de":["Ungleichzeitige Messungen mit `period_uneqlt`","Analytische Fortsetzung von imaginären Zeitdaten auf reale Frequenzen","Unterstützung für Nullfrequenz-Suszeptibilitäten","Unterstützung für zeitabhängige Korrelationsfunktionen","Option zur Erhöhung der Genauigkeit mit `maxent`"],"pt":["Medições de tempo desigual","Continuação analítica","Suporta funções de correlação de tempo dependente","Requer `period_uneqlt > 0` durante a geração de arquivos","Suporta susceptibilidades de frequência zero","Suporta funções de suscetibilidade de pares de ondas D"],"ru":["Неравномерные измерения времени","Аналитическое продолжение","Поддерживает функции корреляции времени","Требует `period_uneqlt > 0` во время генерации файлов","Поддерживает susceptibilidades частоты ноль","Поддерживает функции susceptibilidad пар волн D"],"ar":["قياسات زمنية غير متساوية","الاستمرار التحليلي","يدعم وظائف الارتباط الزمني","يتطلب `period_uneqlt > 0` خلال توليد الملفات","يدعم قابلات التأثر بتردد الصفر","يدعم وظائف قابلات التأثر للأزواج الموجية D"]},"keywords":{"en":["how to use dqmc-advanced","dqmc-advanced setup guide","dqmc-advanced alternative","dqmc-advanced vs other AI skills","dqmc-advanced install","what is dqmc-advanced","dqmc-advanced tutorial","dqmc-advanced advanced topics","dqmc-advanced unequal-time measurements"],"zh":["dqmc-advanced","AI工具","不等时间测量","分析性连续性","零频率磁化率","D波对磁化率","时间相关函数"],"ja":["dqmc-advanced","AIエージェント","不等時間測定","解析的連続性","零頻率磁化率","D波ペア磁化率","時間相関関数"],"ko":["dqmc-advanced","AI도구","불균일 시간 측정","해석적 연속성","零 주파수 자화율","D파 쌍 자화율","시간 상관 함수"],"es":["dqmc-advanced","mediciones de tiempo desigual","continuación analítica","susceptibilidades de frecuencia cero","funciones de correlación dependientes del tiempo","AI Agent","herramientas de AI","Agentes de Inteligencia Artificial"],"fr":["dqmc-advanced","mesures de temps inégales","poursuite analytique","susceptibilités de fréquence zéro","fonctions de corrélation dépendantes du temps","agent IA","outils d''IA","Agents d''Intelligence Artificielle"],"de":["dqmc-advanced","ungleichzeitige Messungen","analytische Fortsetzung","Nullfrequenz-Suszeptibilitäten","zeitabhängige Korrelationsfunktionen","künstliche Intelligenz-Agenten","KI-Tools","künstliche Intelligenz Agenten"],"pt":["dqmc-advanced","AI Agents","medições de tempo desigual","continuação analítica","funções de correlação de tempo dependente","susceptibilidades de frequência zero","funções de suscetibilidade de pares de ondas D","configuração dqmc-advanced"],"ru":["dqmc-advanced","ИИ Агенты","неравномерные измерения времени","аналитическое продолжение","функции корреляции времени","susceptibilidades частоты ноль","функции susceptibilidad пар волн D","настройка dqmc-advanced"],"ar":["dqmc-advanced","آلات الذكاء الاصطناعي","قياسات زمنية غير متساوية","الاستمرار التحليلي","وظائف الارتباط الزمني","قابلات التأثر بتردد الصفر","وظائف قابلات التأثر للأزواج الموجية D","إعداد dqmc-advanced"]}},"owner":"edwnh","repo":"dqmc","repoPath":"edwnh/dqmc","stars":16,"forks":5,"updatedAt":"2026-02-21T00:09:14Z","topics":[],"category":"community","skillMd":{"name":"dqmc-advanced","description":"Advanced DQMC features including unequal-time measurements, analytic continuation, and queue system internals. Use when enabling dynamical correlations, performing MaxEnt continuation, or understanding HDF5 data structure.","bodyPreview":"# Advanced Topics\n\n## Unequal-Time Measurements\n\nEnable by setting `period_uneqlt > 0` during file generation:\n\n```bash\ndqmc-util gen period_uneqlt=8 ...\n```\n\nRequired for:\n- `nnrw0`, `zzrw0` - Zero-frequency susceptibilities\n- `dwq0t` - D-wave pair susceptibility\n- Any time-dependent correlation functions\n\n**Note:** Unequal-time measurements significantly increase runtime and memory usage.\n\n## Analytic Continuation\n\nUse maximum entropy for continuing imaginary-time data to real frequencies:\n\n``","body":"# Advanced Topics\n\n## Unequal-Time Measurements\n\nEnable by setting `period_uneqlt > 0` during file generation:\n\n```bash\ndqmc-util gen period_uneqlt=8 ...\n```\n\nRequired for:\n- `nnrw0`, `zzrw0` - Zero-frequency susceptibilities\n- `dwq0t` - D-wave pair susceptibility\n- Any time-dependent correlation functions\n\n**Note:** Unequal-time measurements significantly increase runtime and memory usage.\n\n## Analytic Continuation\n\nUse maximum entropy for continuing imaginary-time data to real frequencies:\n\n```python\nfrom dqmc_util import maxent\n\n# Solve G = K A given:\n# - G: binned data, shape (nbin, ntau)\n# - K: kernel, shape (ntau, nw)\n# - m: default model, shape (nw,)\nA_omega = maxent.calc_A(G, K, m)\n```\n\n## HDF5 File Structure\n\n```\n/metadata/     # Model info (mu, Nx, Ny, beta)\n/params/       # Simulation parameters, precomputed matrices\n/state/        # RNG state, sweep number, aux field config\n/meas_eqlt/    # Equal-time measurements (n_sample, sign, den, ...)\n/meas_uneqlt/  # Unequal-time measurements (optional)\n```\n\n## Queue System Internals\n\nThe sharded queue uses:\n- 128 shards to avoid lock contention on distributed filesystems\n- Atomic `rename()` operations for task claiming\n- Symlinks moved: `todo/` -> `running/` -> `done/`\n- Checkpointed jobs returned to `todo/` for resumption\n"},"lastSynced":"2026-03-06T06:43:05.241Z","agentAnalysis":{"suitability":{"en":"Perfect for Physics and Materials Science Agents needing advanced simulations with unequal-time measurements and analytic continuation.","zh":"非常适合需要高级模拟的物理和材料科学代理，特别是需要不等时间测量和解析续的模拟。","ja":"物理と材料科学エージェントが、解析継続と等時でない測定を必要とする高度なシミュレーションに最適です。","ko":"불일치 시간 측정을 포함한 고급 시뮬레이션이 필요한 물리학 및 재료과학 에이전트에게 적합합니다.","es":"Perfecto para agentes de Física y Ciencia de Materiales que necesitan simulaciones avanzadas con mediciones de tiempo desigual y continuación analítica.","fr":"Idéal pour les agents de Physique et de Science des Matériaux nécessitant des simulations avancées avec des mesures de temps inégales et une continuation analytique.","de":"Perfekt für Physik- und Materialwissenschaftsagenten, die erweiterte Simulationen mit ungleichzeitigen Messungen und analytischer Fortsetzung benötigen.","pt":"Perfeito para Agentes de Física e Ciência de Materiais que necessitam de simulações avançadas com medições de tempo desigual e continuação analítica.","ru":"Идеально подходит для агентов физики и материаловедения, которым необходимы продвинутые симуляции с неравным временем измерений и аналитическим продолжением.","ar":"مثالي لوكلاء الفيزياء وعلوم المواد الذين يحتاجون إلى محاكاة متقدمة مع قياسات زمنية غير متساوية واستمرارية تحليلية."},"recommendation":{"en":"Empowers agents to perform complex time-dependent correlation function analysis and zero-frequency susceptibility calculations using maximum entropy methods for analytic continuation, enabling advanced research in fields like condensed matter physics.","zh":"赋予代理执行复杂的时依赖相关函数分析和零频率易感性计算，使用最大熵方法进行解析续，实现凝聚态物理等领域的高级研究。","ja":"エージェントが複雑な時間依存の相関関数分析と零周波数の感受性計算を実行できるようにし、解析継続のための最大エントロピー法を使用して、凝縮物質物理学などの研究を促進します。","ko":"에이전트가 복잡한 시간 의존 상관 함수 분석 및 0주파수 감수성 계산을 수행할 수 있게 하여 최대 엔트로피 방법을 사용하여 분석 연속을 수행하고, 응집 물질 물리학 등 분야의 고급 연구를 가능하게 합니다.","es":"Permite a los agentes realizar análisis complejos de funciones de correlación dependientes del tiempo y cálculos de susceptibilidad de frecuencia cero utilizando métodos de entropía máxima para la continuación analítica, lo que permite investigaciones avanzadas en campos como la física de la materia condensada.","fr":"Permet aux agents d''effectuer des analyses complexes de fonctions de corrélation dépendantes du temps et des calculs de susceptibilité à fréquence nulle en utilisant des méthodes d''entropie maximale pour la continuation analytique, permettant ainsi des recherches avancées dans des domaines comme la physique de la matière condensée.","de":"Ermöglicht es Agenten, komplexe Analysen von zeitabhängigen Korrelationsfunktionen und Berechnungen der Nullfrequenzsuszeptibilität unter Verwendung von Maximum-Entropie-Methoden für die analytische Fortsetzung durchzuführen, wodurch fortschrittliche Forschung in Bereichen wie der Physik der kondensierten Materie ermöglicht wird.","pt":"Habilita os agentes a realizarem análises complexas de funções de correlação dependentes do tempo e cálculos de suscetibilidade de frequência zero usando métodos de entropia máxima para continuação analítica, permitindo pesquisas avançadas em campos como a física da matéria condensada.","ru":"Позволяет агентам выполнять сложный анализ временно-зависимых корреляционных функций и расчеты нулевой частотной восприимчивости с использованием методов максимальной энтропии для аналитического продолжения, что позволяет проводить продвинутые исследования в областях, таких как физика конденсированного состояния.","ar":"يمنح الوكلاء khảية إجراء تحليلات معقدة لدوال الارتباط التابعة للزمن وحسابات القابلية للتأثر بترددات صفرية باستخدام أساليب الإントروبيا القصوى للاستمرارية التحليلية، مما يُمكن البحث المتقدم في مجالات مثل فيزياء المواد المكثفة."},"useCases":{"en":["Automating unequal-time measurement simulations for accurate susceptibility calculations","Generating time-dependent correlation functions for advanced materials analysis","Debugging runtime and memory usage issues in dqmc simulations"],"zh":["自动执行不等时间测量模拟以进行准确的易感性计算","生成时依赖相关函数以进行高级材料分析","调试dqmc模拟中的运行时和内存使用问题"],"ja":["等時でない測定のシミュレーションを自動化して正確な感受性計算を実行する","時間依存の相関関数を生成して高度な材料分析を実行する","dqmcシミュレーションの実行時とメモリ使用の問題をデバッグする"],"ko":["불일치 시간 측정 시뮬레이션을 자동화하여 정확한 감수성 계산을 수행하는 것","시간 의존 상관 함수를 생성하여 고급 재료 분석을 수행하는 것","dqmc 시뮬레이션의 실행 시간과 메모리 사용 문제를 디버깅하는 것"],"es":["Automatizar simulaciones de mediciones de tiempo desigual para cálculos de susceptibilidad precisos","Generar funciones de correlación dependientes del tiempo para análisis de materiales avanzados","Depurar problemas de tiempo de ejecución y uso de memoria en simulaciones dqmc"],"fr":["Automatiser les simulations de mesures de temps inégales pour des calculs de susceptibilité précis","Générer des fonctions de corrélation dépendantes du temps pour l''analyse avancée des matériaux","Déboguer les problèmes de temps d''exécution et d''utilisation de la mémoire dans les simulations dqmc"],"de":["Automatisierung von Simulatoren für ungleichzeitige Messungen zur genauen Berechnung der Suszeptibilität","Generierung von zeitabhängigen Korrelationsfunktionen für erweiterte Materialanalysen","Fehlerbehebung bei Laufzeit- und Speicherproblemen in dqmc-Simulationen"],"pt":["Automatizar simulações de medições de tempo desigual para cálculos de suscetibilidade precisos","Gerar funções de correlação dependentes do tempo para análise de materiais avançada","Depurar problemas de uso de tempo de execução e memória em simulações dqmc"],"ru":["Автоматизировать симуляции неравных времен измерений для точных расчетов восприимчивости","Генерировать временно-зависимые корреляционные функции для продвинутого анализа материалов","Отладить проблемы использования времени выполнения и памяти в симуляциях dqmc"],"ar":["تأتمة محاكاة قياسات زمنية غير متساوية لتحسابات قابلية دقيقة","توليد دوال ارتباط تعتمد على الزمن لتحليل متقدم للمواد","تصحيح أخطاء استخدام وقت التشغيل وذاكرة التخزين في محاكاة dqmc"]},"limitations":{"en":["Significantly increases runtime and memory usage due to unequal-time measurements","Requires specific configuration settings, such as `period_uneqlt > 0`"],"zh":["由于不等时间测量，运行时和内存使用量大大增加","需要特定的配置设置，例如 `period_uneqlt > 0`"],"ja":["等時でない測定により、実行時間とメモリ使用量が大幅に増加する","特定の設定が必要です。たとえば、`period_uneqlt > 0`"],"ko":["불일치 시간 측정으로 인해 실행 시간과 메모리 사용량이 크게 증가함","특정 구성 설정이 필요함. 예를 들어, `period_uneqlt > 0`"],"es":["Aumenta significativamente el tiempo de ejecución y el uso de memoria debido a las mediciones de tiempo desigual","Requiere ajustes de configuración específicos, como `period_uneqlt > 0`"],"fr":["Augmente considérablement le temps d''exécution et l''utilisation de la mémoire en raison des mesures de temps inégales","Nécessite des paramètres de configuration spécifiques, tels que `period_uneqlt > 0`"],"de":["Erhöht die Laufzeit und den Speicherbedarf aufgrund von ungleichzeitigen Messungen erheblich","Erfordert spezifische Konfigurationseinstellungen, wie z.B. `period_uneqlt > 0`"],"pt":["Aumenta significativamente o tempo de execução e o uso de memória devido às medições de tempo desigual","Requer configurações de configuração específicas, como `period_uneqlt > 0`"],"ru":["Значительно увеличивает время выполнения и использование памяти из-за неравных времен измерений","Требует специальных настроек конфигурации, таких как `period_uneqlt > 0`"],"ar":["يزيد بشكل كبير من وقت التشغيل واستخدام الذاكرة بسبب قياسات زمنية غير متساوية","يتطلب إعدادات تكوين محددة، مثل `period_uneqlt > 0`"]},"version":4},"contentHash":"a32db98cff4f5ebd0a83215f27c4dc5565f7b5b2c421c4f407cf49b5e7ebdfab","qualityScore":30}');
