INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('liveloveapp/hashbrown/ideate', 'ideate', 'liveloveapp', 'hashbrown', 'community', 'ideate liveloveapp hashbrown community Hashbrown是一款用于构建浏览器内运行的AI智能代理的框架，支持Angular和React Hashbrownは、ブラウザ内で実行されるAIエージェントを構築するためのフレームワークであり、AngularとReactをサポートしています Hashbrown은 브라우저 내에서 실행되는 AI 에이전트를 구축하기 위한 프레임워크이며 Angular 및 React를 지원합니다 Hashbrown es un framework para construir agentes que se ejecutan en el navegador, compatible con Angular y React Hashbrown est un framework pour construire des agents qui s''exécutent dans le navigateur, compatible avec Angular et React Hashbrown ist ein Framework zum Erstellen von Agenten, die im Browser ausgeführt werden, kompatibel mit Angular und React Hashbrown é um framework para construir agentes que rodam no navegador, compatível com Angular e React Hashbrown - это фреймворк для создания агентов, работающих в браузере, для Angular и React Hashbrown هو إطار للعمل مع وكلاء يعملون في المتصفح، مدعوم من Angular و React Hashbrown is a framework for building agents that run the browser. Built for Angular and React. AI智能代理 Hashbrown框架 Angular开发 React开发 AI工具 如何使用Hashbrown Hashbrown安装 AIエージェント开发教程 Hashbrown is a framework for building agents that run the browser. Built for Angular and React.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/iOS Localization & Assets', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'iOS Localization & Assets', 0, 0, 30, '2026-02-20T04:13:19.578Z', '2026-02-20T04:52:53.293Z', '92928cc653b564577a07486f7d841dd1b550a10036ceb5dd8e209a4d0a7660b6', '{"id":"HoangNguyen0403/agent-skills-standard/iOS Localization & Assets","name":"iOS Localization & Assets","description":{"zh":"iOS, String Catalogs .stringcatalog Xcode 15+.","ja":"iOS, String Catalogs .stringcatalog Xcode 15+.","ko":"iOS, String Catalogs .stringcatalog Xcode 15+.","es":"Estándares y mejores prácticas para la localización y los activos en iOS, incluyendo catálogos de cadenas y pluralización","fr":"Normes et bonnes pratiques pour la localisation et les ressources sur iOS, y compris les catalogues de chaînes et la pluralisation","de":"Standards und Best Practices für die Lokalisierung und Assets in iOS, einschließlich String-Katalogen und Pluralisierung","pt":"Aprenda a implementar localização e gerenciamento de ativos em projetos iOS de forma eficaz","ru":"Узнайте, как реализовать локализацию и управление активами в проектах iOS эффективно","ar":"تعرف على كيفية تنفيذ المحلية وإدارة الموارد في مشاريع آي أو إس بفعالية","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"iOS ","ja":"iOS","ko":"iOS ","es":"Estándares de localización y activos de iOS","fr":"Normes de localisation et de ressources iOS","de":"iOS-Lokalisierungs- und Asset-Standards","pt":"Padrões de Localização e Ativos iOS","ru":"Стандарты локализации и активов iOS","ar":"معايير المحلية والأصول آي أو إس","en":"iOS Localization & Assets"},"description":{"zh":"iOS, String Catalogs .stringcatalog Xcode 15+.","ja":"iOS, String Catalogs .stringcatalog Xcode 15+.","ko":"iOS, String Catalogs .stringcatalog Xcode 15+.","es":"Estándares y mejores prácticas para la localización y los activos en iOS, incluyendo catálogos de cadenas y pluralización","fr":"Normes et bonnes pratiques pour la localisation et les ressources sur iOS, y compris les catalogues de chaînes et la pluralisation","de":"Standards und Best Practices für die Lokalisierung und Assets in iOS, einschließlich String-Katalogen und Pluralisierung","pt":"Aprenda a implementar localização e gerenciamento de ativos em projetos iOS de forma eficaz","ru":"Узнайте, как реализовать локализацию и управление активами в проектах iOS эффективно","ar":"تعرف على كيفية تنفيذ المحلية وإدارة الموارد في مشاريع آي أو إس بفعالية","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and p..."},"definition":{"en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"features":{"zh":["String Catalogs .stringcatalog","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization"],"ja":["String Catalogs .stringcatalog","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization"],"ko":["String Catalogs .stringcatalog","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization"],"es":["Catálogos de cadenas para localización","Implementación nativa de localización","Pluralización con catálogos de cadenas","Soporte para Xcode 15+","Mejores prácticas para la localización de aplicaciones"],"fr":["Catalogues de chaînes pour la localisation","Implémentation native de la localisation","Pluralisation avec les catalogues de chaînes","Prise en charge de Xcode 15+","Bonnes pratiques pour la localisation des applications"],"de":["String-Kataloge für Lokalisierung","Native Implementierung der Lokalisierung","Pluralisierung mit String-Katalogen","Unterstützung für Xcode 15+","Best Practices für die Lokalisierung von Anwendungen"],"pt":["Uso de catálogos de strings para localização","Implementação nativa de localização","Suporte a pluralização","Uso de recursos de localização","Gerenciamento de ativos em Xcode","Melhores práticas para localização em iOS"],"ru":["Использование каталогов строк для локализации","Нативная реализация локализации","Поддержка pluralизации","Использование ресурсов локализации","Управление активами в Xcode","Лучшие практики локализации в iOS"],"ar":["استخدام كتالوجات السلاسل لتحويل اللغة المحلية","تنفيذ اللغة المحلية الأصلي","دعم التعددي","استخدام الموارد المحلية","إدارة الموارد في إكس كود","أفضل الممارسات لتحويل اللغة المحلية في آي أو إس"]},"keywords":{"zh":["iOS","String Catalogs","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization","iOS","iOS"],"ja":["iOS","String Catalogs","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization","iOS","iOS"],"ko":["iOS","String Catalogs","Xcode 15+","String(localized: )","LocalizedStringResource","pluralization","iOS","iOS"],"es":["localización de iOS","activos de iOS","catálogos de cadenas","pluralización","Xcode 15+","mejores prácticas de localización","desarrollo de aplicaciones móviles","iOS development"],"fr":["localisation sur iOS","ressources sur iOS","catalogues de chaînes","pluralisation","Xcode 15+","bonnes pratiques de localisation","développement d''applications mobiles","développement iOS"],"de":["Lokalisierung in iOS","Assets in iOS","String-Kataloge","Pluralisierung","Xcode 15+","Best Practices für Lokalisierung","Mobile App-Entwicklung","iOS-Entwicklung"],"pt":["localização iOS","ativos iOS","catálogos de strings","implementação nativa","pluralização","recursos de localização","Xcode","desenvolvimento iOS","melhores práticas"],"ru":["локализация iOS","активы iOS","каталоги строк","нативная реализация","pluralизация","ресурсы локализации","Xcode","разработка iOS","лучшие практики"],"ar":["المحلية آي أو إس","الأصول آي أو إس","كتالوجات السلاسل","تنفيذ اللغة المحلية الأصلي","التعددي","الموارد المحلية","إكس كود","تطوير آي أو إس","أفضل الممارسات"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"iOS Localization & Assets","description":"Standards for String Catalogs, L10n, and Asset Management.","bodyPreview":"# iOS Localization & Assets Standards\n\n## **Priority: P1**\n\n## Implementation Guidelines\n\n### Localization (L10n)\n\n- **String Catalogs (.stringcatalog)**: Use for primary localization in Xcode 15+. It provides a visual editor and compile-time checks for missing translations.\n- **Native Implementation**: Use `String(localized: \"key\")` or `LocalizedStringResource`. Avoid manual `NSLocalizedString` where possible.\n- **Pluralization**: Use String Catalogs'' built-in pluralization support instead of c","body":"# iOS Localization & Assets Standards\n\n## **Priority: P1**\n\n## Implementation Guidelines\n\n### Localization (L10n)\n\n- **String Catalogs (.stringcatalog)**: Use for primary localization in Xcode 15+. It provides a visual editor and compile-time checks for missing translations.\n- **Native Implementation**: Use `String(localized: \"key\")` or `LocalizedStringResource`. Avoid manual `NSLocalizedString` where possible.\n- **Pluralization**: Use String Catalogs'' built-in pluralization support instead of complex code logic.\n- **Formatting**: Use `Formatted` API for dates, numbers, and currencies to respect the user''s locale.\n\n### Asset Management\n\n- **Asset Catalogs (.xcassets)**: Keep assets organized. Use folders with \"Provides Namespace\" enabled for large projects.\n- **SF Symbols**: Use for standard icons to ensure consistency and accessibility.\n- **Vector Assets**: Use PDF or SVG and enable \"Preserve Vector Data\" for resolution independence.\n\n### Best Practices\n\n- **Hardcoded Strings**: Never use hardcoded strings in UI. Every user-facing string must be localized.\n- **Base Bundle**: Ensure `Base` localization is complete before adding other languages.\n\n## Anti-Patterns\n\n- **Manual String Formatting**: `**No manual currency symbol concat**: Use NumberFormatter or .formatted(.currency).`\n- **Loose Asset Files**: `**No loose png/jpg files in repo**: Always use Asset Catalogs.`\n- **Untranslated Keys**: `**No placeholder strings**: Ensure 100% coverage in String Catalogs.`\n\n## References\n\n- [L10n & Asset Organization](references/implementation.md)\n"},"lastSynced":"2026-02-20T04:52:53.293Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Agents focused on iOS development, seeking to streamline localization and asset management.","zh":"适用于专注于 iOS 开发的移动代理，旨在简化本地化和资产管理。","ja":"iOS 開発に焦点を当てたモバイル エージェントに適しています。ローカライズとアセット管理をストリームライン化することを目指しています。","ko":"iOS 개발에 중점을 둔 모바일 에이전트에게 적합합니다. 로컬라이제이션 및 자산 관리를 간소화하려는 경우에 사용됩니다.","es":"Ideal para agentes móviles centrados en el desarrollo de iOS, que buscan simplificar la localización y la gestión de activos.","fr":"Idéal pour les agents mobiles axés sur le développement iOS, cherchant à rationaliser la localisation et la gestion des ressources.","de":"Ideal für Mobile Agenten, die sich auf die iOS-Entwicklung konzentrieren und die Lokalisierung sowie die Ressourcenverwaltung rationalisieren möchten.","pt":"Ideal para Agentes Móveis focados no desenvolvimento do iOS, buscando otimizar a localização e o gerenciamento de ativos.","ru":"Идеально для мобильных агентов, ориентированных на разработку для iOS, стремящихся оптимизировать локализацию и управление активами.","ar":"مثالي للوكلاء المحمولين الذين يركزون على تطوير iOS ، يسعون لتبسيط الترجمة والتعامل مع الموارد."},"recommendation":{"en":"Empowers agents to implement efficient iOS localization using String Catalogs (.stringcatalog) and Native Implementation with `String(localized: key)` or `LocalizedStringResource`, while also handling pluralization and asset optimization.","zh":"赋予代理实现使用字符串目录 (.stringcatalog) 和本地实现 (`String(localized: key)` 或 `LocalizedStringResource`) 的高效 iOS 本地化能力，同时处理复数和资产优化。","ja":"エージェントに、String Catalogs (.stringcatalog) とネイティブ実装 (`String(localized: key)` または `LocalizedStringResource`) を使用して効率的な iOS ローカライズを実装する能力を付与します。複数化とアセットの最適化も処理します。","ko":"에이전트에게 문자열 카탈로그 (.stringcatalog) 및 네이티브 구현 (`String(localized: key)` 또는 `LocalizedStringResource`)을 사용하여 효율적인 iOS 로컬라이제이션을 구현할 수 있는 능력을 부여합니다. 복수 및 자산 최적화를 처리합니다.","es":"Permite a los agentes implementar una localización de iOS eficiente utilizando Catálogos de cadenas (.stringcatalog) y Implementación nativa con `String(localized: key)` o `LocalizedStringResource`, y también manejar la pluralización y la optimización de activos.","fr":"Permet aux agents de mettre en œuvre une localisation iOS efficace en utilisant des catalogues de chaînes (.stringcatalog) et une implémentation native avec `String(localized: key)` ou `LocalizedStringResource`, tout en gérant la pluralisation et l''optimisation des ressources.","de":"Ermöglicht es Agenten, eine effiziente iOS-Lokalisierung mithilfe von Zeichenfolgenkatalogen (.stringcatalog) und nativer Implementierung mit `String(localized: key)` oder `LocalizedStringResource` umzusetzen, und gleichzeitig die Pluralisierung und Ressourcenoptimierung zu handhaben.","pt":"Permite que os agentes implementem uma localização eficiente do iOS usando Catálogos de Cadeias de Caracteres (.stringcatalog) e Implementação Nativa com `String(localized: key)` ou `LocalizedStringResource`, além de lidar com a pluralização e a otimização de ativos.","ru":"Позволяет агентам реализовать эффективную локализацию для iOS, используя Каталоги строк (.stringcatalog) и Родную реализацию с `String(localized: key)` или `LocalizedStringResource`, а также обработку множественного числа и оптимизацию активов.","ar":"تمكّن الوكلاء من تنفيذ ترجمة iOS فعالة باستخدام كتالوجات السلاسل المحلية (.stringcatalog) والتنفيذ المحلي باستخدام `String(localized: key)` أو `LocalizedStringResource` ، بالإضافة إلى التعامل مع التعدّدية وتنظيم الموارد."},"useCases":{"en":["Implementing robust localization for iOS apps using Xcode 15+","Automating asset management for diverse iOS projects","Debugging localization issues with compile-time checks for missing translations"],"zh":["使用 Xcode 15+ 实现强大的 iOS 应用程序本地化","自动化多样化的 iOS 项目的资产管理","使用编译时检查调试本地化问题（缺失翻译）"],"ja":["Xcode 15+ を使用して堅牢な iOS アプリのローカライズを実装する","多様な iOS プロジェクトのアセット管理を自動化する","コンパイル時チェックを使用してローカライズの問題（翻訳不足）をデバッグする"],"ko":["Xcode 15+를 사용하여 강력한 iOS 애플리케이션 로컬라이제이션 구현","다양한 iOS 프로젝트의 자산 관리 자동화","컴파일 타임 체크를 사용하여 로컬라이제이션 문제(번역되지 않은 항목) 디버깅"],"es":["Implementar una localización robusta para aplicaciones de iOS con Xcode 15+","Automatizar la gestión de activos para proyectos de iOS diversos","Depurar problemas de localización con comprobaciones de tiempo de compilación para traducciones que faltan"],"fr":["Mettre en œuvre une localisation robuste pour les applications iOS avec Xcode 15+","Automatiser la gestion des ressources pour les projets iOS divers","Déboguer les problèmes de localisation avec des vérifications à compile-time pour les traductions manquantes"],"de":["Eine robuste Lokalisierung für iOS-Apps mit Xcode 15+ umzusetzen","Die Ressourcenverwaltung für verschiedene iOS-Projekte zu automatisieren","Lokalisierungsprobleme mit Compile-Time-Checks für fehlende Übersetzungen zu debuggen"],"pt":["Implementação de localização robusta para aplicativos do iOS usando o Xcode 15+","Automação do gerenciamento de ativos para projetos do iOS diversificados","Depuração de problemas de localização com verificação de tempo de compilação para traduções ausentes"],"ru":["Реализация устойчивой локализации для приложений iOS с помощью Xcode 15+","Автоматизация управления активами для различных проектов iOS","Отладка проблем локализации с проверкой во время компиляции на отсутствующие переводы"],"ar":["تنفيذ ترجمة قوية لبرامج iOS باستخدام Xcode 15+","توسيط إدارة الموارد لتطبيقات iOS متنوعة","تصحيح أخطاء الترجمة باستخدام فحص وقت الترجمة للترجمات المفقودة"]},"limitations":{"en":["Requires Xcode 15+ for String Catalogs","Native Implementation limited to Swift and iOS frameworks","Manual NSLocalizedString usage discouraged"],"zh":["需要 Xcode 15+ 才能使用字符串目录","本地实现仅限于 Swift 和 iOS 框架","手动使用 NSLocalizedString 不推荐"],"ja":["String Catalogs を使用するには Xcode 15+ が必要","ネイティブ実装は Swift と iOS フレームワークに限定される","NSLocalizedString の手動使用は非推奨"],"ko":["문자열 카탈로그를 사용하려면 Xcode 15+ 필요","네이티브 구현은 스위프트 및 iOS 프레임워크로 제한됨","NSLocalizedString의 수동 사용은 비추천"],"es":["Requiere Xcode 15+ para Catálogos de cadenas","La Implementación nativa está limitada a Swift y marcos de iOS","Se desaconseja el uso manual de NSLocalizedString"],"fr":["Nécessite Xcode 15+ pour les catalogues de chaînes","L''implémentation native est limitée à Swift et aux frameworks iOS","L''utilisation manuelle de NSLocalizedString est déconseillée"],"de":["Benötigt Xcode 15+ für Zeichenfolgenkataloge","Die native Implementierung ist auf Swift und iOS-Frameworks beschränkt","Die manuelle Verwendung von NSLocalizedString wird nicht empfohlen"],"pt":["Exige Xcode 15+ para Catálogos de Cadeias de Caracteres","Implementação Nativa limitada ao Swift e às estruturas do iOS","Uso manual de NSLocalizedString desencorajado"],"ru":["Требует Xcode 15+ для Каталогов строк","Родная реализация ограничена Swift и фреймворками iOS","Ручное использование NSLocalizedString не рекомендуется"],"ar":["يتطلب Xcode 15+ لكتالوجات السلاسل","التنفيذ المحلي مقيد بالسويفت وإطارات العمل الخاصة ببرامج iOS","استخدام NSLocalizedString يدوياً غير مشجع"]},"version":3},"contentHash":"92928cc653b564577a07486f7d841dd1b550a10036ceb5dd8e209a4d0a7660b6","qualityScore":30}');
