INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/iOS Dependency Injection', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'iOS Dependency Injection', 0, 0, 30, '2026-02-20T04:13:19.578Z', '2026-02-20T04:55:24.126Z', 'e2e2907b0582d740408cf2106b0fffabdacafd2304b89ca7f98aa9571c5a2bd5', '{"id":"HoangNguyen0403/agent-skills-standard/iOS Dependency Injection","name":"iOS Dependency Injection","description":{"zh":"iOS,Protocol-Based DI,Modern Property Wrappers","ja":"iOS,Protocol-Based DI,Modern Property Wrappers","ko":"iOS,Protocol-Based DI,Modern Property Wrappers","es":"La inyección de dependencias en iOS es una técnica de programación que permite una mayor flexibilidad y reutilización de código. Nuestro enfoque proporciona una guía detallada para implementar esta técnica de manera efectiva","fr":"L''injection de dépendances dans iOS est une technique de programmation qui permet une plus grande flexibilité et réutilisation de code. Notre approche fournit un guide détaillé pour mettre en œuvre cette technique de manière efficace","de":"Die Abhängigkeitsinjektion in iOS ist eine ProgrammierTechnik, die eine größere Flexibilität und Wiederverwendbarkeit von Code ermöglicht. Unser Ansatz bietet eine detaillierte Anleitung zur effektiven Implementierung dieser Technik","pt":"Injeção de dependência em iOS é uma técnica para gerenciar dependências entre objetos, melhorando a testabilidade e manutenção do código.","ru":"Внедрение зависимостей в iOS - это техника для управления зависимостями между объектами, улучшающая тестируемость и поддержку кода.","ar":"حقن التبعية في iOS هو تقنية لتدبير التبعيات بين الكائنات، مما يحسن من قابليتها للتجريبและการصيانة","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"iOS ","ja":"iOS","ko":"iOS ","es":"Inyección de Dependencias en iOS","fr":"Injection de Dépendances iOS","de":"iOS Abhängigkeitsinjektion","pt":"Injeção de Dependência iOS","ru":"Внедрение зависимостей в iOS","ar":"حقن التبعية في iOS","en":"iOS Dependency Injection"},"description":{"zh":"iOS,Protocol-Based DI,Modern Property Wrappers","ja":"iOS,Protocol-Based DI,Modern Property Wrappers","ko":"iOS,Protocol-Based DI,Modern Property Wrappers","es":"La inyección de dependencias en iOS es una técnica de programación que permite una mayor flexibilidad y reutilización de código. Nuestro enfoque proporciona ...","fr":"L''injection de dépendances dans iOS est une technique de programmation qui permet une plus grande flexibilité et réutilisation de code. Notre approche fourni...","de":"Die Abhängigkeitsinjektion in iOS ist eine ProgrammierTechnik, die eine größere Flexibilität und Wiederverwendbarkeit von Code ermöglicht. Unser Ansatz biete...","pt":"Injeção de dependência em iOS é uma técnica para gerenciar dependências entre objetos, melhorando a testabilidade e manutenção do código.","ru":"Внедрение зависимостей в iOS - это техника для управления зависимостями между объектами, улучшающая тестируемость и поддержку кода.","ar":"حقن التبعية في iOS هو تقنية لتدبير التبعيات بين الكائنات، مما يحسن من قابليتها للتجريبและการصيانة","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and p..."},"definition":{"en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"features":{"zh":["Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"ja":["Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"ko":["Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"es":["Inyección de dependencias basada en protocolos","Uso de inicializadores para pasar dependencias","Inyección de abstracciones en lugar de clases concretas","Uso de la biblioteca Factory para una inyección de dependencias ligera","Integración con Swinject para contenedores de grado empresarial"],"fr":["Injection de dépendances basée sur les protocoles","Utilisation d''initialiseurs pour passer les dépendances","Injection d''abstractions au lieu de classes concrètes","Utilisation de la bibliothèque Factory pour une injection de dépendances légère","Intégration avec Swinject pour des conteneurs de grade entreprise"],"de":["Abhängigkeitsinjektion basierend auf Protokollen","Verwendung von Initialisierern zum Übergeben von Abhängigkeiten","Injektion von Abstraktionen anstelle von konkreten Klassen","Verwendung der Factory-Bibliothek für eine leichte Abhängigkeitsinjektion","Integration mit Swinject für Containern im Unternehmensbereich"],"pt":["Injeção de dependência baseada em protocolos","Injeção de inicializadores","Uso de abstrações para facilitar testes","Uso da biblioteca Factory para injeção de dependência","Uso da biblioteca Swinject para contêineres de dependência"],"ru":["Внедрение зависимостей на основе протоколов","Внедрение инициализаторов","Использование абстракций для облегчения тестирования","Использование библиотеки Factory для внедрения зависимостей","Использование библиотеки Swinject для контейнеров зависимостей"],"ar":["حقن التبعية المستندة إلى البروتوكولات","حقن المُبادئ","استخدام التstractions لتسهيل الاختبارات","استخدام مكتبة Factory لحقن التبعية","استخدام مكتبة Swinject لحاويات التبعية"]},"keywords":{"zh":["iOS","Dependency Injection","Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"ja":["iOS","Dependency Injection","Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"ko":["iOS","Dependency Injection","Protocol-Based DI","Modern Property Wrappers","Initializer Injection","Factory","Swinject"],"es":["inyección de dependencias","iOS","programación","diseño de software","protocolos","inicializadores","abstracciones","Factory","Swinject"],"fr":["injection de dépendances","iOS","programmation","conception de logiciel","protocoles","initialiseurs","abstractions","Factory","Swinject"],"de":["Abhängigkeitsinjektion","iOS","Programmierung","Software-Design","Protokolle","Initialisierer","Abstraktionen","Factory","Swinject"],"pt":["injeção de dependência ios","desenvolvimento de software ios","padrões de design de software","testabilidade de código","manutenção de código","injeção de dependência baseada em protocolos"],"ru":["внедрение зависимостей ios","разработка программного обеспечения ios","паттерны проектирования программного обеспечения","тестируемость кода","поддержка кода","внедрение зависимостей на основе протоколов"],"ar":["حقن التبعية ios","تطوير البرمجيات ios","أنماط تصميم البرمجيات","قابلية الاختبار","صيانة الكود","حقن التبعية المستندة إلى البروتوكولات"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"iOS Dependency Injection","description":"Standards for Protocol-based DI, Property Wrappers, and Factory/Needle.","bodyPreview":"# iOS Dependency Injection Standards\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Protocol-Based DI (Manual)\n\n- **Initializer Injection**: Preferred method. Pass dependencies through `init`.\n- **Abstractions**: Inject protocols instead of concrete classes to facilitate testing (Mocks/Stubs).\n\n### Modern Property Wrappers (Factory/Resolver)\n\n- **Factory**: Use the `Factory` library for lightweight, type-safe navigation-friendly DI.\n- **Swinject**: Use for enterprise-grade container-bas","body":"# iOS Dependency Injection Standards\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Protocol-Based DI (Manual)\n\n- **Initializer Injection**: Preferred method. Pass dependencies through `init`.\n- **Abstractions**: Inject protocols instead of concrete classes to facilitate testing (Mocks/Stubs).\n\n### Modern Property Wrappers (Factory/Resolver)\n\n- **Factory**: Use the `Factory` library for lightweight, type-safe navigation-friendly DI.\n- **Swinject**: Use for enterprise-grade container-based DI in large modular projects.\n- **Injected**: Use `@Injected` property wrappers for cleaner syntax in ViewModels.\n\n### Scoping\n\n- **Singleton**: Use for app-wide services (Auth, Network, Database).\n- **Unique/Transient**: Default for ViewModels and temporary workers.\n- **Graph/Cached**: Use for shared data within a specific feature flow (Coordinator scope).\n\n## Anti-Patterns\n\n- **Singletitis**: `**No global Shared singleton access everywhere**: Inject the service via initializer.`\n- **Service Locator**: `**No Resolver.resolve() inside logic**: Pass dependency via constructor or property wrapper.`\n- **Concrete Dependency**: `**No direct class instantiation**: Depend on protocols for testability.`\n\n## References\n\n- [Manual & Library DI Setup](references/implementation.md)\n"},"lastSynced":"2026-02-20T04:55:24.126Z","agentAnalysis":{"suitability":{"en":"Perfect for Swift-based AI Agents needing robust iOS app development with Dependency Injection frameworks like Factory and Swinject.","zh":"非常适合需要在iOS应用开发中使用依赖注入框架（如Factory和Swinject）的Swift-based AI代理","ja":"SwiftベースのAIエージェントがiOSアプリ開発で依存性注入フレームワーク（FactoryやSwinjectなど）を使用する場合に最適","ko":"Swift 기반 AI 에이전트가 iOS 애플리케이션 개발에서 디펜던시 인젝션 프레임워크(예: Factory 및 Swinject)를 사용해야 하는 경우에 적합","es":"Perfecto para agentes de inteligencia artificial basados en Swift que necesitan un desarrollo de aplicaciones de iOS robusto con marcos de inyección de dependencias como Factory y Swinject.","fr":"Parfait pour les agents d''intelligence artificielle basés sur Swift qui nécessitent un développement d''applications iOS robuste avec des frameworks d''injection de dépendances tels que Factory et Swinject.","de":"Perfekt für auf Swift basierende KI-Agents, die eine robuste iOS-App-Entwicklung mit Abhängigkeitsinjektionsframeworks wie Factory und Swinject benötigen.","pt":"Perfeito para Agentes de IA baseados em Swift que precisam de desenvolvimento de aplicativos iOS robusto com frameworks de Injeção de Dependência como Factory e Swinject.","ru":"Идеально для агентов ИИ на основе Swift, которым требуется надежная разработка приложений iOS с фреймворками внедрения зависимостей, такими как Factory и Swinject.","ar":"مثالي لعمليات وكيل ذكاء اصطناعي التي تعتمد على سويفت وتحتاج إلى تطوير تطبيقات آي أو إس قوي مع إطارات حقن التبعية مثل Factory و Swinject."},"recommendation":{"en":"Empowers agents to implement protocol-based Dependency Injection using initializer injection and abstractions, while also leveraging Modern Property Wrappers such as Factory and Swinject for enterprise-grade container-based DI, facilitating testing with mocks and stubs.","zh":"使代理能够使用初始化注入和抽象实现基于协议的依赖注入，同时利用现代属性包装器（如Factory和Swinject）进行企业级的容器式依赖注入，方便使用模拟和存根进行测试","ja":"エージェントがイニシャライザ注入と抽象を使用してプロトコルベースの依存性注入を実装できるようにし、FactoryやSwinjectなどのモダンなプロパティラッパーを使用してエンタープライズグレードのコンテナベースのDIを実現し、モックとスタブを使用したテストを容易にします","ko":"에이전트가 초기화 삽입 및 추상화를 사용하여 프로토콜 기반 의존성 주입을 구현할 수 있도록 하며, Factory 및 Swinject와 같은 최신 속성 래퍼를 사용하여 엔터프라이즈급의 컨테이너 기반 DI를 구현하여 모의 및 스텁을 사용한 테스트를容易하게 합니다","es":"Habilita a los agentes a implementar inyección de dependencias basada en protocolos utilizando inyección de inicializadores y abstracciones, y también a aprovechar los Modern Property Wrappers como Factory y Swinject para un contenedor de nivel empresarial basado en DI, lo que facilita las pruebas con mocks y stubs.","fr":"Permet aux agents de mettre en œuvre l''injection de dépendances basée sur les protocoles en utilisant l''injection d''initialiseurs et des abstractions, tout en exploitant les Modern Property Wrappers tels que Factory et Swinject pour un conteneur de niveau entreprise basé sur le DI, facilitant ainsi les tests avec des mocks et des stubs.","de":"Ermächtigt die Agents, protokollbasierte Abhängigkeitsinjektion mithilfe von Initialisierungsinjektion und Abstraktionen zu implementieren und gleichzeitig moderne Eigenschaftswrapper wie Factory und Swinject für einen unternehmensgradigen, containerbasierten DI zu nutzen, wodurch das Testen mit Mocks und Stubs erleichtert wird.","pt":"Habilita os agentes a implementar Injeção de Dependência baseada em protocolo usando injeção de inicializador e abstrações, além de aproveitar Wrappers de Propriedade Modernas, como Factory e Swinject, para DI baseada em contêiner de nível empresarial, facilitando testes com mocks e stubs.","ru":"Наделяет агентов возможностью реализовать внедрение зависимостей на основе протоколов с использованием инъекции инициализатора и абстракций, а также использовать современные обертки свойств, такие как Factory и Swinject, для контейнерного внедрения зависимостей уровня предприятия, что облегчает тестирование с помощью макетов и заглушек.","ar":"تمكن الوكيل من تنفيذ حقن التبعية القائمة على البروتوكول باستخدام حقن المُشغل والتنقيحات ، بالإضافة إلى استخدام غلاف الملكية الحديث مثل Factory و Swinject لتحقيق حقن التبعية القائم على الحاويات درجات الشركات ، و تسهيل الاختبارات مع المزيف و النماذج."},"useCases":{"en":["Implementing protocol-based Dependency Injection for iOS apps","Configuring initializer injection for dependencies","Utilizing Factory and Swinject for type-safe navigation-friendly DI"],"zh":["为iOS应用实现基于协议的依赖注入","配置依赖的初始化注入","使用Factory和Swinject进行类型安全的导航友好DI"],"ja":["iOSアプリのプロトコルベースの依存性注入の実装","依存関係のイニシャライザ注入の構成","FactoryやSwinjectを使用したタイプセーフなナビゲーションに優しいDI"],"ko":["iOS 애플리케이션의 프로토콜 기반 의존성 주입 구현","의존성 초기화 삽입 구성","Factory 및 Swinject를 사용한 유형 안전导航 친화적 DI"],"es":["Implementar inyección de dependencias basada en protocolos para aplicaciones de iOS","Configurar inyección de inicializadores para dependencias","Utilizar Factory y Swinject para un DI de tipo seguro y amigable con la navegación"],"fr":["Mettre en œuvre l''injection de dépendances basée sur les protocoles pour les applications iOS","Configurer l''injection d''initialiseurs pour les dépendances","Utiliser Factory et Swinject pour un DI de type sécurisé et convivial pour la navigation"],"de":["Implementierung von protokollbasierter Abhängigkeitsinjektion für iOS-Anwendungen","Konfiguration von Initialisierungsinjektion für Abhängigkeiten","Verwendung von Factory und Swinject für einen typsicheren und navigationsfreundlichen DI"],"pt":["Implementação de Injeção de Dependência baseada em protocolo para aplicativos iOS","Configuração de injeção de inicializador para dependências","Utilização de Factory e Swinject para DI de navegação de tipo seguro"],"ru":["Реализация внедрения зависимостей на основе протоколов для приложений iOS","Настройка инъекции инициализатора для зависимостей","Использование Factory и Swinject для типа-безопасного внедрения зависимостей с навигацией"],"ar":["تنفيذ حقن التبعية القائمة على البروتوكول لتطبيقات آي أو إس","تكوين حقن المُشغل للتبعيات","استخدام Factory و Swinject لتحقيق حقن التبعية آمنة من النوع مع التوجيه"]},"limitations":{"en":["Requires Swift programming language","iOS platform only","Limited to Dependency Injection frameworks mentioned"],"zh":["需要Swift编程语言","仅限iOS平台","仅限于提到的依赖注入框架"],"ja":["Swiftプログラミング言語が必要","iOSプラットフォームのみ","依存性注入フレームワークは記載されたもののみ"],"ko":["Swift 프로그래밍 언어가 필요","iOS 플랫폼만 해당","의존성 주입 프레임워크는 언급된 것만 해당"],"es":["Requiere lenguaje de programación Swift","Solo plataforma iOS","Limitado a los marcos de inyección de dependencias mencionados"],"fr":["Nécessite le langage de programmation Swift","Plate-forme iOS uniquement","Limité aux frameworks d''injection de dépendances mentionnés"],"de":["Erfordert die Swift-Programmiersprache","Nur iOS-Plattform","Begrenzt auf die genannten Abhängigkeitsinjektionsframeworks"],"pt":["Exige a linguagem de programação Swift","Plataforma iOS apenas","Limitado a frameworks de Injeção de Dependência mencionados"],"ru":["Требует языка программирования Swift","Только платформа iOS","Ограничен фреймворками внедрения зависимостей, упомянутыми выше"],"ar":["يتطلب لغة برمجة سويفت","منصة آي أو إس فقط","محدود بإطارات حقن التبعية المذكورة"]},"version":3},"contentHash":"e2e2907b0582d740408cf2106b0fffabdacafd2304b89ca7f98aa9571c5a2bd5","qualityScore":30}');
