INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kks0488/vibe-claude/v-continue', 'community', 'kks0488', 'vibe-claude', 'kks0488/vibe-claude', 'v-continue', 0, 0, 30, '2026-03-06T12:59:22.248Z', '2026-03-06T14:37:15.858Z', 'c2752ba3475ef5cf434e10c2dc3fb01449346c1d84f337a3dde5cd2f4a58e7a2', '{"id":"kks0488/vibe-claude/v-continue","name":"v-continue","description":{"en":"v-continue is a self-evolving multi-agent system that resumes work from where the previous session left off, benefiting developers working with Claude Code. It parses work files, identifies pending tasks, and automatically continues from where you left off.","zh":"v-continue是一种自演化的多智能体系统，用于Claude Code。它可以自动续作上一次会话的工作","ja":"v-continueは、Claude Code用の自己進化型マルチエージェントシステムです。前回のセッションから自動的に作業を再開します","ko":"v-continue는 Claude Code용 自己 진화형 多智能体 시스템입니다. 이전 세션에서 자동으로 작업을 续行합니다","es":"v-continue es una herramienta de agente de inteligencia artificial que permite reanudar el trabajo desde donde se dejó. Funciona analizando el archivo de trabajo más reciente y continuando desde la última tarea pendiente.","fr":"v-continue est un outil d''agent d''intelligence artificielle qui permet de reprendre le travail où vous l''avez laissé. Il fonctionne en analysant le fichier de travail le plus récent et en reprenant à partir de la dernière tâche en attente.","de":"v-continue ist ein KI-Tool, das es ermöglicht, die Arbeit von wo aus Sie aufgehört haben fortzusetzen. Es funktioniert, indem es die aktuellste Arbeitsdatei analysiert und von der letzten ausstehenden Aufgabe fortsetzt.","pt":"O v-continue é um sistema de multi-agente que permite retomar o trabalho de onde parou, analisando arquivos e identificando tarefas pendentes","ru":"V-continue - это система многоагентного взаимодействия, которая позволяет возобновить работу с того места, где вы остановились, анализируя файлы и выявляя незавершенные задачи ИИ Аг