INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kks0488/vibe-claude/v-continue', 'v-continue', 'kks0488', 'vibe-claude', 'community', 'v-continue kks0488 vibe-claude community v-continue is a self-evolving multi-agent system that resumes work from where the previous session left off, benefiting developers working with Claude Code. It parses work files, identifies pending tasks, and automatically continues from where you left off. v-continue是一种自演化的多智能体系统，用于Claude Code。它可以自动续作上一次会话的工作 v-continueは、Claude Code用の自己進化型マルチエージェントシステムです。前回のセッションから自動的に作業を再開します v-continue는 Claude Code용 自己 진화형 多智能体 시스템입니다. 이전 세션에서 자동으로 작업을 续行합니다 v-continue es una herramienta de agente de inteligencia artificial que permite reanudar el trabajo desde donde se dejó. Funciona analizando el archivo de trabajo más reciente y continuando desde la última tarea pendiente. v-continue est un outil d''agent d''intelligence artificielle qui permet de reprendre le travail où vous l''avez laissé. Il fonctionne en analysant le fichier de travail le plus récent et en reprenant à partir de la dernière tâche en attente. v-continue ist ein KI-Tool, das es ermöglicht, die Arbeit von wo aus Sie aufgehört haben fortzusetzen. Es funktioniert, indem es die aktuellste Arbeitsdatei analysiert und von der letzten ausstehenden Aufgabe fortsetzt. O v-continue é um sistema de multi-agente que permite retomar o trabalho de onde parou, analisando arquivos e identificando tarefas pendentes V-continue - это система многоагентного взаимодействия, которая позволяет возобновить работу с того места, где вы остановились, анализируя файлы и выявляя незавершенные задачи ИИ Агентов v-continue هو نظام متعدد الوكلاء الذي يسمح باستئناف العمل من حيث توقفت، من خلال تحليل الملفات وتحديد المهام المعلقة لأدوات الذكاء الاصطناعي how to use v-continue v-continue setup guide v-continue alternative v-continue vs claude code what is v-continue v-continue install self-evolving multi-agent system claude code development workflow resume work from previous session v-continue AI智能工具 自动续作 Claude Code 多智能体系统 工作文件 实时更新 Finds the most recent .vibe/work-*.md file for seamless work resumption Parses work files to identify checked and unchecked items Automatically continues work from where the previous session left off using the /v-continue command Displays a summary of previous progress for context Supports real-time updates without requiring a separate session-state.md file v-continue is a skill that enables resuming work from the previous session, utilizing a self-evolving multi-agent system for Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Tiendil/donna/donna-do', 'community', 'Tiendil', 'donna', 'Tiendil/donna', 'donna-do', 11, 2, 29, '2026-03-05T20:18:45Z', '2026-03-07T12:49:07.268Z', '742eb2391d410d98455b23f11b029d8094bf85e82b8d594c1ecd3df9b53b1a97', '{"id":"Tiendil/donna/donna-do","name":"donna-do","description":{"en":"The donna-do skill enables developers to leverage deterministic behavior, state machines, and artifact management for their coding agents. It provides a robust framework for managing project artifacts and ensuring consistent execution.","zh":"Donna-Do 是一种编码代理技能，提供确定性行为、状态机管理和元编程功能，帮助开发者提高编码效率","ja":"Donna-Do は、決定性動作、状態マシン、メタプログラミングを提供する AI エージェント スキルです","ko":"Donna-Do는 결정적 행동, 상태 기계, 메타 프로그래밍을 제공하는 코딩 에이전트 스킬입니다","es":"donna-do es una habilidad para agentes de código que permite un comportamiento determinista, state machines y gestión de artefactos","fr":"donna-do est une compétence pour les agents de code qui permet un comportement déterministe, des machines d''état et une gestion d''artefacts","de":"donna-do ist eine Fähigkeit für Coding-Agents, die deterministisches Verhalten, State Machines und Artefaktverwaltung ermöglicht","pt":"O donna-do é uma habilidade que fornece comportamento determinístico, máquinas de estado e gerenciamento de artefatos para desenvolvedores","ru":"donna-do - это навык, который обеспечивает детерминированное поведение, машины состояния и управление артефактами для разработчиков","ar":"donna-do هو مهارة توفر سلوك محدد، آلات الحالة المتعلمة وإدارة الملفات القابلة للتنفيذ للمطورين"},"seo":{"title":{"en":"donna-do: Setup Guide for AI Agents | AI Agent Skill","zh":"Donna-Do 技术指南：确定性行为和状态机管理","ja":"Donna-Do Setup Guide: AIエージェントの決定性動作と状態マシン","ko":"Donna-Do 설정 가이드: 결정적 행동 및 상태 기계 관리","es":"Guía de configuración de donna-do para agentes de código","fr":"Guide de mise en place de donna-do pour les agen