INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MarjanDB/brrr-generator/slovenian-tax-edavki', 'slovenian-tax-edavki', 'MarjanDB', 'brrr-generator', 'community', 'slovenian-tax-edavki MarjanDB brrr-generator community edavki ibkr taxes The slovenian-tax-edavki skill generates tax reports for brokerage accounts, specifically designed for Slovenia''s Tax Authority. It benefits developers and financial professionals who need to automate tax reporting. Slovenian Tax EDavki AIエージェント用于生成税务报告，支持DOH_DIV等报告类型 Slovenian Tax EDavki AIエージェントは税務報告書を生成し、DOH_DIVなどの報告書タイプをサポート Slovenian Tax EDavki AI 툴은税務보고서를 생성하며DOH_DIV 등의 보고서 유형을 지원 EDavki es una herramienta de inteligencia artificial que genera informes de impuestos para la autoridad fiscal eslovena. Ofrece detalles específicos para Slovenia y tipos de informes como DOH_DIV EDavki est un outil d''intelligence artificielle qui génère des rapports d''impôts pour l''administration fiscale slovène. Il propose des détails spécifiques pour la Slovénie et des types de rapports tels que DOH_DIV EDavki ist ein KI-Tool, das Steuerberichte für die slowenische Finanzbehörde generiert. Es bietet spezifische Details für Slowenien und Berichtstypen wie DOH_DIV O skill de impostos esloveno EDavki gera relatórios de impostos para a autoridade fiscal eslovena. Ele usa tecnologias como pipeline-and-structure e infoproviders-lookup-data. Навык налогов Словении EDavki генерирует отчеты о налогах для налоговой службы Словении. Он использует технологии như pipeline-and-structure и infoproviders-lookup-data. مهارة الضريبة السلوفينية EDavki توليد تقارير ضريبية للسلطات الضريبية السلوفينية. إنها تستخدم تقنيات مثل pipeline-and-structure و infoproviders-lookup-data. how to use slovenian-tax-edavki slovenian-tax-edavki setup guide slovenian-tax-edavki alternative what is slovenian-tax-edavki slovenian-tax-edavki install slovenian-tax-edavki vs ibkr edavki tax reporting slovenian tax authority reporting Slovenian Tax EDavki AIエージェント 税务报告生成 DOH_DIV报告类型 TaxAuthorityProvider Edavki税务报告 IBKR税务报告 Python开发 CLI开发 AIエージェント Generates tax reports for Slovenia''s Tax Authority using EDavki-specific details Implements report types such as DOH_DIV for dividend income Utilizes TaxAuthorityProvider.TaxAuthorities.Slovenia.Schemas.ReportTypes.SlovenianTaxAuthorityReportTypes for report generation Supports pipeline-and-structure and infoproviders-lookup-data skills for enhanced functionality Provides Slovenian label and use information for each report type slovenian-tax-edavki is a skill that generates tax reports for Slovenia''s Tax Authority, utilizing specific details and schemas such as TaxAuthorityProvider.TaxAuthorities.Slovenia.Schemas.ReportTypes.SlovenianTaxAuthorityReportTypes');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Clyra-AI/gait/gait-capture-runpack', 'community', 'Clyra-AI', 'gait', 'Clyra-AI/gait', 'gait-capture-runpack', 6, 2, 29, '2026-02-24T13:23:46Z', '2026-03-06T06:52:35.369Z', '32d6c557241f41acaba739464cfca7338481a6b912ec86e451ba66f8ccbd6a73', '{"id":"Clyra-AI/gait/gait-capture-runpack","name":"gait-capture-runpack","description":{"en":"The gait-capture-runpack skill executes workflows to record artifacts safely and deterministically, benefiting AI agent developers and operators. It provides verifiable evidence of AI agent jobs in production.","zh":"Gait-Capture-Runpack 是一个离线优先的 AI 代理运行时，提供可验证的证据生成和确定性回归支持","ja":"Gait-Capture-Runpack はオフライン優先の AI エージェントランタイムで、検証可能な証拠生成と決定性回帰をサポート","ko":"Gait-Capture-Runpack은 오프라인 우선의 AI 에이전트 런타임으로, 검증 가능한 증거 생성과 결정적 회귀를 지원합니다","es":"Gait-capture-runpack es una habilidad que permite capturar y verificar la evidencia de ejecución de agentes de IA de manera segura y determinística. Proporciona una forma offline-first de ejecutar trabajos de agentes de IA","fr":"Gait-capture-runpack est une compétence qui permet de capturer et de vérifier les preuves d''exécution des outils d''IA de manière sécurisée et déterministe. Elle offre une façon de travailler offline-first pour les tâches d''outils d''IA","de":"Gait-capture-runpack ist eine Fähigkeit, die es ermöglicht, die Ausführung von KI-Agents sicher und deterministisch zu erfassen und zu verifizieren. Sie bietet eine offline-first-Methode zur Ausführung von KI-Aufgaben","pt":"O gait-capture-runpack é uma ferramenta para capturar artefatos de forma segura e determinística, ideal para triagem de incidentes e portas de CI.","ru":"Gait-capture-runpack - это инструмент для захвата артефактов в ИИ Агентах, обеспечивающий безопасность и детерминированность.","ar":"يُستخدم gait-capture-runpack لالتقاط الملفات الفنية بشكل آمن ومحدد، وهو مناسب لمعالجة الحوادث وبوابات CI"},"seo":{"title":{"en":"gait-capture-runpack: Verifiable Evidence for AI Agents |...","zh":"Gait-Capture-Runpack 技术指南：离线 AI 代理运行包捕获","ja":"Gait-Capture-Runpack の設定方法：オフライン AI エージェントのランパックキャプチャ","ko":"Gait-Capture-Runpack 설정 가이드: 오프라인 AI 에이전트 런팩 캡처","es":"Guía de configuración de gait-capture-runpack para agente...","fr":"Guide de mise en œuvre de gait-capture-runpack pour les o...","de":"Einrichtungsleitfaden für gait-capture-runpack bei KI-Agents","pt":"Guia de Configuração do gait-capture-runpack para Desenvo...","ru":"Настройка gait-capture-runpack: Руководство для разработч...","ar":"دليل إعداد gait-capture-runpack لتقنيين تطوير الإي آي"},"description":{"en":"Discover how gait-capture-runpack provides offline-first, signed, and verifiable evidence for AI agent jobs. Learn how to capture runpack artifacts safely an...","zh":"了解 Gait-Capture-Runpack 技术，实现离线 AI 代理运行包捕获和可验证证据生成","ja":"Gait-Capture-Runpack を使用してオフライン AI エージェントのランパックをキャプチャし、検証可能な証拠を生成する","ko":"Gait-Capture-Runpack 기술을 통해 오프라인 AI 에이전트 런팩을 캡처하고 검증 가능한 증거를 생성하세요","es":"Aprende a implementar gait-capture-runpack para capturar y verificar la evidencia de ejecución de agentes de IA de manera segura y determinística","fr":"Découvrez comment mettre en œuvre gait-capture-runpack pour capturer et vérifier les preuves d''exécution des outils d''IA de manière sécurisée et déterministe","de":"Erfahren Sie, wie Sie gait-capture-runpack implementieren, um die Ausführung von KI-Agents sicher und deterministisch zu erfassen und zu verifizieren","pt":"Aprenda a configurar o gait-capture-runpack para capturar e reproduzir artefatos de forma segura e determinística","ru":"Узнайте, как настроить gait-capture-runpack для захвата и воспроизведения артефактов в ИИ Агентах","ar":"تعرف على كيفية إعداد gait-capture-runpack لالتقاط وإعادة إنتاج الملفات الفنية بطريقة آمنة ومحددة"},"definition":{"en":"gait-capture-runpack is an offline-first runtime for AI agents that captures runpack artifacts and emits signed and verifiable evidence.","zh":"Gait-Capture-Runpack 是一种用于捕获和验证 AI 代理运行包的技术","ja":"Gait-Capture-Runpack は AI エージェントのランパックをキャプチャして検証する技術","ko":"Gait-Capture-Runpack은 AI 에이전트 런팩을 캡처하고 검증하는 기술입니다","es":"Gait-capture-runpack es una habilidad de agentes de IA que captura y verifica la evidencia de ejecución de manera segura y determinística","fr":"Gait-capture-runpack est une compétence d''outils d''IA qui capture et vérifie les preuves d''exécution de manière sécurisée et déterministe","de":"Gait-capture-runpack ist eine Fähigkeit von KI-Agents, die die Ausführung von KI-Aufgaben sicher und deterministisch erfasst und verifiziert","pt":"O gait-capture-runpack é uma ferramenta de captura de artefatos para AI Agents","ru":"Gait-capture-runpack - это инструмент захвата артефактов для ИИ Агентов","ar":"يُعرّف gait-capture-runpack بأنه أداة لالتقاط الملفات الفنية لتقنيات الإي آي"},"features":{"en":["Executes workflows to record artifacts safely and deterministically","Provides offline-first, signed, and verifiable evidence for AI agent jobs","Supports incident triage with captured run artifacts for reproduction","Enforces tool-boundary policy for secure AI agent execution","Emits signed and verifiable evidence artifacts for CI gate failures"],"zh":["离线优先的 AI 代理运行时","可验证的证据生成","确定性回归支持","工具边界策略执行","签名和验证证据生成"],"ja":["オフライン優先の AI エージェントランタイム","検証可能な証拠生成","決定性回帰サポート","ツールバウンダリポリシーの実行","署名と検証証拠生成"],"ko":["오프라인 우선의 AI 에이전트 런타임","검증 가능한 증거 생성","결정적 회귀 지원","도구 경계 정책 실행","서명 및 검증 증거 생성"],"es":["Ejecución offline-first de trabajos de agentes de IA","Emisión de artefactos firmados y verificables","Soporte para regresiones determinísticas","Captura de artefactos de manera segura y determinística","Verificación de la identidad y la integridad de los artefactos"],"fr":["Exécution offline-first des tâches d''outils d''IA","Émission d''artefacts signés et vérifiables","Prise en charge des régressions déterministes","Capture d''artefacts de manière sécurisée et déterministe","Vérification de l''identité et de l''intégrité des artefactos"],"de":["Offline-first-Ausführung von KI-Aufgaben","Ausgabe von signierten und überprüfbaren Artefakten","Unterstützung für deterministische Regressionsanalysen","Sichere und deterministische Erfassung von Artefakten","Verifizierung der Identität und Integrität von Artefakten"],"pt":["Execução de workflows offline-first","Emissão de artefatos assinados e verificáveis","Suporte a regressões determinísticas","Captura de artefatos para triagem de incidentes","Geração de recibos e evidências com base em metadados de runpack"],"ru":["Выполнение workflow в режиме offline-first","Выдача подписанных и верифицируемых артефактов","Поддержка детерминированных регрессий","Захват артефактов для расследования инцидентов","Генерация квитанций и доказательств на основе метаданных runpack"],"ar":["تشغيل سير عمل في وضع غير متصل","إصدار ملفات فنية موقعة ويمكن التحقق منها","دعم الانحدارات المحددة","التقاط الملفات الفنية لمعالجة الحوادث","توليد إيصالات والأدلة المعتمدة على بيانات تعريف الحزمة"]},"keywords":{"en":["how to use gait-capture-runpack","gait-capture-runpack setup guide","gait-capture-runpack alternative","gait-capture-runpack vs other AI agent runtimes","verifiable evidence for AI agents","offline-first AI agent runtime","incident triage with gait-capture-runpack","gait-capture-runpack install","gait-capture-runpack documentation"],"zh":["Gait-Capture-Runpack","AI 代理","离线优先","可验证证据","确定性回归","工具边界策略","AI 工具","AI 代理技术"],"ja":["Gait-Capture-Runpack","AI エージェント","オフライン優先","検証可能な証拠","決定性回帰","ツールバウンダリポリシー","AI エージェント技術","AI ツール"],"ko":["Gait-Capture-Runpack","AI 에이전트","오프라인 우선","검증 가능한 증거","결정적 회귀","도구 경계 정책","AI 에이전트 기술","AI 도구"],"es":["agentes de IA","gait-capture-runpack","ejecución offline-first","artefactos firmados","regresiones determinísticas","captura de artefactos","verificación de identidad","integridad de artefactos","desarrollo de IA"],"fr":["outils d''IA","gait-capture-runpack","exécution offline-first","artefacts signés","régressions déterministes","capture d''artefacts","vérification d''identité","intégrité des artefacts","développement d''IA"],"de":["KI-Agents","gait-capture-runpack","offline-first-Ausführung","signierte Artefakte","deterministische Regressionsanalysen","Erfassung von Artefakten","Verifizierung der Identität","Integrität von Artefakten","KI-Entwicklung"],"pt":["gait-capture-runpack","AI Agents","captura de artefatos","triagem de incidentes","portas de CI","desenvolvimento de software","ferramentas de AI","tecnologias de inteligência artificial"],"ru":["gait-capture-runpack","ИИ Агенты","захват артефактов","расследование инцидентов","ворота CI","разработка программного обеспечения","инструменты ИИ","технологии искусственного интеллекта"],"ar":["gait-capture-runpack","تقنيات الإي آي","التقاط الملفات الفنية","معالجة الحوادث","بوابات CI","تطوير البرمجيات","أدوات الإي آي","تقنيات الذكاء الاصطناعي"]}},"owner":"Clyra-AI","repo":"gait","repoPath":"Clyra-AI/gait","stars":6,"forks":2,"updatedAt":"2026-02-24T13:23:46Z","topics":[],"category":"community","skillMd":{"name":"gait-capture-runpack","description":"Capture and verify deterministic Gait runpacks from normalized run input. Use when asked to record a run, produce run_id or runpack artifacts, generate ticket-ready proof, or validate artifact integrity before handoff.","bodyPreview":"# Capture Runpack\n\nExecute this workflow to record an artifact safely and deterministically.\n\n## Gait Context\n\nGait is an offline-first runtime for AI agents that enforces tool-boundary policy, emits signed and verifiable evidence artifacts, and supports deterministic regressions.\n\nUse this skill when:\n- incident triage needs captured run artifacts for reproduction\n- CI gate failures need verifiable artifact identity and integrity\n- receipt/evidence generation depends on runpack metadata and dig","body":"# Capture Runpack\n\nExecute this workflow to record an artifact safely and deterministically.\n\n## Gait Context\n\nGait is an offline-first runtime for AI agents that enforces tool-boundary policy, emits signed and verifiable evidence artifacts, and supports deterministic regressions.\n\nUse this skill when:\n- incident triage needs captured run artifacts for reproduction\n- CI gate failures need verifiable artifact identity and integrity\n- receipt/evidence generation depends on runpack metadata and digests\n\nDo not use this skill when:\n- Gait CLI is unavailable in the environment\n- no Gait run input or artifact source is available\n\n## Workflow\n\n1. Validate required input path: `<run_record.json>`.\n2. Run record with JSON output (required):\n   - `gait run record --input <run_record.json> --json`\n3. Parse output fields:\n   - `ok`, `run_id`, `bundle`, `manifest_digest`, `ticket_footer`\n4. Verify artifact integrity (required):\n   - `gait verify <run_id_or_bundle_path> --json`\n5. Return a concise handoff block that includes:\n   - `run_id`\n   - `bundle`\n   - `manifest_digest`\n   - `ticket_footer`\n   - verify status\n\n## Safety Rules\n\n- Keep default capture mode as `reference`.\n- Do not switch to raw capture unless explicitly requested.\n- For replay workflows, prefer `gait run replay` (stub mode default); require explicit unsafe flags for real tool replay.\n- Do not invent `run_id`, digests, or verify results.\n- Treat non-zero exit from `gait run record` or `gait verify` as blocking errors.\n- Keep this skill wrapper-only: do not parse policy YAML or implement custom evaluator logic.\n\n## Determinism Rules\n\n- Always use `--json` and parse structured fields.\n- Do not rely on text-only output for workflow decisions.\n- Keep output grounded in recorded artifact values only.\n"},"lastSynced":"2026-03-06T06:52:35.369Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent Developers and Operators requiring verifiable evidence of AI agent jobs in production environments, particularly those utilizing Gait''s offline-first runtime.","zh":"适合需要在生产环境中验证AI代理作业的AI代理开发人员和运营人员，特别是那些使用Gait的离线优先运行时的环境","ja":"Gaitのオフライン优先ランタイムを使用する生産環境でのAIエージェントジョブの検証証拠が必要なAIエージェント開発者およびオペレーターに適しています","ko":"생산 환경에서 AI 에이전트 작업의 검증 증거가 필요한 AI 에이전트 개발자 및 운영 담당자에게 적합합니다. 특히 Gait의 오프라인 우선 실행 환경을 사용하는 경우에 적합합니다","es":"Ideal para desarrolladores y operadores de agentes de inteligencia artificial que requieren evidencia verificable de trabajos de agentes de inteligencia artificial en entornos de producción, particularmente aquellos que utilizan el entorno de ejecución offline-first de Gait.","fr":"Idéal pour les développeurs et les opérateurs d''agents d''intelligence artificielle nécessitant des preuves vérifiables d''emplois d''agents d''intelligence artificielle dans des environnements de production, en particulier ceux qui utilisent l''environnement d''exécution offline-first de Gait.","de":"Ideal für Entwickler und Betreiber von KI-Agenten, die verifizierbare Beweise für KI-Agentenjobs in Produktionsumgebungen benötigen, insbesondere solche, die die offline-first-Laufzeitumgebung von Gait nutzen.","pt":"Ideal para desenvolvedores e operadores de agentes de IA que exigem evidências verificáveis de trabalhos de agentes de IA em ambientes de produção, particularmente aqueles que utilizam o tempo de execução offline-first do Gait.","ru":"Идеально подходит для разработчиков и операторов агентов ИИ, требующих проверяемых доказательств работы агентов ИИ в производственных средах, в частности тех, которые используют офлайн-режим работы Gait.","ar":"مثالي لمطوري و مشغلي وكلاء الذكاء الاصطناعي الذين يتطلبون أدلة قابلة للتحقق من وظائف وكلاء الذكاء الاصطناعي في بيئات الإنتاج، خاصة تلك التي تستخدم وقت التشغيل غير المتصل الأول من Gait."},"recommendation":{"en":"Empowers agents to execute workflows that record artifacts safely and deterministically, providing signed and verifiable evidence artifacts through Gait''s tool-boundary policy, supporting deterministic regressions and CI gate failures analysis with verifiable artifact identity and integrity.","zh":"赋予代理执行工作流的能力，以安全且确定性的方式记录制品，并通过Gait的工具边界策略提供签名且可验证的制品证据，支持确定性回归和CI门控故障分析，并具有可验证的制品身份和完整性","ja":"エージェントにワークフローを実行させる能力を与え、安全かつ決定的にアーティファクトを記録し、Gaitのツール境界ポリシーによって署名された可検証アーティファクト証拠を提供し、決定性の回帰とCIゲート障害分析をサポートし、検証可能なアーティファクトのIDと整合性を提供する","ko":"에이전트가 안전하고 결정적으로 아티팩트를 기록하여 워크플ロー 실행을 가능하게 하며, Gait의 툴 경계 정책을 통해 서명된 검증 가능한 아티팩트 증거를 제공하여, 결정적 회귀 및 CI 게이트 실패 분석을 지원하며, 검증 가능한 아티팩트 ID 및 무결성을 제공합니다","es":"Habilita a los agentes a ejecutar flujos de trabajo que registran artefactos de manera segura y determinista, proporcionando artefactos de evidencia firmados y verificables a través de la política de límite de herramientas de Gait, lo que admite regresiones deterministas y análisis de fallos de puerta de CI con identidad y integridad de artefactos verificables.","fr":"Permet aux agents d''exécuter des flux de travail qui enregistrent des artefacts de manière sécurisée et déterministe, fournissant des artefacts de preuve signés et vérifiables via la politique de limite d''outils de Gait, ce qui prend en charge les régressions déterministes et l''analyse des défaillances de la porte de CI avec une identité et une intégrité d''artefact vérifiables.","de":"Ermächtigt Agenten, Workflows auszuführen, die Artefakte sicher und deterministisch aufzeichnen, indem sie durch die Tool-Grenzenpolitik von Gait signierte und verifizierbare Beweisartefakte bereitstellen, was deterministische Regressions- und CI-Tor-Fehleranalysen mit verifizierbarer Artefaktidentität und -integrität unterstützt.","pt":"Habilita os agentes a executar fluxos de trabalho que registram artefatos de forma segura e determinística, fornecendo artefatos de evidência assinados e verificáveis por meio da política de limite de ferramenta do Gait, suportando regressões determinísticas e análise de falhas de gate de CI com identidade e integridade de artefato verificável.","ru":"Наделяет агентов возможностью выполнять рабочие процессы, которые записывают артефакты безопасно и детерминированно, предоставляя подписанные и проверяемые артефакты доказательств через политику инструментального ограничения Gait, поддерживающую детерминированные регрессии и анализ неисправностей шлюза CI с проверяемой идентичностью и целостностью артефакта.","ar":"يمنح الوكلاء القدرة على تشغيل سلاسل من الأعمال التي تسجل الملفات الشخصية بأمان وباتجاه معين، وتوفر文件ات أدلة موقعة وقابلة للتحقق من خلال سياسة حدود الأداة من Gait، ودعم الانحدارات المتجهة وتحليل فشل بوابة CI مع هوية وسلامة ملفات قابلة للتحقق."},"useCases":{"en":["Capturing runpack metadata for incident triage and reproduction","Generating verifiable evidence for receipt and integrity validation","Debugging CI gate failures with deterministic artifact analysis"],"zh":["捕获运行包元数据以进行事件故障排除和重现","生成可验证证据以验证收据和完整性","使用确定性制品分析进行CI门控故障调试"],"ja":["インシデントのトライアジと再現のためにランパックメタデータをキャプチャする","受領と整合性の検証のための検証可能証拠を生成する","決定的なアーティファクト分析を使用してCIゲート障害をデバッグする"],"ko":["사건 재현을 위한 런패키지 메타데이터 캡처","수신 및 무결성 검증을 위한 검증 가능한 증거 생성","결정적 아티팩트 분석을 사용한 CI 게이트 故障 디버깅"],"es":["Captura de metadatos de runpack para triage y reproducción de incidentes","Generación de evidencia verificable para validación de recibo e integridad","Depuración de fallos de puerta de CI con análisis de artefactos deterministas"],"fr":["Capture de métadonnées de runpack pour triage et reproduction d''incidents","Génération de preuves vérifiables pour validation de réception et d''intégrité","Débogage des défaillances de la porte de CI avec analyse d''artefacts déterministes"],"de":["Erfassung von Runpack-Metadaten für Vorfallstriage und -reproduktion","Erzeugung von verifizierbaren Beweisen für Empfangs- und Integritätsvalidierung","Fehlerbehebung von CI-Tor-Fehlern mit deterministischer Artefaktanalyse"],"pt":["Captura de metadados de runpack para triagem e reprodução de incidentes","Geração de evidências verificáveis para validação de recebimento e integridade","Depuração de falhas de gate de CI com análise de artefatos determinística"],"ru":["Захват метаданных runpack для триажа и воспроизведения инцидентов","Генерация проверяемых доказательств для проверки получения и целостности","Отладка неисправностей шлюза CI с детерминированным анализом артефактов"],"ar":["التقاط بيانات تعريف تشغيل الحزمة لتحديد وتكرار الحوادث","توليد أدلة قابلة للتحقق للتحقق من استلام وسلامة","تصحيح أخطاء بوابة CI مع تحليل الملفات الشخصية باتجاه معين"]},"limitations":{"en":["Requires Gait''s offline-first runtime environment","Dependent on tool-boundary policy for signed and verifiable evidence artifacts"],"zh":["需要Gait的离线优先运行时环境","依赖于工具边界策略以获取签名且可验证的证据制品"],"ja":["Gaitのオフライン優先ランタイム環境が必要","署名された可検証アーティファクト証拠を得るためにツール境界ポリシーに依存する"],"ko":["Gait의 오프라인 우선 실행 환경이 필요","서명된 검증 가능한 아티팩트 증거를 얻기 위해 툴 경계 정책에 의존"],"es":["Requiere el entorno de ejecución offline-first de Gait","Dependiente de la política de límite de herramientas para artefactos de evidencia firmados y verificables"],"fr":["Nécessite l''environnement d''exécution offline-first de Gait","Dépend de la politique de limite d''outils pour des artefacts de preuve signés et vérifiables"],"de":["Benötigt die offline-first-Laufzeitumgebung von Gait","Abhängig von der Tool-Grenzenpolitik für signierte und verifizierbare Beweisartefakte"],"pt":["Exige o ambiente de tempo de execução offline-first do Gait","Depende da política de limite de ferramenta para artefatos de evidência assinados e verificáveis"],"ru":["Требует офлайн-режима работы Gait","Зависит от политики инструментального ограничения для подписанных и проверяемых артефактов доказательств"],"ar":["يتطلب بيئة وقت تشغيل غير متصل أولاً من Gait","يعتمد على سياسة حدود الأداة لأدلة ملفات موقعة وقابلة للتحقق"]},"version":4},"contentHash":"32d6c557241f41acaba739464cfca7338481a6b912ec86e451ba66f8ccbd6a73","qualityScore":29}');
