INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Clyra-AI/gait/gait-capture-runpack', 'gait-capture-runpack', 'Clyra-AI', 'gait', 'community', 'gait-capture-runpack Clyra-AI gait community The gait-capture-runpack skill executes workflows to record artifacts safely and deterministically, benefiting AI agent developers and operators. It provides verifiable evidence of AI agent jobs in production. Gait-Capture-Runpack 是一个离线优先的 AI 代理运行时，提供可验证的证据生成和确定性回归支持 Gait-Capture-Runpack はオフライン優先の AI エージェントランタイムで、検証可能な証拠生成と決定性回帰をサポート Gait-Capture-Runpack은 오프라인 우선의 AI 에이전트 런타임으로, 검증 가능한 증거 생성과 결정적 회귀를 지원합니다 Gait-capture-runpack es una habilidad que permite capturar y verificar la evidencia de ejecución de agentes de IA de manera segura y determinística. Proporciona una forma offline-first de ejecutar trabajos de agentes de IA Gait-capture-runpack est une compétence qui permet de capturer et de vérifier les preuves d''exécution des outils d''IA de manière sécurisée et déterministe. Elle offre une façon de travailler offline-first pour les tâches d''outils d''IA Gait-capture-runpack ist eine Fähigkeit, die es ermöglicht, die Ausführung von KI-Agents sicher und deterministisch zu erfassen und zu verifizieren. Sie bietet eine offline-first-Methode zur Ausführung von KI-Aufgaben O gait-capture-runpack é uma ferramenta para capturar artefatos de forma segura e determinística, ideal para triagem de incidentes e portas de CI. Gait-capture-runpack - это инструмент для захвата артефактов в ИИ Агентах, обеспечивающий безопасность и детерминированность. يُستخدم gait-capture-runpack لالتقاط الملفات الفنية بشكل آمن ومحدد، وهو مناسب لمعالجة الحوادث وبوابات CI how to use gait-capture-runpack gait-capture-runpack setup guide gait-capture-runpack alternative gait-capture-runpack vs other AI agent runtimes verifiable evidence for AI agents offline-first AI agent runtime incident triage with gait-capture-runpack gait-capture-runpack install gait-capture-runpack documentation Gait-Capture-Runpack AI 代理 离线优先 可验证证据 确定性回归 工具边界策略 AI 工具 AI 代理技术 Executes workflows to record artifacts safely and deterministically Provides offline-first, signed, and verifiable evidence for AI agent jobs Supports incident triage with captured run artifacts for reproduction Enforces tool-boundary policy for secure AI agent execution Emits signed and verifiable evidence artifacts for CI gate failures gait-capture-runpack is an offline-first runtime for AI agents that captures runpack artifacts and emits signed and verifiable evidence.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('freepik-company/knowledge-agent/release', 'community', 'freepik-company', 'knowledge-agent', 'freepik-company/knowledge-agent', 'release', 5, 2, 29, '2026-02-23T09:49:59Z', '2026-03-07T01:52:27.268Z', '216215d6b4bd2079f2af2082e92670dc883d51c004ac8db2699e1a48d99d1eb4', '{"id":"freepik-company/knowledge-agent/release","name":"release","description":{"en":"The release skill automates institutional knowledge capture, utilizing GitHub CLI for reproducible releases. It benefits developers and release managers seeking efficient version control.","zh":"使用 GitHub CLI 进行版本发布，实现自动化和语义版本控制","ja":"GitHub CLI を使用してバージョンを发布し、自動化とセマンティック バージョニングを実現します","ko":"GitHub CLI를 사용하여 버전을发布하고 자동화와 의미 있는 버전 관리를 구현합니다","es":"Release es una herramienta de administración de versiones que utiliza GitHub CLI para crear versiones de manera segura y reproducible, con tecnologías como Go y pgvector","fr":"Release est un outil de gestion de versions qui utilise GitHub CLI pour créer des versions de manière sûre et reproductible, avec des technologies comme Go et pgvector","de":"Release ist ein Versionsverwaltungstool, das GitHub CLI verwendet, um Versionen sicher und reproduzierbar zu erstellen, mit Technologien wie Go und pgvector","pt":"O release é um agente de gerenciamento de conhecimento com auto-aprendizado e busca semântica, construído com Anthropic Claude, Go e pgvector.","ru":"Релиз - это агент управления знаниями с функцией автономного обучения и семантического поиска, построенный на основе Anthropic Claude, Go и pgvector.","ar":"الإصدار هو وكيل إدارة المعرفة بالاعتماد على الذكاء الاصطناعي مع خاصية التعلم الذاتي والبحث الدلالي، مبني على Anthropic Claude و Go و pgvector."},"seo":{"title":{"en":"Release: Automated Semantic Search Setup Guide | AI Agent...","zh":"Release Setup Guide: 使用 GitHub CLI 进行版本发布","ja":"Release ベストプラクティス: GitHub CLI を使用したバージョン管理","ko":"릴리스 설정 가이드: GitHub CLI를 사용한 버전发布","es":"Guía de configuración de Release: Administración de versi...","fr":"Guide de configuration de Release : Gestion de versions a...","de":"Release-Setup-Anleitung: Versionierung mit GitHub CLI","pt":"Guia de Configuração do Release: Gerenciamento de Conheci...","ru":"Руководство по настройке релиза: Управление знаниями с по...","ar":"دليل إعداد الإصدار: إدارة المعرفة بالاعتماد على الذكاء ال..."},"description":{"en":"Discover how to leverage GitHub CLI for safe releases. Learn to integrate Anthropic Claude with Go and pgvector for AI knowledge management.","zh":"了解如何使用 GitHub CLI 进行版本发布，包括语义版本控制和自动化工作流","ja":"GitHub CLI を使用してバージョンを发布する方法について学びます。セマンティック バージョニングと自動化ワークフローを含みます","ko":"GitHub CLI를 사용하여 버전을发布하는 방법을 알아보세요. 의미 있는 버전 관리와 자동화 워크플로우를 포함합니다","es":"Aprende a configurar Release para administrar versiones de manera segura y reproducible con GitHub CLI y tecnologías como Go y pgvector","fr":"Découvrez comment configurer Release pour gérer les versions de manière sûre et reproductible avec GitHub CLI et des technologies comme Go et pgvector","de":"Erfahren Sie, wie Sie Release konfigurieren, um Versionen sicher und reproduzierbar mit GitHub CLI und Technologien wie Go und pgvector zu verwalten","pt":"Aprenda a configurar o release com auto-aprendizado e busca semântica, integrado ao Slack ou via API A2A","ru":"Узнайте, как настроить релиз с помощью ИИ Агентов, интегрированных со Slack или через API A2A","ar":"تعرف على كيفية إعداد الإصدار باستخدام الذكاء الاصطناعي مع البحث الدلالي ودمجها مع Slack أو عبر واجهة برمجة التطبيقات A2A"},"definition":{"en":"Release is an AI knowledge management agent that integrates with Slack or uses A2A API for customizable, multilingual, production-ready semantic search.","zh":"Release 是一个使用 GitHub CLI 进行版本发布的 AI 知识管理代理","ja":"Release は、GitHub CLI を使用してバージョンを发布する AI エージェントです","ko":"릴리스는 GitHub CLI를 사용하여 버전을发布하는 AI 에이전트입니다","es":"Release es un agente de conocimiento AI que administra versiones de software utilizando GitHub CLI y tecnologías como Anthropic Claude y pgvector","fr":"Release est un agent de connaissances IA qui gère les versions de logiciels en utilisant GitHub CLI et des technologies comme Anthropic Claude et pgvector","de":"Release ist ein AI-Knowledge-Agent, der Softwareversionen mit GitHub CLI und Technologien wie Anthropic Claude und pgvector verwaltet","pt":"O que é release? É um agente de gerenciamento de conhecimento que captura automaticamente o conhecimento institucional.","ru":"Что такое релиз? Это агент управления знаниями, который автоматически捕ывает корпоративные знания.","ar":"ما هو الإصدار؟ هو وكيل إدارة المعرفة الذي يلتقط المعرفة المؤسسية تلقائيًا."},"features":{"en":["Utilizes GitHub CLI (`gh`) for safe and reproducible releases","Supports SemVer versioning with ''major'', ''minor'', or ''patch'' arguments","Automatically infers the correct version bump when no argument is provided","Integrates with Anthropic Claude for advanced AI capabilities","Leverages pgvector for efficient vector search","Compatible with Slack for team collaboration"],"zh":["使用 GitHub CLI 进行版本发布","支持语义版本控制（SemVer）","自动化工作流和验证","支持多语言和自定义","集成 Slack 和 A2A API"],"ja":["GitHub CLI を使用したバージョン发布","セマンティック バージョニング（SemVer）をサポート","自動化ワークフローと検証","多言語とカスタマイズをサポート","Slack と A2A API に対応"],"ko":["GitHub CLI를 사용한 버전发布","의미 있는 버전 관리（SemVer）를 지원","자동화 워크플로우와 검증","다국어와 사용자 정의를 지원","Slack와 A2A API에 대응"],"es":["Integración con GitHub CLI para administrar versiones","Utiliza tecnologías como Go y pgvector para la gestión de versiones","Compatibilidad con SemVer para el control de versiones","Soporte para versiones explícitas y automáticas","Validaciones iniciales para garantizar la integridad del repositorio","Soporte para varios idiomas"],"fr":["Intégration avec GitHub CLI pour gérer les versions","Utilise des technologies comme Go et pgvector pour la gestion de versions","Compatibilité avec SemVer pour le contrôle de versions","Prise en charge de versions explicites et automatiques","Validations initiales pour garantir l''intégrité du référentiel","Prise en charge de plusieurs langues"],"de":["Integration mit GitHub CLI für die Versionsverwaltung","Verwendung von Technologien wie Go und pgvector für die Versionsverwaltung","Unterstützung für SemVer für die Versionskontrolle","Unterstützung für explizite und automatische Versionen","Anfangsvalidierungen, um die Integrität des Repositorys zu gewährleisten","Unterstützung für mehrere Sprachen"],"pt":["Integração com Slack ou API A2A","Auto-aprendizado e busca semântica","Construído com Anthropic Claude, Go e pgvector","Captura automática de conhecimento institucional","Personalizável e multilíngue"],"ru":["Интеграция со Slack или API A2A","Автономное обучение и семантический поиск","Построен на основе Anthropic Claude, Go и pgvector","Автоматическая捕ура корпоративных знаний","Настраиваемый и многоязычный"],"ar":["التكامل مع Slack أو واجهة برمجة التطبيقات A2A","التعلم الذاتي والبحث الدلالي","مبني على Anthropic Claude و Go و pgvector","التقاط المعرفة المؤسسية تلقائيًا","قابل للتخصيص ومتعدد اللغة"]},"keywords":{"en":["how to use release skill","release setup guide","GitHub CLI release management","Anthropic Claude integration","pgvector search","release vs semantic search tools","release install for AI agents","what is release skill","release alternative for developers","release skill for multilingual support"],"zh":["AI 知识管理代理","GitHub CLI","版本发布","语义版本控制","自动化工作流","多语言支持","Slack 集成","A2A API"],"ja":["AI エージェント","GitHub CLI","バージョン发布","セマンティック バージョニング","自動化ワークフロー","多言語対応","Slack 統合","A2A API"],"ko":["AI 에이전트","GitHub CLI","버전发布","의미 있는 버전 관리","자동화 워크플로우","다국어 지원","Slack 연동","A2A API"],"es":["herramientas de versión","administración de versiones","GitHub CLI","Go","pgvector","SemVer","versiones de software","agente de conocimiento AI","desarrollo de software","control de versiones"],"fr":["outils de version","gestion de versions","GitHub CLI","Go","pgvector","SemVer","versions de logiciels","agent de connaissances IA","développement de logiciels","contrôle de versions"],"de":["Versionsverwaltungstools","Versionsverwaltung","GitHub CLI","Go","pgvector","SemVer","Softwareversionen","AI-Knowledge-Agent","Softwareentwicklung","Versionskontrolle"],"pt":["release","gerenciamento de conhecimento","auto-aprendizado","busca semântica","Anthropic Claude","Go","pgvector","Slack","API A2A"],"ru":["релиз","управление знаниями","автономное обучение","семантический поиск","Anthropic Claude","Go","pgvector","Slack","API A2A","ИИ Агенты"],"ar":["الإصدار","إدارة المعرفة","التعلم الذاتي","البحث الدلالي","Anthropic Claude","Go","pgvector","Slack","واجهة برمجة التطبيقات A2A","وكلاء الذكاء الاصطناعي"]}},"owner":"freepik-company","repo":"knowledge-agent","repoPath":"freepik-company/knowledge-agent","stars":5,"forks":2,"updatedAt":"2026-02-23T09:49:59Z","topics":[],"category":"community","skillMd":{"name":"release","description":"Create a professional release using GitHub CLI (gh). Generate SemVer version, clear release notes, and ready-to-run command.","bodyPreview":"Act as a Release Manager + Senior Engineer with experience in professional release workflows and production repositories.\n\nYour goal is to create a release of the current repository using GitHub CLI (`gh`), in a safe, clear, and reproducible way.\n\nInput:\n- $ARGUMENTS can be:\n  - \"major\", \"minor\", or \"patch\" (SemVer)\n  - An explicit version (e.g., v1.4.2)\n  - Empty → automatically infer the correct bump\n\nProcess to follow:\n\n1) Initial validations\n- Verify the repo is a clean Git repository (no un","body":"Act as a Release Manager + Senior Engineer with experience in professional release workflows and production repositories.\n\nYour goal is to create a release of the current repository using GitHub CLI (`gh`), in a safe, clear, and reproducible way.\n\nInput:\n- $ARGUMENTS can be:\n  - \"major\", \"minor\", or \"patch\" (SemVer)\n  - An explicit version (e.g., v1.4.2)\n  - Empty → automatically infer the correct bump\n\nProcess to follow:\n\n1) Initial validations\n- Verify the repo is a clean Git repository (no uncommitted changes).\n- Check that `gh` is installed and authenticated.\n- Detect the latest existing tag (SemVer).\n- Flag if there are no previous tags or if versioning is inconsistent.\n\n2) Version determination\n- Use SemVer strictly.\n- If the argument is:\n  - major → increment MAJOR\n  - minor → increment MINOR\n  - patch → increment PATCH\n  - explicit version → validate format (vX.Y.Z)\n- If no argument:\n  - Analyze commits since the last tag:\n    - BREAKING CHANGE → major\n    - feat → minor\n    - fix / perf / refactor → patch\n- Clearly explain why you choose that version.\n\n3) Release notes generation\n- Summarize changes since the last tag.\n- Group into sections:\n  - 🚀 Features\n  - 🐛 Fixes\n  - 🛠 Refactors / Maintenance\n  - ⚠️ Breaking Changes (if applicable)\n- Use clear and technical language.\n- Avoid noise (trivial commits, formatting, etc.).\n\n4) Risk review\n- Flag:\n  - Potentially breaking changes\n  - Required migrations\n  - Flags, configs, or manual post-release steps\n- If high risks detected, warn explicitly before continuing.\n\n5) Tag and Release creation\n- Generate the exact `gh release create` command:\n  - Include tag, title, and notes\n  - Use `--draft` by default\n  - **IMPORTANT**: `gh release create` automatically creates the Git tag when executed\n- Example:\n  gh release create vX.Y.Z --title \"vX.Y.Z\" --notes \"<release notes>\" --draft\n\nDO NOT execute the command.\nDeliver the command ready to copy/paste.\n\nNote: The tag will be created automatically when the release is published (or when draft is created if using `--draft`).\n\nOutput format:\n\nA) SUMMARY\n- Last version:\n- Proposed new version:\n- Release type:\n- Risk: Low / Medium / High\n\nB) RELEASE NOTES\n<full text>\n\nC) GH COMMAND\n<exact command>\n\nD) TAG CREATION\nExplain that the tag (vX.Y.Z) will be created automatically when running the gh command above.\n\nRules:\n- Don''t publish the release automatically (use --draft).\n- Don''t invent changes: if there are doubts, indicate them.\n- Prioritize clarity and safety over speed.\n- Always explain that the Git tag will be created automatically by gh release create.\n- Include verification step: after creating draft, user should verify tag was created with `git tag -l`."},"lastSynced":"2026-03-07T01:52:27.268Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated version control and release management using GitHub CLI and SemVer.","zh":"非常适合需要使用 GitHub CLI 和 SemVer 进行自动化版本控制和发布管理的 DevOps Agent。","ja":"GitHub CLI と SemVer を使用して自動化されたバージョン管理とリリース管理が必要な DevOps Agent に最適。","ko":"GitHub CLI와 SemVer를 사용하여 자동화된 버전 관리 및 릴리스 관리가 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan control de versiones automatizado y administración de lanzamientos utilizando GitHub CLI y SemVer.","fr":"Parfait pour les agents DevOps ayant besoin d''un contrôle de version automatisé et d''une gestion de versions utilisant GitHub CLI et SemVer.","de":"Perfekt für DevOps-Agents, die automatisierte Versionskontrolle und Release-Management mit GitHub CLI und SemVer benötigen.","pt":"Perfeito para Agents DevOps que necessitam de controle de versão automatizado e gerenciamento de lançamento usando GitHub CLI e SemVer.","ru":"Идеально подходит для агентов DevOps, которым требуются автоматизированный контроль версий и управление выпусками с помощью GitHub CLI и SemVer.","ar":"مثالي لعميل DevOps الذي يحتاج إلى سيطرة إصدار آلية وإدارة إصدار باستخدام GitHub CLI و SemVer."},"recommendation":{"en":"Empowers agents to create reproducible releases using GitHub CLI, supporting major, minor, or patch version bumps, and automatic version inference, while ensuring a clean Git repository.","zh":"赋予代理创建可复现的版本的能力，使用 GitHub CLI 支持主要、次要或补丁版本升级，并自动版本推断，同时确保 Git 存储库清洁。","ja":"GitHub CLI を使用してメジャー、ミノー、またはパッチ バージョンのバンプをサポートし、自動バージョン推論を行い、同時にクリーンな Git リポジトリを確保しながら、再現可能なリリースを作成するためのエージェントをエンパワーメントします。","ko":"GitHub CLI를 사용하여 주요, 부, 패치 버전 업그레이드를 지원하고 자동 버전 추론을 수행하며,同時에 깨끗한 Git 리포지토리를 보장하면서 재현 가능한 릴리스를 생성할 수 있는 에이전트를 강화합니다.","es":"Habilita a los agentes a crear lanzamientos reproducibles utilizando GitHub CLI, que admiten aumentos de versión principales, menores o de revisión, y una inferencia automática de versión, al mismo tiempo que garantiza un repositorio Git limpio.","fr":"Permet aux agents de créer des versions reproductibles en utilisant GitHub CLI, en prenant en charge les mises à jour majeures, mineures ou de correctif, ainsi qu''une inférence automatique de version, tout en garantissant un référentiel Git propre.","de":"Ermöglicht es Agents, reproduzierbare Releases mit GitHub CLI zu erstellen, die Haupt-, Neben- oder Patchversionssprünge unterstützen, sowie automatische Versionsableitung, während ein sauberes Git-Repository sichergestellt wird.","pt":"Habilita os agentes a criar lançamentos reproduzíveis usando GitHub CLI, suportando aumentos de versão major, minor ou patch, e inferência automática de versão, garantindo um repositório Git limpo.","ru":"Наделяет агентов возможностью создавать воспроизводимые выпуски с помощью GitHub CLI, поддерживая основные, незначительные или исправления версий, и автоматическуюinferencia версии, гарантируя чистый репозиторий Git.","ar":"يمنح العميل إمكانية إنشاء إصدارات قابلة للتكرار باستخدام GitHub CLI، مع دعم زيادات إصدار رئيسية وثانوية وتصحيح، واستدلال إصدار تلقائي، مع ضمان مخزن Git نظيف."},"useCases":{"en":["Automating institutional knowledge capture","Generating reproducible releases with SemVer","Validating clean Git repositories before release"],"zh":["自动化机构知识捕获","使用 SemVer 生成可复现的版本","版本发布前验证清洁的 Git 存储库"],"ja":["機関の知識の自動化されたキャプチャー","SemVer を使用して再現可能なバージョンを生成する","リリース前のクリーンな Git リポジトリの検証"],"ko":["기관 지식 자동화 캡처","SemVer를 사용하여 재현 가능한 릴리스 생성","릴리스 전 깨끗한 Git 리포지토리 확인"],"es":["Automatización de la captura de conocimiento institucional","Generación de versiones reproducibles con SemVer","Validación de repositorios Git limpios antes del lanzamiento"],"fr":["Automatisation de la capture des connaissances institutionnelles","Génération de versions reproductibles avec SemVer","Validation de référentiels Git propres avant la publication"],"de":["Automatisierung der Erfassung von institutionellem Wissen","Erstellung reproduzierbarer Versionen mit SemVer","Überprüfung sauberer Git-Repositorys vor dem Release"],"pt":["Automatizar a captura do conhecimento institucional","Gerar lançamentos reproduzíveis com SemVer","Validar repositórios Git limpos antes do lançamento"],"ru":["Автоматизировать захват знаний учреждения","Генерировать воспроизводимые выпуски с SemVer","Проверять чистые репозитории Git перед выпуском"],"ar":["تأتمتية.capture المعرفة المؤسسية","توليد إصدارات قابلة للتكرار مع SemVer","التحقق من مخازن Git النظيفة قبل الإصدار"]},"limitations":{"en":["Requires GitHub CLI installed","Needs a clean Git repository","Limited to SemVer versioning"],"zh":["需要安装 GitHub CLI","需要一个清洁的 Git 存储库","仅限 SemVer 版本控制"],"ja":["GitHub CLI のインストールが必要","クリーンな Git リポジトリが必要","SemVer バージョニングに限定"],"ko":["GitHub CLI 설치가 필요합니다.","깨끗한 Git 리포지토리가 필요합니다.","SemVer 버전 관리에만 제한"],"es":["Requiere GitHub CLI instalado","Necesita un repositorio Git limpio","Limitado a la versión SemVer"],"fr":["Nécessite GitHub CLI installé","A besoin d''un référentiel Git propre","Limité à la version SemVer"],"de":["Benötigt installierten GitHub CLI","Benötigt ein sauberes Git-Repository","Begrenzt auf SemVer-Versionierung"],"pt":["Requer GitHub CLI instalado","Necessita de um repositório Git limpo","Limitado ao versionamento SemVer"],"ru":["Требует установленного GitHub CLI","Требует чистого репозитория Git","Ограничен версионированием SemVer"],"ar":["يتطلب تثبيت GitHub CLI","يحتاج إلى مخزن Git نظيف","محدود بتصريف الإصدار SemVer"]},"version":4},"contentHash":"216215d6b4bd2079f2af2082e92670dc883d51c004ac8db2699e1a48d99d1eb4","qualityScore":29}');
