INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('freepik-company/knowledge-agent/release', 'release', 'freepik-company', 'knowledge-agent', 'community', 'release freepik-company knowledge-agent community The release skill automates institutional knowledge capture, utilizing GitHub CLI for reproducible releases. It benefits developers and release managers seeking efficient version control. 使用 GitHub CLI 进行版本发布，实现自动化和语义版本控制 GitHub CLI を使用してバージョンを发布し、自動化とセマンティック バージョニングを実現します GitHub CLI를 사용하여 버전을发布하고 자동화와 의미 있는 버전 관리를 구현합니다 Release es una herramienta de administración de versiones que utiliza GitHub CLI para crear versiones de manera segura y reproducible, con tecnologías como Go y pgvector Release est un outil de gestion de versions qui utilise GitHub CLI pour créer des versions de manière sûre et reproductible, avec des technologies comme Go et pgvector Release ist ein Versionsverwaltungstool, das GitHub CLI verwendet, um Versionen sicher und reproduzierbar zu erstellen, mit Technologien wie Go und pgvector O release é um agente de gerenciamento de conhecimento com auto-aprendizado e busca semântica, construído com Anthropic Claude, Go e pgvector. Релиз - это агент управления знаниями с функцией автономного обучения и семантического поиска, построенный на основе Anthropic Claude, Go и pgvector. الإصدار هو وكيل إدارة المعرفة بالاعتماد على الذكاء الاصطناعي مع خاصية التعلم الذاتي والبحث الدلالي، مبني على Anthropic Claude و Go و pgvector. how to use release skill release setup guide GitHub CLI release management Anthropic Claude integration pgvector search release vs semantic search tools release install for AI agents what is release skill release alternative for developers release skill for multilingual support AI 知识管理代理 GitHub CLI 版本发布 语义版本控制 自动化工作流 多语言支持 Slack 集成 A2A API Utilizes GitHub CLI (`gh`) for safe and reproducible releases Supports SemVer versioning with ''major'', ''minor'', or ''patch'' arguments Automatically infers the correct version bump when no argument is provided Integrates with Anthropic Claude for advanced AI capabilities Leverages pgvector for efficient vector search Compatible with Slack for team collaboration Release is an AI knowledge management agent that integrates with Slack or uses A2A API for customizable, multilingual, production-ready semantic search.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BugRoger/2bd/_assistant-calendar', 'community', 'BugRoger', '2bd', 'BugRoger/2bd', '_assistant-calendar', 3, 0, 29, '2026-02-28T21:14:50Z', '2026-03-06T07:02:49.954Z', '2d6b98ac3b9b72abe0297e7f7a2e8ac34956e2ed3cdbd6accc121c71a018b85e', '{"id":"BugRoger/2bd/_assistant-calendar","name":"_assistant-calendar","description":{"en":"The _assistant-calendar skill analyzes meeting load and prepares for key interactions, benefiting developers and AI agents. It runs in draft mode, generating sections with placeholders and writing to Synthetic/Assistants/{name}/{timescale}-draft.md.","zh":"_assistant-calendar 是一个基于 Claude Skills 的个人知识和生产力系统，提供日程安排和事件处理功能","ja":"_assistant-calendar は、Claude Skills を基盤とする个人知識と生産性システムであり、スケジュール管理とイベント処理機能を提供する","ko":"_assistant-calendar는 Claude Skills를 기반으로 하는 개인 지식 및 생산성 시스템으로, 일정 관리 및 이벤트 처리 기능을 제공합니다","es":"_assistant-calendar es un sistema de productividad personal que utiliza Claude Skills para analizar la carga de reuniones y preparar interacciones clave","fr":"_assistant-calendar est un système de productivité personnel qui utilise Claude Skills pour analyser la charge de réunions et préparer des interactions clés","de":"_assistant-calendar ist ein persönliches Produktivitätssystem, das Claude Skills verwendet, um die Besprechungsbelastung zu analysieren und wichtige Interaktionen vorzubereiten","pt":"O _assistant-calendar é um sistema de produtividade pessoal construído com Claude Skills, que analisa a carga de reuniões e prepara para interações-chave.","ru":"_assistant-calendar - это личная система производительности, построенная на основе Claude Skills, которая анализирует нагрузку на встречи и готовит к ключевым взаимодействиям.","ar":"_assistant-calendar هو نظام إنتاجية شخصي مبني على Claude Skills، يقوم بتحليل حملة الاجتماعات و الاستعداد للتفاعلات الرئيسية."},"seo":{"title":{