INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BugRoger/2bd/_assistant-calendar', '_assistant-calendar', 'BugRoger', '2bd', 'community', '_assistant-calendar BugRoger 2bd community ai brain claude gps para productivity second skills The _assistant-calendar skill analyzes meeting load and prepares for key interactions, benefiting developers and AI agents. It runs in draft mode, generating sections with placeholders and writing to Synthetic/Assistants/{name}/{timescale}-draft.md. _assistant-calendar 是一个基于 Claude Skills 的个人知识和生产力系统，提供日程安排和事件处理功能 _assistant-calendar は、Claude Skills を基盤とする个人知識と生産性システムであり、スケジュール管理とイベント処理機能を提供する _assistant-calendar는 Claude Skills를 기반으로 하는 개인 지식 및 생산성 시스템으로, 일정 관리 및 이벤트 처리 기능을 제공합니다 _assistant-calendar es un sistema de productividad personal que utiliza Claude Skills para analizar la carga de reuniones y preparar interacciones clave _assistant-calendar est un système de productivité personnel qui utilise Claude Skills pour analyser la charge de réunions et préparer des interactions clés _assistant-calendar ist ein persönliches Produktivitätssystem, das Claude Skills verwendet, um die Besprechungsbelastung zu analysieren und wichtige Interaktionen vorzubereiten O _assistant-calendar é um sistema de produtividade pessoal construído com Claude Skills, que analisa a carga de reuniões e prepara para interações-chave. _assistant-calendar - это личная система производительности, построенная на основе Claude Skills, которая анализирует нагрузку на встречи и готовит к ключевым взаимодействиям. _assistant-calendar هو نظام إنتاجية شخصي مبني على Claude Skills، يقوم بتحليل حملة الاجتماعات و الاستعداد للتفاعلات الرئيسية. how to use _assistant-calendar _assistant-calendar setup guide _assistant-calendar alternative _assistant-calendar vs Claude Skills what is _assistant-calendar _assistant-calendar install Second Brain Daemon configuration Claude Skills for productivity AI agent calendar management _assistant-calendar AI 个人知识和生产力系统 日程安排 事件处理 Claude Skills 草稿模式 并行执行 Runs in draft mode during parallel execution, loading context autonomously Generates sections with placeholders and writes to Synthetic/Assistants/{name}/{timescale}-draft.md Fetches events using the configured provider before processing calendar actions Processes calendar actions by reading $VAULT/00_Brain/Systemic/Co Utilizes Claude Skills for building the personal knowledge and productivity system _assistant-calendar is a personal knowledge and productivity system built with Claude Skills, acting as a calendar specialist to analyze meeting load and prepare for key interactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hack-dance/hack/macos-app-design', 'community', 'hack-dance', 'hack', 'hack-dance/hack', 'macos-app-design', 2, 1, 29, '2026-02-28T01:56:53Z', '2026-03-06T07:09:40.735Z', '87b6dca250e2ce7bd4323c467fe3e154279796e742477d3ae3d0f0e8e2e3fed0', '{"id":"hack-dance/hack/macos-app-design","name":"macos-app-design","description":{"en":"The macos-app-design skill provides opinionated local-dev orchestration for running multiple projects without port conflicts, benefiting developers who want to create native-feeling Mac apps.","zh":"macOS 应用设计指南，帮助您创建本地化的 macOS 应用，使用系统组件和约定","ja":"macOS アプリ設計ガイドは、システムコンポーネントと規約を使用して、ネイティブな macOS アプリを作成するのに役立ちます","ko":"macOS 앱 디자인 가이드는 시스템 구성 요소와 규칙을 사용하여 네이티브 macOS 앱을 만드는 데 도움이 됩니다","es":"Diseña aplicaciones macOS con una integración profunda con flujos de trabajo y evita conflictos de puertos. Nuestra guía te muestra cómo crear aplicaciones nativas y accesibles","fr":"Concevez des applications macOS avec une intégration profonde aux flux de travail et évitez les conflits de ports. Notre guide vous montre comment créer des applications natives et accessibles","de":"Entwerfen Sie macOS-Apps mit tiefer Integration in Workflows und vermeiden Sie Portkonflikte. Unser Leitfaden zeigt Ihnen, wie Sie native und zugängliche Apps erstellen","pt":"O design de aplicativos macOS exige atenção ao detalhe e integração com o sistema operacional. Aprenda a criar aplicativos com design nativo e rápido","ru":"Создание приложений для macOS требует внимания к деталям и интеграции с системой. Узнайте, как создавать приложения с быстрым и элегантным дизайном","ar":"تصميم التطبيقات على نظام macOS يتطلب الانتباه إلى التفاصيل والتكامل مع النظام. تعلم كيفية إنشاء تطبيقات سريعة وجميلة"},"seo":{"title":{"en":"macos-app-design: Native Mac App Development Best Practic...","zh":"macOS 应用设计最佳实践指南","ja":"macOS アプリ設計のベストプラクティスガイド","ko":"macOS 앱 디자인 설정 가이드","es":"Guía de configuración para diseño de aplicaciones macOS c...","fr":"Guide de configuration pour la conception d''applications ...","de":"Einrichtungsleitfaden für macOS-App-Design mit KI-Tool","pt":"Guia de Design de Aplicativos macOS: Melhores Práticas","ru":"ИИ Агенты для macOS: Руководство по Созданию Приложений","ar":"تصميم تطبيقات macOS: دليل أفضل الممارسات"},"description":{"en":"Discover how to create seamless Mac apps with our expert guide to macOS app design, featuring system component integration and UI customization best practice...","zh":"学习如何设计和实现本地化的 macOS 应用，使用系统组件和约定，避免端口冲突","ja":"macOS アプリを設計して実装する方法を学びます。システムコンポーネントと規約を使用して、ポートの競合を避けます","ko":"macOS 앱을 설계하고 구현하는 방법을 배우세요. 시스템 구성 요소와 규칙을 사용하여 포트 충돌을 피합니다","es":"Aprende a diseñar aplicaciones macOS con una integración profunda con flujos de trabajo y evita conflictos de puertos con nuestra guía de diseño de aplicacio...","fr":"Découvrez comment concevoir des applications macOS avec une intégration profonde aux flux de travail et évitez les conflits de ports avec notre guide de conc...","de":"Erfahren Sie, wie Sie macOS-Apps mit tiefer Integration in Workflows entwerfen und Portkonflikte vermeiden können, mit unserem Leitfaden für macOS-App-Design","pt":"Aprenda a criar aplicativos macOS com design nativo e integração profunda com os fluxos de trabalho do sistema operacional","ru":"Создавайте приложения для macOS с помощью ИИ Агентов, используя системные компоненты и конвенции для быстрого и элегантного дизайна","ar":"تعلم كيفية تصميم تطبيقات macOS مع الحفاظ على الشعور بالسرعة والأناقة والتكامل العميق مع سير العمل"},"definition":{"en":"macos-app-design is a set of guidelines and best practices for designing and implementing native-feeling, accessible, and deeply integrated macOS apps using system components and conventions.","zh":"macOS 应用设计是创建本地化的 macOS 应用的过程，使用系统组件和约定","ja":"macOS アプリ設計は、システムコンポーネントと規約を使用して、ネイティブな macOS アプリを作成するプロセスです","ko":"macOS 앱 디자인은 시스템 구성 요소와 규칙을 사용하여 네이티브 macOS 앱을 만드는 과정입니다","es":"El diseño de aplicaciones macOS es el proceso de crear aplicaciones nativas y accesibles que se integran profundamente con los flujos de trabajo de macOS","fr":"La conception d''applications macOS est le processus de création d''applications natives et accessibles qui s''intègrent profondément aux flux de travail de macOS","de":"Das Design von macOS-Apps ist der Prozess der Erstellung von nativen und zugänglichen Apps, die sich tief in die Workflows von macOS integrieren","pt":"O design de aplicativos macOS é a criação de aplicativos com design nativo e integração profunda com os fluxos de trabalho do sistema operacional","ru":"Дизайн приложений для macOS - это создание приложений с быстрым и элегантным дизайном, используя системные компоненты и конвенции","ar":"تصميم التطبيقات على نظام macOS هو إنشاء تطبيقات ذات تصميم أصلي وتكامل عميق مع سير العمل"},"features":{"en":["Prefer system components and conventions over bespoke UI for a native Mac feel","Customize bars, backgrounds, borders, or control chrome with justification","Follow the Mac Citizen Checklist for fast, elegant, and accessible app design","Integrate deeply with macOS workflows for a seamless user experience","Use opinionated local-dev orchestration to run multiple projects without port conflicts"],"zh":["使用系统组件和约定","避免端口冲突","创建本地化的 macOS 应用","遵循 Mac Citizen Checklist","优化应用性能","提高用户体验"],"ja":["システムコンポーネントと規約を使用","ポートの競合を避ける","ネイティブな macOS アプリを作成","Mac Citizen Checklist に従う","アプリのパフォーマンスを最適化","ユーザーエクスペリエンスを向上させる"],"ko":["시스템 구성 요소와 규칙을 사용","포트 충돌을 피함","네이티브 macOS 앱을 만듦","Mac Citizen Checklist를 따름","애플리케이션 성능을 최적화","사용자 경험을 향상"],"es":["Preferencia de componentes y convenciones del sistema","Evitación de conflictos de puertos con múltiples proyectos","Diseño de aplicaciones con una integración profunda con flujos de trabajo de macOS","Creación de aplicaciones nativas y accesibles","Uso de la lista de verificación de Mac Citizen para garantizar la calidad de la aplicación"],"fr":["Préférence des composants et conventions du système","Évitement des conflits de ports avec plusieurs projets","Conception d''applications avec une intégration profonde aux flux de travail de macOS","Création d''applications natives et accessibles","Utilisation de la liste de vérification de Mac Citizen pour garantir la qualité de l''application"],"de":["Bevorzugung von Systemkomponenten und -konventionen","Vermeidung von Portkonflikten mit mehreren Projekten","Entwurf von Apps mit tiefer Integration in macOS-Workflows","Erstellung von nativen und zugänglichen Apps","Verwendung der Mac-Citizen-Checkliste, um die Qualität der App zu gewährleisten"],"pt":["Preferência por componentes e convenções do sistema","Criação de aplicativos com design nativo e rápido","Integração profunda com os fluxos de trabalho do sistema operacional","Uso de barras, fundos, bordas e cromados de controle personalizados","Verificação da lista de verificação do cidadão Mac"],"ru":["Использование системных компонентов и конвенций","Создание приложений с быстрым и элегантным дизайном","Глубокая интеграция с рабочими процессами системы","Использование персонализированных панелей, фонов, границ и элементов управления","Проверка списка проверки гражданина Mac"],"ar":["التفضيل للمكونات والتقاليد الخاصة بالنظام","إنشاء تطبيقات ذات تصميم أصلي وسريع","التكامل العميق مع سير العمل","استخدام شريط، خلفية، حدود، وزر تشغيل مخصص","فحص قائمة التحقق من المواطن ماك"]},"keywords":{"en":["how to use macos-app-design","what is macos-app-design","macos-app-design alternative","macos-app-design vs swiftui","macos-app-design install","macos-app-design setup guide","native mac app development","macos app design best practices","system component integration"],"zh":["macOS 应用设计","macOS 开发","系统组件","约定","本地化","端口冲突","Mac Citizen Checklist","应用性能","用户体验"],"ja":["macOS アプリ設計","macOS 開発","システムコンポーネント","規約","ネイティブ","ポートの競合","Mac Citizen Checklist","アプリのパフォーマンス","ユーザーエクスペリエンス"],"ko":["macOS 앱 디자인","macOS 개발","시스템 구성 요소","규칙","네이티브","포트 충돌","Mac Citizen Checklist","애플리케이션 성능","사용자 경험"],"es":["diseño de aplicaciones macOS","integración con flujos de trabajo","evitación de conflictos de puertos","aplicaciones nativas y accesibles","lista de verificación de Mac Citizen","guía de diseño de aplicaciones macOS","herramientas de diseño de aplicaciones","desarrollo de aplicaciones macOS","IA Agent para diseño de aplicaciones"],"fr":["conception d''applications macOS","intégration aux flux de travail","évitement des conflits de ports","applications natives et accessibles","liste de vérification de Mac Citizen","guide de conception d''applications macOS","outils de conception d''applications","développement d''applications macOS","Outil IA pour conception d''applications"],"de":["macOS-App-Design","Integration in Workflows","Vermeidung von Portkonflikten","native und zugängliche Apps","Mac-Citizen-Checkliste","Leitfaden für macOS-App-Design","Entwicklungstools für macOS-Apps","macOS-App-Entwicklung","KI-Tool für App-Design"],"pt":["design de aplicativos macOS","melhores práticas de design","integração com sistema operacional","componentes do sistema","convenções do sistema","cidadão Mac","lista de verificação do cidadão Mac"],"ru":["дизайн приложений для macOS","лучшие практики дизайна","интеграция с системой","системные компоненты","системные конвенции","гражданин Mac","список проверки гражданина Mac"],"ar":["تصميم التطبيقات على نظام macOS","أفضل الممارسات لتصميم التطبيقات","التكامل مع النظام","مكونات النظام","تقاليد النظام","مواطن ماك","قائمة التحقق من مواطن ماك"]}},"owner":"hack-dance","repo":"hack","repoPath":"hack-dance/hack","stars":2,"forks":1,"updatedAt":"2026-02-28T01:56:53Z","topics":[],"category":"community","skillMd":{"name":"macos-app-design","description":"Use when designing or building native macOS applications with SwiftUI or AppKit. Triggers on menu bar structure, keyboard shortcuts, multi-window behavior, Liquid Glass design system, macOS Tahoe/Sequoia, sidebar navigation, toolbar design, app icons, SF Symbols, or making an app feel like a good Mac citizen.","bodyPreview":"# macOS App Design & Development\n\nGuide for designing and implementing native-feeling, \"good Mac citizen\" apps: fast, elegant, accessible, and deeply integrated with macOS workflows.\n\n## Two Rules That Beat Everything Else\n\n1. **Prefer system components and conventions** over bespoke UI—fastest path to \"feels right on Mac\"\n2. **If you customize bars, backgrounds, borders, or control chrome**: stop and justify it\n\n## Quick Reference: Mac Citizen Checklist\n\n| Area | Requirement |\n|------|---------","body":"# macOS App Design & Development\n\nGuide for designing and implementing native-feeling, \"good Mac citizen\" apps: fast, elegant, accessible, and deeply integrated with macOS workflows.\n\n## Two Rules That Beat Everything Else\n\n1. **Prefer system components and conventions** over bespoke UI—fastest path to \"feels right on Mac\"\n2. **If you customize bars, backgrounds, borders, or control chrome**: stop and justify it\n\n## Quick Reference: Mac Citizen Checklist\n\n| Area | Requirement |\n|------|-------------|\n| **Menu Bar** | Standard layout (App/File/Edit/View/Window/Help), ⌘, for Settings |\n| **Keyboard** | Every primary command reachable via keyboard, standard shortcuts work |\n| **Windows** | Resize fluidly, support multiple windows, respect fullscreen/minimize |\n| **Sidebars** | Top-level navigation, scannable items, content extends behind |\n| **Toolbars** | Group by function/frequency, demote secondary to \"more\" menu |\n| **Text** | Use system text components, standard editing behaviors |\n| **Accessibility** | VoiceOver labels, full keyboard navigation, Reduced Motion support |\n\n## Liquid Glass Quick Rules\n\n**Do:**\n- Use for navigation/controls layer (toolbars, sidebars, bars)\n- Let system components provide built-in behaviors\n\n**Don''t:**\n- Apply to content layer (tables, lists, document content)\n- Stack \"glass on glass\"\n\n## App Archetypes\n\nIdentify your app type first:\n- **Document-based**: Files as primary units (open/save/duplicate)\n- **Library + editor**: Sidebar lists items, detail in main area\n- **Utility**: Single window, optional menu bar\n- **Menu-bar app**: Lives in menu bar, minimal UI\n- **Pro tool**: Dense, power-user workflows\n\n## Deliverables Before Building\n\n1. **App archetype** identified\n2. **Information architecture** (sidebar structure, navigation, window model)\n3. **Command map** (menus + keyboard shortcuts for every major feature)\n4. **State + data model** (persistence, undo/redo, concurrency)\n5. **Accessibility plan** (VoiceOver, keyboard, contrast, reduce motion)\n\n## Full Reference\n\nFor complete design system details, Icon Composer workflow, SF Symbols guidance, evaluation rubrics, and Definition of Done checklist:\n\nSee: [references/macos-design-guide.md](references/macos-design-guide.md)\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Missing menu bar commands | Every feature in menus with keyboard shortcuts |\n| Settings outside App menu | Always ⌘, opening from App menu |\n| Custom text components | Use system text for Mac editing ecosystem |\n| Toolbar overload | Demote secondary actions, group by function |\n| Glass on content | Reserve Liquid Glass for navigation layer only |\n| Breaking standard shortcuts | Never override ⌘C, ⌘V, ⌘Z, etc. |\n| Single-window only | Support multiple windows when it benefits workflows |\n"},"lastSynced":"2026-03-06T07:09:40.735Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Agents needing to design native-feeling Mac apps with system components and conventions","zh":"非常适合需要设计具有本地化 macOS 体验的 UI/UX 代理，包括系统组件和惯例","ja":"UI/UX エージェントがネイティブな Mac アプリをシステム コンポーネントや規範で設計するのに最適","ko":"시스템 구성 요소 및 규칙을 사용하여 네이티브 macOS 느낌의 Mac 앱을 설계하는 UI/UX 에이전트에게 적합","es":"Perfecto para agentes de UI/UX que necesitan diseñar aplicaciones Mac con componentes y convenciones del sistema que parezcan nativas","fr":"Parfait pour les agents UI/UX qui ont besoin de concevoir des applications Mac avec des composants et des conventions système pour une sensation native","de":"Perfekt für UI/UX-Agenten, die native Mac-Apps mit Systemkomponenten und -konventionen entwerfen müssen","pt":"Perfeito para Agentes UI/UX que precisam projetar aplicativos Mac nativos com componentes do sistema e convenções","ru":"Идеально для агентов UI/UX, которым необходимо проектировать родные приложения Mac с системными компонентами и конвенциями","ar":"مثالي لعميل واجهة المستخدم / الخبراء الذين يحتاجون إلى تصميم تطبيقات Mac الأصلي مع مكونات النظام والاتفاقيات"},"recommendation":{"en":"Empowers agents to create fast, elegant, and accessible Mac apps by leveraging system components, conventions, and native macOS workflows, ensuring a seamless user experience through proper justification of customized UI elements, bars, backgrounds, borders, or control chrome","zh":"通过利用系统组件、惯例和本地 macOS 工作流，使得代理能够创建快速、优雅、可访问的 Mac 应用，确保通过自定义 UI 元素、条、背景、边框或控制 chrome 的适当理由实现无缝的用户体验","ja":"システム コンポーネント、規範、ネイティブの macOS ワークフローを利用して、エージェントが高速で優雅でアクセス可能な Mac アプリを作成できるようにし、カスタマイズされた UI 要素、バー、背景、ボーダー、またはコントロール クロームの適切な理由付けによってシームレスなユーザー エクスペリエンスを実現する","ko":"시스템 구성 요소, 규칙 및 네이티브 macOS 워크플로를 활용하여 에이전트가 빠르고 우아하며 접근 가능한 Mac 애플리케이션을 생성할 수 있도록 하여, 사용자 지정 UI 요소, 바, 배경, 경계 또는 제어 크롬의 적절한 정당성을 통해 무결점의 사용자 경험을 보장","es":"Habilita a los agentes a crear aplicaciones Mac rápidas, elegantes y accesibles mediante la utilización de componentes del sistema, convenciones y flujos de trabajo nativos de macOS, lo que garantiza una experiencia de usuario sin interrupciones a través de la justificación adecuada de elementos de interfaz de usuario personalizados, barras, fondos, bordes o cromos de control","fr":"Permet aux agents de créer des applications Mac rapides, élégantes et accessibles en exploitant les composants système, les conventions et les flux de travail natifs de macOS, garantissant ainsi une expérience utilisateur sans accroc grâce à une justification appropriée des éléments d''interface utilisateur personnalisés, des barres, des arrière-plans, des bordures ou du chrome de contrôle","de":"Ermächtigt Agenten, schnelle, elegante und zugängliche Mac-Apps durch die Nutzung von Systemkomponenten, -konventionen und nativen macOS-Arbeitsabläufen zu erstellen, was eine nahtlose Benutzeroberfläche durch eine ordnungsgemäße Rechtfertigung von benutzerdefinierten UI-Elementen, Leisten, Hintergründen, Rändern oder Kontroll-Chrome gewährleistet","pt":"Habilita os agentes a criar aplicativos Mac rápidos, elegantes e acessíveis, aproveitando os componentes do sistema, convenções e fluxos de trabalho macOS nativos, garantindo uma experiência do usuário sem interrupções por meio da justificativa adequada de elementos de interface do usuário personalizados, barras, fundos, bordas ou cromo de controle","ru":"Наделяет агентов возможностью создавать быстрые, элегантные и доступные приложения Mac, используя системные компоненты, конвенции и родные рабочие процессы macOS, обеспечивая бесперебойный пользовательский опыт посредством надлежащего оправдания настроенных элементов интерфейса пользователя, панелей, фонов, границ или элементов управления","ar":"يمنح الوكلاء إمكانية إنشاء تطبيقات Mac سريعة و أنيقة و متوافرة، من خلال الاستفادة من مكونات النظام والاتفاقيات و سير عمل macOS الأصلي، مما يضمن تجربة مستخدم دون انقطاع من خلال التبرير المناسب للعناصر المخصصة لواجهة المستخدم، والأشرطة، والخلفيات، والحدود، أو كروم التحكم"},"useCases":{"en":["Designing intuitive Mac app interfaces","Implementing native macOS workflows","Optimizing app performance for a seamless user experience"],"zh":["为 Mac 应用设计直观的界面","实现本地 macOS 工作流","优化应用性能以实现无缝的用户体验"],"ja":["Mac アプリの直感的なインターフェイスを設計する","ネイティブの macOS ワークフローを実装する","アプリのパフォーマンスを最適化してシームレスなユーザー エクスペリエンスを実現する"],"ko":["Mac 애플리케이션의 直観적인 인터페이스를 설계","네이티브 macOS 워크플로우를 구현","애플리케이션 성능을 최적화하여 무결점의 사용자 경험을 달성"],"es":["Diseñar interfaces de aplicaciones Mac intuitivas","Implementar flujos de trabajo nativos de macOS","Optimizar el rendimiento de la aplicación para una experiencia de usuario sin interrupciones"],"fr":["Concevoir des interfaces d''applications Mac intuitives","Mettre en œuvre des flux de travail natifs de macOS","Optimiser les performances de l''application pour une expérience utilisateur sans accroc"],"de":["Intuitive Mac-App-Oberflächen entwerfen","Native macOS-Arbeitsabläufe implementieren","App-Leistung für eine nahtlose Benutzeroberfläche optimieren"],"pt":["Projetar interfaces de aplicativos Mac intuitivas","Implementar fluxos de trabalho macOS nativos","Otimizar o desempenho do aplicativo para uma experiência de usuário sem interrupções"],"ru":["Проектировать интуитивные интерфейсы приложений Mac","Реализовывать родные рабочие процессы macOS","Оптимизировать производительность приложения для бесперебойного пользовательского опыта"],"ar":["تصميم واجهات تطبيقات Mac直觉ية","تنفيذ سير عمل macOS الأصلي","تحسين أداء التطبيق لتجربة مستخدم دون انقطاع"]},"limitations":{"en":["Requires adherence to macOS design conventions","Limited to Mac app development"],"zh":["需要遵守 macOS 设计惯例","仅限 Mac 应用开发"],"ja":["macOS デザイン規範に従う必要がある","Mac アプリ開発のみに限定"],"ko":["macOS 디자인 규칙을 따라야 함","Mac 애플리케이션 개발만에 한정"],"es":["Requiere adherencia a las convenciones de diseño de macOS","Limitado al desarrollo de aplicaciones Mac"],"fr":["Nécessite l''adhésion aux conventions de conception de macOS","Limité au développement d''applications Mac"],"de":["Erfordert Einhaltung der macOS-Designkonventionen","Begrenzt auf die Entwicklung von Mac-Apps"],"pt":["Exige aderência às convenções de design do macOS","Limitado ao desenvolvimento de aplicativos Mac"],"ru":["Требует соблюдения конвенций дизайна macOS","Ограничен разработкой приложений Mac"],"ar":["يتطلب الالتزام باتفاقيات التصميم من macOS","محدود بتطوير تطبيقات Mac"]},"version":4},"contentHash":"87b6dca250e2ce7bd4323c467fe3e154279796e742477d3ae3d0f0e8e2e3fed0","qualityScore":29}');
