INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nate-d-olson/q100-variant-benchmark-paper/data-dict-update', 'data-dict-update', 'nate-d-olson', 'q100-variant-benchmark-paper', 'community', 'data-dict-update nate-d-olson q100-variant-benchmark-paper community The data-dict-update skill keeps the data dictionary at docs/data-dictionary.md in sync with the codebase, benefiting developers by automating updates whenever relevant files are modified. 数据字典更新技能用于保持代码库和文档的同步，包括R语言文件和Arrow schemas的更新 データディクショナリ更新スキルは、コードベースとドキュメントを同期させるために使用され、R言語ファイルとArrowスキーマの更新が含まれる 데이터 사전 업데이트 스킬은 코드베이스와 문서를 동기화하는 데 사용되며, R 언어 파일 및 Arrow 스키마 업데이트를 포함 El skill de actualización de diccionario de datos mantiene el archivo docs/data-dictionary.md sincronizado con el código base. Se invoca automáticamente cuando se modifican archivos relevantes. Le skill de mise à jour du dictionnaire de données maintient le fichier docs/data-dictionary.md synchronisé avec la base de code. Il est invoqué automatiquement lorsque des fichiers pertinents sont modifiés. Der Skill zum Aktualisieren des Datenwörterbuchs hält die Datei docs/data-dictionary.md synchronisiert mit dem Codebase. Er wird automatisch aufgerufen, wenn relevante Dateien geändert werden. O data-dict-update é uma habilidade que mantém o dicionário de dados em sincronia com o código. É invocada automaticamente por Claude quando arquivos relevantes são modificados. Data-dict-update - это способность, которая поддерживает словарь данных в синхронизации с кодовой базой. Она вызывается автоматически Claude, когда меняются соответствующие файлы. تحديث قاموس البيانات هو مهارة تحافظ على معجم البيانات متوافقًا مع الكود. يتم استدعاؤها تلقائيًا بواسطة كلود عندما يتم تعديل الملفات ذات الصلة how to use data-dict-update data-dict-update setup guide what is data-dict-update data-dict-update alternative data-dict-update vs manual syncing automated data syncing for AI agents data dictionary management R/data_loading.R updates invoke data-dict-update skill 数据字典更新 代码库同步 R语言文件更新 Arrow schemas更新 触发文件 AI工具 数据处理 Invokes automatically when files like R/data_loading.R, R/schemas.R, and R/cache.R are modified Supports synchronization with workflow scripts like generate_variant_parquet.py Updates data dictionary at docs/data-dictionary.md Triggers on changes to Arrow schemas, factor levels, and validation rules in R/schemas.R Monitors caching behavior changes in R/cache.R Ensures data consistency across the codebase data-dict-update is a skill that automatically synchronizes the data dictionary with the codebase, ensuring consistency and accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HenderOrlando/booklyapp/ux-ui', 'community', 'HenderOrlando', 'booklyapp', 'HenderOrlando/booklyapp', 'ux-ui', 0, 0, 29, '2026-02-23T19:25:03Z', '2026-03-07T04:06:49.072Z', '235598886641bde98088e48931f65e50d20cd5ee7914ee0a7907ff1b76dbf7bf', '{"id":"HenderOrlando/booklyapp/ux-ui","name":"ux-ui","description":{"en":"The UX-UI skill ensures deliverables are usable, clear, consistent, accessible, and measurable, benefiting fintech, legaltech, and healthtech developers with systematic design principles","zh":"UX/UI 设计工具旨在提供可用、清晰、连贯、可访问和可衡量的交互体验，通过系统化设计和完整状态实现无缝交互","ja":"UX/UI デザインツールは、システム化された設計と完全な状態を通じて、使用可能、明確、一貫性、可及、測定可能なインタラクティブ体験を提供することを目的としています","ko":"UX/UI 디자인 도구는 시스템적인 설계와 완전한 상태를 통해 사용자에게 사용 가능, 명확, 일관, 접근 가능, 측정 가능한 상호작용 경험을 제공하는 것을 목표로 합니다","es":"La plataforma UX/UI está diseñada para garantizar la usabilidad, claridad y accesibilidad en los proyectos de desarrollo","fr":"La plateforme UX/UI est conçue pour garantir l''utilisabilité, la clarté et l''accessibilité dans les projets de développement","de":"Die UX/UI-Plattform ist darauf ausgelegt, die Benutzbarkeit, Klarheit und Zugänglichkeit in Entwicklungsprojekten zu gewährleisten","pt":"A plataforma UX/UI é projetada para garantir entregas usáveis, claras e acessíveis. Aprenda a aplicar princípios de design sistemático.","ru":"Платформа UX/UI предназначена для обеспечения удобных, ясных и доступных поставок. Узнайте, как применять системный дизайн.","ar":"المنصة UX/UI مصممة لضمان تسليم قابل للاستخدام وواضح وقابل للوصول. تعلم كيفية تطبيق مبادئ التصميم النظامي."},"seo":{"title":{"en":"UX-UI Skill: Systematic Design Setup Guide | AI Agent","zh":"UX/UI 设计工具：打造无缝交互体验 Setup Guide","ja":"UX/UI デザインツール：フリクションレスな体験を作る Best Practices","ko":"UX/UI 디자인 도구: 무결점 경험을 위한 설계 가이드","es":"Guía de configuración de UX/UI para desarrolladores","fr":"Conseils de mise en place de l''UX/UI pour les développeurs","de":"UX/UI-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração UX/UI: Melhores Práticas para Desenv...","ru":"Настройка UX/UI: Руководство по Лучшим Практикам для Разр...","ar":"إعداد UX/UI: دليل أفضل الممارسات للمطورين"},"description":{"en":"Unlock efficient reservation management with UX-UI, learn how to apply clarity, consistency, and accessibility principles to your fintech, legaltech, or heal...","zh":"了解 UX/UI 设计工具的技术细节，打造可用、清晰、连贯、可访问和可衡量的交互体验，提升用户满意度","ja":"UX/UI デザインツールの技術的側面を探ることで、フリクションレスな体験を作り、ユーザーサティスファクションを向上させる","ko":"UX/UI 디자인 도구의 기술 세부 사항을 학습하여 사용자滿意度를 높이고 무결점 경험을 제공하는 방법","es":"Aprende a implementar principios de UX/UI efectivos en tus proyectos de desarrollo con nuestra guía de mejores prácticas","fr":"Découvrez comment mettre en œuvre des principes d''UX/UI efficaces dans vos projets de développement avec notre guide de bonnes pratiques","de":"Erfahren Sie, wie Sie effektive UX/UI-Prinzipien in Ihre Entwicklungsprojekte implementieren können, mit unserem Leitfaden für beste Praktiken","pt":"Aprenda a implementar princípios de UX/UI para garantir entregas usáveis, claras e acessíveis. Descubra as melhores práticas para desenvolvedores.","ru":"Узнайте, как реализовать принципы UX/UI, чтобы гарантировать удобные, ясные и доступные поставки. Откройте для себя лучшие практики для разработчиков ИИ Аген...","ar":"تعلم كيفية تنفيذ مبادئ UX/UI لضمان التسليم القابل للاستخدام والواضح والقابل للوصول. اكتشف أفضل الممارسات للمطورين."},"definition":{"en":"ux-ui is a systematic design approach ensuring usability, clarity, consistency, accessibility, and measurability in fintech, legaltech, and healthtech applications","zh":"UX/UI 设计工具是一种用于创建可用和清晰的交互体验的技术，确保任何交互都是无缝和可衡量的","ja":"UX/UI デザインツールは、使用可能で明確なインタラクティブ体験を作成する技術であり、フリクションレスで測定可能な体験を保証する","ko":"UX/UI 디자인 도구는 사용 가능하고 명확한 상호작용 경험을 만들기 위한 기술로, 무결점하고 측정 가능한 경험을 보장합니다","es":"UX/UI se refiere a la creación de interfaces de usuario claras y consistentes para una experiencia de usuario óptima","fr":"L''UX/UI fait référence à la création d''interfaces utilisateur claires et cohérentes pour une expérience utilisateur optimale","de":"UX/UI bezeichnet die Erstellung von klaren und konsistenten Benutzeroberflächen für eine optimale Benutzererfahrung","pt":"UX/UI é uma abordagem de design que visa garantir a usabilidade, clareza e acessibilidade de uma plataforma ou aplicativo.","ru":"UX/UI — это подход к дизайну, направленный на обеспечение удобства, ясности и доступности платформы или приложения.","ar":"UX/UI هو نهج تصميم يهدف إلى ضمان سهولة استخدام ووضوح وسهولة الوصول إلى منصة أو تطبيق."},"features":{"en":["Applies Clarity beats cleverness principle for direct copywriting","Eliminates friction with systematic design and complete states","Ensures consistency and accessibility in fintech, legaltech, and healthtech projects","Supports measurable outcomes with data-driven design decisions","Integrates with multiple tech domains including Edtech, Retailtech, and Proptech","Follows non-negotiable principles for efficient reservation management"],"zh":["基于 Clarity beats cleverness 的设计原则","实现无缝交互体验，减少 Friction","系统化设计，确保交互体验的一致性","可访问和可衡量的交互体验","支持 Fintech、Legaltech、Edtech 等多个行业"],"ja":["Clarity beats cleverness という設計原則に基づく設計","フリクションレスなインタラクティブ体験の実現","システム化された設計による一貫性の確保","可及性と測定可能性のあるインタラクティブ体験","Fintech、Legaltech、Edtech など複数の業界をサポート"],"ko":["Clarity beats cleverness 설계 원칙 기반의 설계","무결점 상호작용 경험의 구현","시스템적인 설계를 통한 일관성 보장","접근 가능하고 측정 가능한 상호작용 경험","Fintech, Legaltech, Edtech 등 여러 산업을 지원"],"es":["Diseño sistemático para garantizar la usabilidad","Estados completos para una experiencia de usuario sin fricción","Principios de claridad y consistencia en la creación de interfaces","Implementación de copy directo y sin jerga innecesaria","Diseño accesible para todos los usuarios"],"fr":["Conception systématique pour garantir l''utilisabilité","États complets pour une expérience utilisateur sans friction","Principes de clarté et de cohérence dans la création d''interfaces","Mise en œuvre de copy direct et sans jargon inutile","Conception accessible pour tous les utilisateurs"],"de":["Systematisches Design für die Gewährleistung der Benutzbarkeit","Vollständige Zustände für eine Benutzererfahrung ohne Reibung","Prinzipien der Klarheit und Konsistenz bei der Erstellung von Benutzeroberflächen","Implementierung von direktem Copy und ohne unnötige Fachsprache","Barrierefreies Design für alle Benutzer"],"pt":["Clarity beats cleverness: copy direto e sem jerga","Friction is a bug: design sistemático para minimizar a fricção","Entregas usáveis e acessíveis","Diseño sistemático e estados completos","Medição e análise de desempenho"],"ru":["Clarity beats cleverness: прямой копи и без ненужной жаргона","Friction is a bug: системный дизайн для минимизации трения","Удобные и доступные поставки","Системный дизайн и полные состояния","Измерение и анализ производительности"],"ar":["الوضوح يغلب على الذكاء: نسخة مباشرة وبدون مصطلحات غير ضرورية","الاحتكاك هو خطأ: تصميم نظامي لتحقيق الحد الأدنى من الاحتكاك","التسليم القابل للاستخدام والقابل للوصول","التصميم النظامي والحالات الكاملة","قياس وتحليل الأداء"]},"keywords":{"en":["what is ux-ui","ux-ui setup guide","ux-ui vs material design","how to use ux-ui in fintech","ux-ui install for legaltech","ux-ui best practices for healthtech","ux-ui alternative for edtech","ux-ui systematic design principles","ux-ui for efficient reservation management","ux-ui clarity beats cleverness principle"],"zh":["UX/UI 设计工具","无缝交互体验","Clarity beats cleverness","系统化设计","可访问和可衡量","Fintech UX/UI","Legaltech UX/UI","Edtech UX/UI"],"ja":["UX/UI デザインツール","フリクションレスな体験","Clarity beats cleverness","システム化された設計","可及性と測定可能性","Fintech UX/UI","Legaltech UX/UI","Edtech UX/UI"],"ko":["UX/UI 디자인 도구","무결점 상호작용 경험","Clarity beats cleverness","시스템적인 설계","접근 가능하고 측정 가능","Fintech UX/UI","Legaltech UX/UI","Edtech UX/UI"],"es":["ux/ui para desarrolladores","diseño de interfaces de usuario","experiencia de usuario óptima","principios de claridad y consistencia","copy directo y sin jerga","diseño accesible","herramientas de ux/ui","mejores prácticas de ux/ui","guias de configuración de ux/ui"],"fr":["ux/ui pour les développeurs","conception d''interfaces utilisateur","expérience utilisateur optimale","principes de clarté et de cohérence","copy direct et sans jargon","conception accessible","outils d''ux/ui","bonnes pratiques d''ux/ui","guides de configuration d''ux/ui"],"de":["ux/ui für Entwickler","Erstellung von Benutzeroberflächen","optimale Benutzererfahrung","Prinzipien der Klarheit und Konsistenz","direkter Copy und ohne Fachsprache","barrierefreies Design","UX/UI-Tools","beste Praktiken für UX/UI","Konfigurationsleitfäden für UX/UI"],"pt":["ux ui design","desenvolvimento de plataforma","princípios de design","usabilidade e acessibilidade","melhores práticas de desenvolvimento","guias de configuração ux ui","ferramentas de design sistemático"],"ru":["ux ui дизайн","разработка платформы","принципы дизайна","удобство и доступность","лучшие практики разработки","руководства по настройке ux ui","инструменты системного дизайна","ИИ Агенты"],"ar":["تصميم ux ui","تطوير المنصة","مبادئ التصميم","سهولة الاستخدام وسهولة الوصول","أفضل الممارسات للتطوير","دلائل إعداد ux ui","أدوات التصميم النظامي","وكلاء الذكاء الاصطناعي"]}},"owner":"HenderOrlando","repo":"booklyapp","repoPath":"HenderOrlando/booklyapp","stars":0,"forks":0,"updatedAt":"2026-02-23T19:25:03Z","topics":[],"category":"community","skillMd":{"name":"ux-ui","description":"Skill de UX/UI que asegura entregas usables, claras, consistentes, accesibles y medibles, con diseño sistemático y estados completos.","bodyPreview":"# 🎨 Windsurf Skill — UX/UI (Clave para que se use)\n**Skill ID:** SK-UXUI-001  \n**Aplica a:** Fintech, Legaltech, Edtech, Healthtech, Retailtech, Proptech, Foodtech, Medtech, Regtech  \n**Objetivo:** garantizar que cualquier entrega sea **usable**, **clara**, **consistente**, **accesible** y **medible** (sin fricción), con un diseño sistemático y estados completos.\n\n---\n\n## 1) Principios (no negociables)\n1. **Clarity beats cleverness:** copy directo, sin jerga innecesaria.\n2. **Friction is a bug:","body":"# 🎨 Windsurf Skill — UX/UI (Clave para que se use)\n**Skill ID:** SK-UXUI-001  \n**Aplica a:** Fintech, Legaltech, Edtech, Healthtech, Retailtech, Proptech, Foodtech, Medtech, Regtech  \n**Objetivo:** garantizar que cualquier entrega sea **usable**, **clara**, **consistente**, **accesible** y **medible** (sin fricción), con un diseño sistemático y estados completos.\n\n---\n\n## 1) Principios (no negociables)\n1. **Clarity beats cleverness:** copy directo, sin jerga innecesaria.\n2. **Friction is a bug:** cada paso debe justificarse por valor o control de riesgo.\n3. **Consistency scales:** todo UI nuevo debe salir del Design System (o ampliarlo).\n4. **States are features:** empty/loading/error/disabled/success son parte del alcance.\n5. **Accessibility by default:** a11y no es “extra”; es requisito.\n6. **Progressive disclosure:** mostrar lo mínimo; expandir cuando el usuario lo pida.\n7. **Trust & safety:** especialmente en dominios regulados: transparencias, confirmaciones y auditabilidad.\n\n---\n\n## 2) Outputs obligatorios (según fase BMAD)\n\n### 2.1 BRIEF — UX Brief (obligatorio)\n- **Persona/Contexto:** quién, dónde, qué intenta lograr.\n- **JTBD + top pains:** 3 dolores y 3 motivaciones.\n- **Success criteria UX:** (ej. completar onboarding < 2 min, tasa de activación, task success rate).\n- **Constraints:** plataforma (web/mobile), i18n, dark mode, compliance, a11y target.\n\n**Gate BRIEF UX (bloquea):**\n- No hay usuario/escenario principal.\n- No hay métrica de éxito UX (task success / time-on-task / activation).\n\n---\n\n### 2.2 MODEL — UX Model (obligatorio)\n- **User Flow** (happy path + alternos mínimos).\n- **Information Architecture (IA)** (navegación, jerarquía).\n- **Content Model:** qué información aparece y por qué (prioridades).\n- **State Model:** estados por pantalla/componente (empty/loading/error/permission/first-run).\n- **Design System impact:** reutiliza/crea componentes.\n\n**Gate MODEL UX (bloquea):**\n- Flujo sin estados de error/empty.\n- IA inconsistente o navegación no definida.\n\n---\n\n### 2.3 ACTION — UI Spec (obligatorio)\n- **Screen Spec** por pantalla (mínimo):\n  - Objetivo de la pantalla\n  - Componentes usados (DS)\n  - Copy final (títulos, ayudas, CTAs)\n  - Validaciones y mensajes de error\n  - Estados (empty/loading/error/success/disabled)\n  - Accesibilidad (focus order, labels, roles, tamaños)\n- **Checklist de implementación** (dev-ready):\n  - tokens (spacing, typography)\n  - responsive breakpoints (si web)\n  - instrumentation (eventos clave UX)\n\n**Gate ACTION UX (bloquea):**\n- No hay copy final (o hay placeholders).\n- No hay definición de estados.\n- No hay criterios a11y mínimos.\n\n---\n\n### 2.4 DEPLOY — Usability + Observabilidad UX (obligatorio)\n- **Plan de prueba de usabilidad:** tareas, criterios, muestra mínima.\n- **Telemetría UX:** eventos para drop-off y fricción.\n- **Iteración:** qué se cambia si el funnel cae.\n\n**Gate DEPLOY UX (bloquea):**\n- No hay plan de pruebas o señales de fricción.\n- No hay instrumentación mínima de onboarding/activación.\n\n---\n\n## 3) UX Research & UX Writing (claridad + onboarding)\n### 3.1 UX Writing: reglas\n- **CTA = verbo + resultado** (ej. “Crear presupuesto”, no “Continuar”).\n- Microcopy siempre responde:\n  - “¿Qué pasa si hago esto?”\n  - “¿Por qué me pides esto?”\n  - “¿Cómo lo arreglo si falla?”\n- Evitar culpa/juicio (finanzas/salud/legal): tono neutral y empático.\n- Confirmaciones solo cuando:\n  - hay riesgo (pérdida de datos, cambio irreversible, pago)\n  - o reduce ansiedad\n\n### 3.2 Onboarding sin fricción (framework)\n- **3 pasos máximo** (si se excede, justificar por compliance/riesgo).\n- **Progressive onboarding:** pedir datos cuando el usuario ya vio valor.\n- **Education-in-context:** tips dentro del flujo, no “manuales”.\n- **Aha Moment** definido + evento de activación medible.\n\n**Gate UX Writing (bloquea):**\n- Copy ambiguo en CTAs (“OK”, “Siguiente”) sin contexto.\n- Mensajes de error no accionables.\n\n---\n\n## 4) UI Design + Design System (consistencia)\n### 4.1 Reglas Design System\n- Todo nuevo elemento debe ser:\n  - **Tokenizado** (color, spacing, typography)\n  - **Reutilizable** (prop-driven)\n  - **Documentado** (uso + do/don’t)\n- Componentes obligatorios:\n  - Buttons, Inputs, Selects, Modal/Sheet, Toast, Card, ListItem, Tabs, Badge/Chip\n  - Charts (si aplica) con estados “no data”\n- Estados obligatorios por componente:\n  - default / hover (web) / pressed / focus / disabled\n  - loading\n  - error\n  - empty (cuando aplica)\n\n### 4.2 Dark mode\n- No es “invertir colores”; es un **tema completo**:\n  - contraste validado\n  - colores semánticos (success/warn/error)\n  - sombras/overlays ajustados\n- Gate: si hay dark mode, toda pantalla debe probarse en ambos temas.\n\n**Gate Design System (bloquea):**\n- Componentes “one-off” sin justificación.\n- Inconsistencia visual entre pantallas del mismo flujo.\n\n---\n\n## 5) Accesibilidad (a11y) — mínimos exigibles\n**Checklist mínimo:**\n- Contraste suficiente (texto, iconos, controles).\n- Tamaños legibles (tipografía y targets táctiles).\n- Navegación por teclado (web) y focus visible.\n- Labels/roles correctos en inputs y componentes interactivos.\n- Lectura (screen reader): orden lógico, headings, aria-* donde aplique.\n- No depender solo de color para comunicar estado (error/success).\n\n**Gate a11y (bloquea para flows core):**\n- Inputs sin label accesible.\n- Focus order roto o imposible navegar.\n- Targets táctiles demasiado pequeños en mobile.\n\n---\n\n## 6) Prototipado (Figma) + pruebas de usabilidad\n### 6.1 Prototipo (definición)\n- Fidelity por fase:\n  - Discovery: low-fi (wire)\n  - Validación: mid-fi clickable\n  - Pre-dev: hi-fi con componentes DS\n- Debe cubrir:\n  - Happy path\n  - 2 alternos (mínimo)\n  - Estado empty y error principal\n\n### 6.2 Pruebas de usabilidad (mínimo viable)\n- 5 usuarios por ronda (heurística), o 3 si es interno con limitación.\n- 3 tareas críticas (onboarding + 2 tareas core).\n- Métricas:\n  - **Task success rate**\n  - **Time on task**\n  - **Error rate**\n  - **Confidence score** (1–5)\n\n**Gate usabilidad (bloquea en lanzamientos R2+):**\n- No hay tareas definidas ni criterio de éxito.\n- No existe iteración planificada post-test.\n\n---\n\n## 7) Heurísticas de calidad UX (Windsurf debe auditar)\n- ¿El usuario entiende qué hacer en < 5 segundos?\n- ¿Hay una “salida” clara (back/cancel) sin perder datos?\n- ¿Se puede recuperar de errores sin soporte?\n- ¿Las pantallas enseñan en contexto (sin tutorial largo)?\n- ¿Se mide la fricción (drop-offs y rage taps/clicks)?\n\n---\n\n## 8) Formato obligatorio de salida (cuando se active este skill)\nWindsurf debe responder con:\n\n1) **UX Brief** (persona + objetivo + success criteria)  \n2) **User Flow** (happy + alternos) + **State Model**  \n3) **UI Spec** (pantallas, componentes DS, copy final, validaciones)  \n4) **A11y Checklist aplicado**  \n5) **Figma/Prototype Plan** (qué se prototipa)  \n6) **Usability Test Plan** (tareas + métricas + iteración)  \n7) **Next Steps** (accionables)\n\n---\n\n## 9) Señales de deuda UX (Windsurf debe advertir)\n- Copy ambiguo / jerga / onboarding largo sin razón.\n- Falta de estados (empty/loading/error).\n- Inconsistencia de componentes.\n- Dark mode parcial.\n- Sin a11y mínimo.\n- No hay medición de fricción ni plan de prueba.\n\n---\n**End of skill.**\n\n"},"lastSynced":"2026-03-07T04:06:49.072Z","agentAnalysis":{"suitability":{"en":"Perfect for Interface Agents needing systematic design principles for fintech, legaltech, and healthtech applications.","zh":"非常适合需要系统化设计原则的界面代理，用于金融科技、法律科技和医疗科技应用。","ja":"金融テクノロジー、法テクノロジー、ヘルステクノロジーなどのアプリケーションに系統的な設計原則が必要なインターフェイスエージェントに最適です。","ko":"금융 기술, 법률 기술, 헬스 기술 등에 대한 체계적인 디자인 원칙이 필요한 인터페이스 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Interfaz que necesitan principios de diseño sistemáticos para aplicaciones de fintech, legaltech y healthtech.","fr":"Parfait pour les Agents d''Interface ayant besoin de principes de conception systématiques pour les applications de fintech, legaltech et healthtech.","de":"Perfekt für Interface-Agents, die systematische Designprinzipien für Finanztechnologie-, Rechtstechnologie- und Gesundheitstechnologie-Anwendungen benötigen.","pt":"Perfeito para Agentes de Interface que necessitam de princípios de design sistemáticos para aplicações de fintech, legaltech e healthtech.","ru":"Идеально подходит для Интерфейсных Агентов, которым необходимы системные принципы дизайна для приложений fintech, legaltech и healthtech.","ar":"مثالي لعميل الواجهة الذي يحتاج إلى مبادئ تصميم منهجية لتطبيقات fintech و legaltech و healthtech."},"recommendation":{"en":"Empowers agents to design clear, consistent, and accessible interfaces using systematic design principles, ensuring deliverables are usable and measurable, with a focus on clarity, frictionless interaction, and systematic design.","zh":"赋予代理设计清晰、一致、可访问的界面，使用系统化的设计原则，确保可交付成果是可用且可衡量的，注重清晰、无缝交互和系统化设计。","ja":"エージェントが系統的な設計原則を使用して、クリアで一貫性のあるインターフェイスを設計できるようにし、デリバリーが使用可能で測定可能であることを保証し、クリアさ、無摩擦のインタラクション、系統的な設計に重点を置きます。","ko":"에이전트가 시스템적인 디자인 원칙을 사용하여 명확하고 일관된 인터페이스를 설계할 수 있도록 하여, 사용 가능하고 측정 가능한 결과를 보장하고, 명확성, 마찰 없는 상호 작용 및 체계적인 디자인에 중점을 둡니다.","es":"Habilita a los agentes a diseñar interfaces claras, coherentes y accesibles utilizando principios de diseño sistemáticos, garantizando que los entregables sean utilizables y medibles, con un enfoque en la claridad, la interacción sin fricciones y el diseño sistemático.","fr":"Permet aux agents de concevoir des interfaces claires, cohérentes et accessibles en utilisant des principes de conception systématiques, garantissant que les livrables soient utilisables et mesurables, avec un accent sur la clarté, l''interaction sans friction et la conception systématique.","de":"Ermächtigt die Agenten, klare, konsistente und zugängliche Schnittstellen unter Verwendung systematischer Designprinzipien zu entwerfen, sicherstellend, dass die Ergebnisse nutzbar und messbar sind, mit Fokus auf Klarheit, reibungslose Interaktion und systematisches Design.","pt":"Habilita os agentes a projetar interfaces claras, consistentes e acessíveis usando princípios de design sistemáticos, garantindo que os entregáveis sejam utilizáveis e mensuráveis, com foco na clareza, interação sem atrito e design sistemático.","ru":"Наделяет агентов возможностью проектировать четкие, последовательные и доступные интерфейсы, используя системные принципы дизайна, гарантируя, что результаты будут удобными и измеримыми, с фокусом на ясности, бесшовном взаимодействии и системном дизайне.","ar":"يمكن للعميل تصميم واجهات واضحة ومتسقة ويمكن الوصول إليها باستخدام مبادئ تصميم منهجية، مما يضمن أن تكون النتائج قابلة للاستخدام والقياس، مع التركيز على الوضوح والتفاعل الخالي من العيوب والتصميم المنهجي."},"useCases":{"en":["Designing user flows for fintech applications","Creating accessible interfaces for healthtech platforms","Developing consistent UI components for legaltech services"],"zh":["为金融科技应用程序设计用户流程","为医疗科技平台创建可访问的界面","为法律科技服务开发一致的 UI 组件"],"ja":["金融テクノロジーアプリケーションのユーザーフローを設計する","ヘルステクノロジープラットフォームのアクセス可能なインターフェイスを作成する","法テクノロジーサービスの一貫した UI コンポーネントを開発する"],"ko":["금융 기술 애플리케이션을 위한 사용자 흐름 설계","헬스 기술 플랫폼을 위한 접근 가능한 인터페이스 생성","법률 기술 서비스를 위한 일관된 UI 구성 요소 개발"],"es":["Diseñar flujos de usuario para aplicaciones de fintech","Crear interfaces accesibles para plataformas de healthtech","Desarrollar componentes de UI coherentes para servicios de legaltech"],"fr":["Concevoir des flux d''utilisateurs pour les applications de fintech","Créer des interfaces accessibles pour les plateformes de healthtech","Développer des composants d''UI cohérents pour les services de legaltech"],"de":["Benutzerflüsse für Finanztechnologie-Anwendungen entwerfen","Zugängliche Schnittstellen für Gesundheitstechnologie-Plattformen erstellen","Konsistente Benutzeroberflächen-Komponenten für Rechtstechnologie-Dienste entwickeln"],"pt":["Projeto de fluxos de usuário para aplicações de fintech","Criação de interfaces acessíveis para plataformas de healthtech","Desenvolvimento de componentes de UI consistentes para serviços de legaltech"],"ru":["Проектирование пользовательских потоков для приложений fintech","Создание доступных интерфейсов для платформ healthtech","Разработка последовательных компонентов UI для сервисов legaltech"],"ar":["تصميم تدفقات المستخدم لتطبيقات fintech","إنشاء واجهات يمكن الوصول إليها لأنظمة healthtech","تطوير مكونات واجهة المستخدم المتسقة لخدمات legaltech"]},"limitations":{"en":["Requires understanding of design principles","Applies to specific industries (fintech, legaltech, healthtech, etc.)"],"zh":["需要了解设计原则","仅适用于特定行业（金融科技、法律科技、医疗科技等）"],"ja":["設計原則の理解が必要","特定の業界（金融テクノロジー、法テクノロジー、ヘルステクノロジーなど）のみに適用可能"],"ko":["디자인 원칙에 대한 이해가 필요","특정 산업(금융 기술, 법률 기술, 헬스 기술 등)만 적용 가능"],"es":["Requiere comprensión de principios de diseño","Se aplica a industrias específicas (fintech, legaltech, healthtech, etc.)"],"fr":["Nécessite une compréhension des principes de conception","S''applique à des industries spécifiques (fintech, legaltech, healthtech, etc.)"],"de":["Benötigt Verständnis für Designprinzipien","Wird auf bestimmte Branchen angewendet (Finanztechnologie, Rechtstechnologie, Gesundheitstechnologie usw.)"],"pt":["Exige compreensão dos princípios de design","Aplica-se a setores específicos (fintech, legaltech, healthtech, etc.)"],"ru":["Требует понимания принципов дизайна","Применяется к конкретным отраслям (fintech, legaltech, healthtech и т. д.)"],"ar":["يتطلب فهم مبادئ التصميم","ينطبق على قطاعات محددة (fintech و legaltech و healthtech وغيرها)"]},"version":4},"contentHash":"235598886641bde98088e48931f65e50d20cd5ee7914ee0a7907ff1b76dbf7bf","qualityScore":29}');
