INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MUmerRazzaq/fast-next-todo/database-connection-pooling', 'database-connection-pooling', 'MUmerRazzaq', 'fast-next-todo', 'community', 'database-connection-pooling MUmerRazzaq fast-next-todo community This skill provides guidance on configuring database connection pools using Python''s SQLAlchemy library, covering best practices for traditional and serverless databases. It benefits developers working with databases. 本技能提供数据库连接池配置的指导和资源，主要使用Python的SQLAlchemy库，涵盖传统数据库和服务器less数据库架构的最佳实践 このスキルは、データベース接続プーリングの設定に関するガイダンスとリソースを提供します。PythonのSQLAlchemyライブラリを主に使用し、従来のデータベースとサーバーレスデータベースアーキテクチャのベストプラクティスを網羅 이 스킬은 데이터베이스 연결 풀링 설정에 대한 가이드와 리소스를 제공합니다. Python의 SQLAlchemy 라이브러리를 주로 사용하며, 전통적인 데이터베이스와 서버리스 데이터베이스 아키텍처의 최고의 관행을 다룹니다 Configuración de pooling de conexiones de base de datos con Python y SQLAlchemy para mejorar el rendimiento Configuration du pooling de connexions de base de données avec Python et SQLAlchemy pour améliorer les performances Konfiguration von Datenbank-Verbindungs-Pooling mit Python und SQLAlchemy für bessere Leistung O pooling de conexões de banco de dados é uma técnica para melhorar o desempenho da sua aplicação. Aprenda a configurá-lo com Python e SQLAlchemy. Пул подключений к базе данных - это техника для улучшения производительности вашего приложения. Узнайте, как настроить его с помощью Python и SQLAlchemy. برك اتصال قاعدة البيانات هو تقنية لتحسين أداء التطبيق الخاص بك. تعلم كيفية تنظیمها باستخدام Python و SQLAlchemy. how to use database-connection-pooling database-connection-pooling setup guide database-connection-pooling best practices database-connection-pooling vs traditional databases database-connection-pooling alternative to JDBC install database-connection-pooling SQLAlchemy database connection pooling serverless database connection pooling database connection pooling for Python developers 数据库连接池 SQLAlchemy Python数据库连接 服务器less数据库 数据库连接池配置 最佳实践 传统数据库 服务器less数据库架构 Configures database connection pools using Python''s SQLAlchemy library Provides best practices for traditional and serverless database architectures Supports modern serverless databases like Neon and PlanetScale Offers guidance on identifying environment and determining database type Covers workflow for setting up and optimizing database connection pools database-connection-pooling is a technique for managing multiple database connections efficiently, using libraries like SQLAlchemy to optimize performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Auriaz/nuxt-stack-starter/nuxt-api-endpoint', 'community', 'Auriaz', 'nuxt-stack-starter', 'Auriaz/nuxt-stack-starter', 'nuxt-api-endpoint', 0, 0, 29, '2026-03-02T14:37:53Z', '2026-03-07T04:10:02.860Z', '4da43845ed05ae31987727d5041300ca2bbeb14890fb40509686360830fcac9a', '{"id":"Auriaz/nuxt-stack-starter/nuxt-api-endpoint","name":"nuxt-api-endpoint","description":{"en":"The nuxt-api-endpoint skill enables developers to create and manage API endpoints in Nuxt.js projects, following a structured architecture. It benefits AI agent developers by providing a standardized approach to API development.","zh":"Nuxt API Endpoint 是一个用于构建 API 接口的工具，帮助开发者实现高效的数据交换和业务逻辑处理","ja":"Nuxt API Endpoint は API インターフェースを構築するためのツールであり、開発者が効率的なデータ交換とビジネスロジック処理を実現するのに役立ちます","ko":"Nuxt API Endpoint는 API 인터페이스를 구축하는 데 사용되는 도구로 개발자가 효율적인 데이터 교환 및 비즈니스 로직 처리를 실현하는 데 도움을 줍니다","es":"Nuxt API Endpoint es una habilidad para crear y gestionar endpoints de API de manera efectiva. Permite una arquitectura escalable y mantenible.","fr":"Nuxt API Endpoint est une compétence pour créer et gérer des points de terminaison d''API de manière efficace. Il permet une architecture évolutiva et maintenable.","de":"Nuxt API Endpoint ist eine Fähigkeit, um Endpunkte von APIs effektiv zu erstellen und zu verwalten. Es ermöglicht eine skalierbare und wartbare Architektur.","pt":"O Nuxt API Endpoint é uma ferramenta poderosa para criar endpoints de API em aplicativos Nuxt.js, com suporte a Valibot e arquitetura em camadas.","ru":"Nuxt API Endpoint - это мощный инструмент для создания точек подключения API в приложениях Nuxt.js, с поддержкой Valibot и архитектурой в слоях.","ar":"نقطة نهاية API Nuxt هي أداة قوية لإنشاء نقاط نهاية API في تطبيقات Nuxt.js، مع دعم Valibot وعمارة متعددة الطبقات."},"seo":{"title":{"en":"nuxt-api-endpoint: API Endpoint Setup Guide for AI Agents","zh":"Nuxt API Endpoint Setup Guide - AIエージェント开发最佳实践","ja":"Nuxt API Endpoint セットアップガイド - AIエージェントのベストプラクティス","ko":"Nuxt API Endpoint 설정 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de Nuxt API Endpoint","fr":"Guide de mise en place de Nuxt API Endpoint","de":"Einrichtungsleitfaden für Nuxt API Endpoint","pt":"Guia de Configuração do Nuxt API Endpoint","ru":"Настройка Nuxt API Endpoint: Лучшие Практики","ar":"إعداد نقطة نهاية API Nuxt: دليل شامل"},"description":{"en":"Discover how to set up and use nuxt-api-endpoint for efficient API endpoint management. Learn the best practices and procedures for implementing this skill i...","zh":"了解如何使用 Nuxt API Endpoint 搭建强大的 API 接口，实现高效的数据交换和业务逻辑处理","ja":"Nuxt API Endpoint を使用して強力な API インターフェースを構築し、効率的なデータ交換とビジネスロジック処理を実現する方法を学びます","ko":"Nuxt API Endpoint를 사용하여 강력한 API 인터페이스를 구축하고 효율적인 데이터 교환 및 비즈니스 로직 처리를 실현하는 방법을 알아보세요","es":"Aprende a configurar y optimizar tus endpoints de API con Nuxt. Mejora la arquitectura y la escalabilidad de tus aplicaciones.","fr":"Découvrez comment configurer et optimiser vos points de terminaison d''API avec Nuxt. Améliorez l''architecture et la scalabilité de vos applications.","de":"Erfahren Sie, wie Sie Ihre API-Endpunkte mit Nuxt konfigurieren und optimieren. Verbessern Sie die Architektur und Skalierbarkeit Ihrer Anwendungen.","pt":"Aprenda a configurar o Nuxt API Endpoint com eficiência, incluindo Valibot e arquitetura em camadas","ru":"ИИ Агенты: Настройка Nuxt API Endpoint с помощью Valibot и архитектурой в слоях","ar":"تعلم كيفية إعداد نقطة نهاية API Nuxt باستخدام Valibot وعمارة متعددة الطبقات"},"definition":{"en":"nuxt-api-endpoint is a skill that provides guidelines and procedures for creating and managing API endpoints in Nuxt.js projects, ensuring consistency with the layer architecture","zh":"Nuxt API Endpoint 是一个用于构建 API 接口的工具，用于处理 HTTP 请求和响应","ja":"Nuxt API Endpoint は API インターフェースを構築するためのツールであり、HTTP リクエストとレスポンスを処理するために使用されます","ko":"Nuxt API Endpoint는 API 인터페이스를 구축하는 데 사용되는 도구로 HTTP 요청과 응답을 처리하는 데 사용됩니다","es":"Nuxt API Endpoint es una habilidad que permite crear endpoints de API con Nuxt, siguiendo una arquitectura escalable y mantenible.","fr":"Nuxt API Endpoint est une compétence qui permet de créer des points de terminaison d''API avec Nuxt, suivant une architecture évolutiva et maintenable.","de":"Nuxt API Endpoint ist eine Fähigkeit, die das Erstellen von API-Endpunkten mit Nuxt ermöglicht, unter Berücksichtigung einer skalierbaren und wartbaren Architektur.","pt":"Nuxt API Endpoint é uma funcionalidade que permite criar endpoints de API em aplicativos Nuxt.js","ru":"Nuxt API Endpoint - это функция, позволяющая создавать точки подключения API в приложениях Nuxt.js","ar":"نقطة نهاية API Nuxt هي ميزة تتيح إنشاء نقاط نهاية API في تطبيقات Nuxt.js"},"features":{"en":["Follows a structured architecture as outlined in `content/docs/ARCHITECTURE.md`","Utilizes `server/api/*` as the HTTP controller for parsing, validation, and use-case handling","Separates business logic into `domain/*` for maintainability","Requires schema extension in `shared/schemas/*` using Valibot","Ensures DTO types are properly defined and accessible"],"zh":["支持 Valibot 模式扩展","实现高效的数据交换和业务逻辑处理","提供 HTTP 控制器和 DTO 类型定义","遵循 ARCHITECTURE.md 和 remember.md 规范"],"ja":["Valibot スキーマの拡張をサポート","効率的なデータ交換とビジネスロジック処理を実現","HTTP コントローラーと DTO 型の定義を提供","ARCHITECTURE.md と remember.md 規約に従った設計"],"ko":["Valibot 스키마 확장을 지원","효율적인 데이터 교환 및 비즈니스 로직 처리를 실현","HTTP 컨트롤러 및 DTO 타입 정의 제공","ARCHITECTURE.md 및 remember.md 규약에 따른 설계"],"es":["Creación de endpoints de API con Nuxt","Arquitectura escalable y mantenible","Integración con Valibot para la validación de esquemas","Uso de DTO para la transferencia de datos","Segregación de la lógica de negocio en la capa de dominio"],"fr":["Création de points de terminaison d''API avec Nuxt","Architecture évolutiva et maintenable","Intégration avec Valibot pour la validation de schémas","Utilisation de DTO pour le transfert de données","Ségrégation de la logique métier dans la couche de domaine"],"de":["Erstellung von API-Endpunkten mit Nuxt","Skalierbare und wartbare Architektur","Integration mit Valibot für die Validierung von Schemata","Verwendung von DTO für den Datentransfer","Trennung der Geschäftslogik in der Domänen-Schicht"],"pt":["Suporte a Valibot para validação de esquemas","Arquitetura em camadas para organização de código","Criação de endpoints de API personalizados","Integração com o Nuxt.js","Suporte a DTO para transferência de dados"],"ru":["Поддержка Valibot для валидации схем","Архитектура в слоях для организации кода","Создание пользовательских точек подключения API","Интеграция с Nuxt.js","Поддержка DTO для передачи данных"],"ar":["دعم Valibot لتحقق من مخططات البيانات","بنية متعددة الطبقات لتنظيم الكود","إنشاء نقاط نهاية API مخصصة","التكامل مع Nuxt.js","دعم DTO لنقل البيانات"]},"keywords":{"en":["nuxt-api-endpoint setup guide","nuxt-api-endpoint tutorial","how to use nuxt-api-endpoint in AI agents","nuxt-api-endpoint vs RESTful API","nuxt-api-endpoint installation","nuxt-api-endpoint best practices for AI developers"],"zh":["Nuxt API Endpoint","AIエージェント开发","API 接口构建","Valibot 模式扩展","HTTP 控制器","DTO 类型定义","ARCHITECTURE.md","remember.md"],"ja":["Nuxt API Endpoint","AIエージェント開発","API インターフェース構築","Valibot スキーマ拡張","HTTP コントローラー","DTO 型定義","ARCHITECTURE.md","remember.md"],"ko":["Nuxt API Endpoint","AI 에이전트 개발","API 인터페이스 구축","Valibot 스키마 확장","HTTP 컨트롤러","DTO 타입 정의","ARCHITECTURE.md","remember.md"],"es":["Nuxt API Endpoint","creación de endpoints de API","arquitectura escalable","Valibot","DTO","lógica de negocio","desarrollo de aplicaciones","API RESTful"],"fr":["Nuxt API Endpoint","création de points de terminaison d''API","architecture évolutiva","Valibot","DTO","logique métier","développement d''applications","API RESTful"],"de":["Nuxt API Endpoint","Erstellung von API-Endpunkten","skalierbare Architektur","Valibot","DTO","Geschäftslogik","Anwendungsentwicklung","API RESTful"],"pt":["Nuxt API Endpoint","Valibot","Arquitetura em camadas","Endpoints de API","Nuxt.js","DTO","Desenvolvimento de aplicativos","API","ИИ Агенты"],"ru":["Nuxt API Endpoint","Valibot","Архитектура в слоях","Точки подключения API","Nuxt.js","DTO","Разработка приложений","API","ИИ Агенты"],"ar":["نقطة نهاية API Nuxt","Valibot","بنية متعددة الطبقات","نقاط نهاية API","Nuxt.js","DTO","تطوير التطبيقات","API","وكلاء الذكاء الاصطناعي"]}},"owner":"Auriaz","repo":"nuxt-stack-starter","repoPath":"Auriaz/nuxt-stack-starter","stars":0,"forks":0,"updatedAt":"2026-03-02T14:37:53Z","topics":[],"category":"community","skillMd":{"name":"nuxt-api-endpoint","description":"Tworzenie endpointów API w tym projekcie Nuxt zgodnie z flow schema -> server/api -> domain use-case -> repository -> DTO. Użyj, gdy dodajesz lub modyfikujesz endpoint HTTP.","bodyPreview":"# Nuxt API Endpoint\n\n## Kiedy używać\n\n- Gdy dodajesz nowy endpoint w `server/api/*`.\n- Gdy refaktorujesz endpoint i chcesz zachować zgodność z architekturą warstwową.\n\n## Zasady projektu\n\n- Przeczytaj i stosuj: `.cursor/remember.md` oraz `content/docs/ARCHITECTURE.md`.\n- `server/api/*` to tylko kontroler HTTP (parse -> validate -> use-case -> DTO).\n- Logika biznesowa należy do `domain/*`.\n\n## Procedura\n\n1. Dodaj/rozszerz schemat Valibot w `shared/schemas/*`.\n2. Upewnij się, że typy DTO są dostęp","body":"# Nuxt API Endpoint\n\n## Kiedy używać\n\n- Gdy dodajesz nowy endpoint w `server/api/*`.\n- Gdy refaktorujesz endpoint i chcesz zachować zgodność z architekturą warstwową.\n\n## Zasady projektu\n\n- Przeczytaj i stosuj: `.cursor/remember.md` oraz `content/docs/ARCHITECTURE.md`.\n- `server/api/*` to tylko kontroler HTTP (parse -> validate -> use-case -> DTO).\n- Logika biznesowa należy do `domain/*`.\n\n## Procedura\n\n1. Dodaj/rozszerz schemat Valibot w `shared/schemas/*`.\n2. Upewnij się, że typy DTO są dostępne przez `shared/types/*`.\n3. Zaimplementuj use-case w `domain/*` (bez zależności od UI).\n4. W kontrolerze `server/api/*`:\n   - odczytaj input (`getQuery`/`readBody`),\n   - zwaliduj przez Valibot,\n   - wywołaj use-case,\n   - zwróć dane w standardowym formacie API.\n5. Jeśli endpoint dotyka DB, użyj repository `server/repositories/*`.\n6. Dodaj/aktualizuj `app/composables/resources/*` jako jedyne miejsce wywołań API po stronie UI.\n\n## Walidacja\n\n- Lint i typecheck dla zmienionych plików.\n- Sprawdź przypadek `422 VALIDATION_ERROR` (mapowanie `issues[]`).\n- Sprawdź uprawnienia i błędy domenowe (`DomainError` -> status/code/message).\n"},"lastSynced":"2026-03-07T04:10:02.860Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents developing scalable Nuxt.js applications with structured API endpoints.","zh":"适合开发可扩展的 Nuxt.js 应用程序且具有结构化 API 端点的全栈代理。","ja":"スケーラブルな Nuxt.js アプリケーションを開発し、構造化された API エンドポイントを持つフルスタックエージェントに適しています。","ko":"스케일러블한 Nuxt.js 애플리케이션을 개발하고 구조화된 API 엔드포인트를 갖춘 풀스택 에이전트에게 적합합니다.","es":"Ideal para agentes Full Stack que desarrollan aplicaciones escalables Nuxt.js con puntos de conexión de API estructurados.","fr":"Idéal pour les agents Full Stack qui développent des applications Nuxt.js évolutives avec des points de terminaison d''API structurés.","de":"Ideal für Full-Stack-Agents, die skalierbare Nuxt.js-Anwendungen mit strukturierten API-Endpunkten entwickeln.","pt":"Ideal para Agentes Full Stack que desenvolvem aplicações escaláveis Nuxt.js com endpoints de API estruturados.","ru":"Идеально подходит для полноценных агентов, разрабатывающих масштабируемые приложения Nuxt.js с структурированными конечными точками API.","ar":"مثالي لعميليات Stack الكاملة التي تطور تطبيقات Nuxt.js القابلة للتوسع مع نهايات API منظمة."},"recommendation":{"en":"Empowers agents to create and manage standardized API endpoints in Nuxt.js projects, following a structured architecture with Valibot schema validation and DTO typing, leveraging HTTP controllers and domain logic separation.","zh":"赋予代理创建和管理标准化的 API 端点的能力，遵循结构化的架构，使用 Valibot 模式验证和 DTO 类型，利用 HTTP 控制器和域逻辑分离。","ja":"エージェントが標準化された API エンドポイントを作成して管理する能力を与え、構造化されたアーキテクチャに従い、Valibot スキーマ検証と DTO タイプを使用し、HTTP コントローラーとドメインロジックの分離を利用します。","ko":"에이전트가 표준화된 API 엔드포인트를 생성하고 관리할 수 있는 능력을 부여하며, 구조화된 아키텍처를 따르고 Valibot 스키마 검증 및 DTO 타이핑을 사용하며, HTTP 컨트롤러와 도메인 로직 분리를 활용합니다.","es":"Habilita a los agentes a crear y gestionar puntos de conexión de API estandarizados en proyectos Nuxt.js, siguiendo una arquitectura estructurada con validación de esquema Valibot y tipado de DTO, aprovechando controladores HTTP y separación de lógica de dominio.","fr":"Permet aux agents de créer et de gérer des points de terminaison d''API standardisés dans les projets Nuxt.js, en suivant une architecture structurée avec une validation de schéma Valibot et un typage de DTO, en exploitant les contrôleurs HTTP et la séparation de la logique de domaine.","de":"Ermächtigt die Agenten, standardisierte API-Endpunkte in Nuxt.js-Projekten zu erstellen und zu verwalten, indem sie eine strukturierte Architektur mit Valibot-Schemavalidierung und DTO-Typisierung befolgen, wobei HTTP-Controller und Domänenlogik-Trennung genutzt werden.","pt":"Habilita os agentes a criar e gerenciar endpoints de API padronizados em projetos Nuxt.js, seguindo uma arquitetura estruturada com validação de esquema Valibot e tipagem de DTO, aproveitando controladores HTTP e separação de lógica de domínio.","ru":"Наделяет агентов возможностью создавать и управлять стандартизированными конечными точками API в проектах Nuxt.js, следуя структурированной архитектуре с валидацией схемы Valibot и типизацией DTO, используя контроллеры HTTP и разделение доменной логики.","ar":"يُمكن للعميليات من إنشاء وإدارة نهايات API معيارية في مشاريع Nuxt.js، اتباعًا для هندسة معمارية منظمة مع التحقق من صحة مخطط Valibot وتصنيف DTO، واستخدام متحكمات HTTP وفصل منطق المجال."},"useCases":{"en":["Creating new API endpoints in server/api/*","Refactoring existing endpoints for compatibility with layered architecture","Implementing business logic in domain/*"],"zh":["在 server/api/* 中创建新的 API 端点","重构现有的端点以与分层架构兼容","在 domain/* 中实现业务逻辑"],"ja":["server/api/* に新しい API エンドポイントを作成する","既存のエンドポイントを層化アーキテクチャと互換性のあるようにリファクタリングする","domain/* にビジネスロジックを実装する"],"ko":["server/api/* 에서 새로운 API 엔드포인트를 생성하는 것","既存의 엔드포인트를 계층화된 아키텍처와 호환되는 방식으로 리팩토링하는 것","domain/* 에서 비즈니스 로직을 구현하는 것"],"es":["Crear nuevos puntos de conexión de API en server/api/*","Reestructurar puntos de conexión existentes para la compatibilidad con la arquitectura en capas","Implementar lógica empresarial en domain/*"],"fr":["Créer de nouveaux points de terminaison d''API dans server/api/*","Réorganiser les points de terminaison existants pour la compatibilité avec l''architecture en couches","Mettre en œuvre la logique métier dans domain/*"],"de":["Erstellen neuer API-Endpunkte in server/api/*","Umstrukturieren bestehender Endpunkte für die Kompatibilität mit der schichtbasierten Architektur","Implementieren von Geschäftlogik in domain/*"],"pt":["Criar novos endpoints de API em server/api/*","Reestruturar endpoints existentes para compatibilidade com arquitetura em camadas","Implementar lógica de negócios em domain/*"],"ru":["Создание новых конечных точек API в server/api/*","Переструктуризация существующих конечных точек для совместимости с многослойной архитектурой","Реализация бизнес-логики в domain/*"],"ar":["إنشاء نهايات API جديدة في server/api/*","إعادة هيكلة النهايات الحالية للتوافق مع هندسة معمارية متعددة الطبقات","تنفيذ منطق الأعمال في domain/*"]},"limitations":{"en":["Requires adherence to .cursor/remember.md and content/docs/ARCHITECTURE.md guidelines","Limited to Nuxt.js framework","Requires Valibot schema extension in shared/schemas/*"],"zh":[".cursor/remember.md 和 content/docs/ARCHITECTURE.md 指南的遵守是必需的","仅限于 Nuxt.js 框架","在 shared/schemas/* 中需要 Valibot 模式扩展"],"ja":[".cursor/remember.md と content/docs/ARCHITECTURE.md のガイドラインに従う必要がある","Nuxt.js フレームワークのみに限定される","shared/schemas/* に Valibot スキーマ拡張が必要"],"ko":[".cursor/remember.md 및 content/docs/ARCHITECTURE.md 가이드ライン을 따라야 함","Nuxt.js 프레임워크에만 제한됨","shared/schemas/* 에 Valibot 스키마 확장이 필요"],"es":["Requiere la adhesión a las directrices .cursor/remember.md y content/docs/ARCHITECTURE.md","Limitado al framework Nuxt.js","Requiere la extensión de esquema Valibot en shared/schemas/*"],"fr":["Nécessite l''adhésion aux directives .cursor/remember.md et content/docs/ARCHITECTURE.md","Limité au framework Nuxt.js","Nécessite l''extension de schéma Valibot dans shared/schemas/*"],"de":["Erfordert die Einhaltung der Richtlinien .cursor/remember.md und content/docs/ARCHITECTURE.md","Begrenzt auf das Nuxt.js-Framework","Erfordert die Valibot-Schema-Erweiterung in shared/schemas/*"],"pt":["Exige adesão às diretrizes .cursor/remember.md e content/docs/ARCHITECTURE.md","Limitado ao framework Nuxt.js","Exige extensão de esquema Valibot em shared/schemas/*"],"ru":["Требует соблюдения руководств .cursor/remember.md и content/docs/ARCHITECTURE.md","Ограничен фреймворком Nuxt.js","Требует расширения схемы Valibot в shared/schemas/*"],"ar":["يتطلب الالتزام bằngدوات .cursor/remember.md و content/docs/ARCHITECTURE.md","محدود بـ Nuxt.js الإطار","يتطلب امتداد مخطط Valibot في shared/schemas/*"]},"version":4},"contentHash":"4da43845ed05ae31987727d5041300ca2bbeb14890fb40509686360830fcac9a","qualityScore":29}');
