INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Auriaz/nuxt-stack-starter/nuxt-api-endpoint', 'nuxt-api-endpoint', 'Auriaz', 'nuxt-stack-starter', 'community', 'nuxt-api-endpoint Auriaz nuxt-stack-starter community The nuxt-api-endpoint skill enables developers to create and manage API endpoints in Nuxt.js projects, following a structured architecture. It benefits AI agent developers by providing a standardized approach to API development. Nuxt API Endpoint 是一个用于构建 API 接口的工具，帮助开发者实现高效的数据交换和业务逻辑处理 Nuxt API Endpoint は API インターフェースを構築するためのツールであり、開発者が効率的なデータ交換とビジネスロジック処理を実現するのに役立ちます Nuxt API Endpoint는 API 인터페이스를 구축하는 데 사용되는 도구로 개발자가 효율적인 데이터 교환 및 비즈니스 로직 처리를 실현하는 데 도움을 줍니다 Nuxt API Endpoint es una habilidad para crear y gestionar endpoints de API de manera efectiva. Permite una arquitectura escalable y mantenible. Nuxt API Endpoint est une compétence pour créer et gérer des points de terminaison d''API de manière efficace. Il permet une architecture évolutiva et maintenable. Nuxt API Endpoint ist eine Fähigkeit, um Endpunkte von APIs effektiv zu erstellen und zu verwalten. Es ermöglicht eine skalierbare und wartbare Architektur. O Nuxt API Endpoint é uma ferramenta poderosa para criar endpoints de API em aplicativos Nuxt.js, com suporte a Valibot e arquitetura em camadas. Nuxt API Endpoint - это мощный инструмент для создания точек подключения API в приложениях Nuxt.js, с поддержкой Valibot и архитектурой в слоях. نقطة نهاية API Nuxt هي أداة قوية لإنشاء نقاط نهاية API في تطبيقات Nuxt.js، مع دعم Valibot وعمارة متعددة الطبقات. nuxt-api-endpoint setup guide nuxt-api-endpoint tutorial how to use nuxt-api-endpoint in AI agents nuxt-api-endpoint vs RESTful API nuxt-api-endpoint installation nuxt-api-endpoint best practices for AI developers Nuxt API Endpoint AIエージェント开发 API 接口构建 Valibot 模式扩展 HTTP 控制器 DTO 类型定义 ARCHITECTURE.md remember.md Follows a structured architecture as outlined in `content/docs/ARCHITECTURE.md` Utilizes `server/api/*` as the HTTP controller for parsing, validation, and use-case handling Separates business logic into `domain/*` for maintainability Requires schema extension in `shared/schemas/*` using Valibot Ensures DTO types are properly defined and accessible nuxt-api-endpoint is a skill that provides guidelines and procedures for creating and managing API endpoints in Nuxt.js projects, ensuring consistency with the layer architecture');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('axsh/kuniumi/create-specification', 'community', 'axsh', 'kuniumi', 'axsh/kuniumi', 'create-specification', 0, 0, 29, '2026-02-25T12:23:44Z', '2026-03-07T04:09:43.822Z', 'bae7fb569e8341e0c55e09838b5ee8c7580516264748fc45e7197b8d0fe1bb6c', '{"id":"axsh/kuniumi/create-specification","name":"create-specification","description":{"en":"The create-specification skill generates structured specification documents from user input, utilizing scripts like show_current_status.sh for status checks and output location determination.","zh":"create-specification 技能创建结构化规范文档，使用 Kuniumi 框架和 Go 语言","ja":"create-specification スキルは、Kuniumi フレームワークと Go 言語を使用して構造化された仕様書を作成します","ko":"create-specification 기술은 Kuniumi 프레임워크와 Go 언어를 사용하여 구조화된 규격 문서를 생성합니다","es":"Create-specification es un skill que crea documentos de especificación estructurados desde ideas y requisitos del usuario, utilizando Go y varios interfaces como HTTP, CGI, MCP y contenedores Docker","fr":"Create-specification est un skill qui crée des documents de spécification structurés à partir d''idées et d''exigences de l''utilisateur, en utilisant Go et diverses interfaces telles que HTTP, CGI, MCP et conteneurs Docker","de":"Create-specification ist ein Skill, der strukturierte Spezifikationsdokumente aus Benutzerideen und -anforderungen erstellt, indem er Go und verschiedene Schnittstellen wie HTTP, CGI, MCP und Docker-Container verwendet","pt":"O Create-Specification é um framework que permite expor funções em Go como serviços web portáteis, criando especificações estruturadas a partir de ideias e requisitos do usuário","ru":"Create-Specification - это фреймворк, который позволяет экспонировать функции на Go как веб-сервисы, создавая структурированные спецификации из идей и требований пользователя","ar":"Create-Specification هو إطار عمل يسمح بتعرض دوال Go كخدمات ويب