INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('axsh/kuniumi/create-specification', 'create-specification', 'axsh', 'kuniumi', 'community', 'create-specification axsh kuniumi community The create-specification skill generates structured specification documents from user input, utilizing scripts like show_current_status.sh for status checks and output location determination. create-specification 技能创建结构化规范文档，使用 Kuniumi 框架和 Go 语言 create-specification スキルは、Kuniumi フレームワークと Go 言語を使用して構造化された仕様書を作成します create-specification 기술은 Kuniumi 프레임워크와 Go 언어를 사용하여 구조화된 규격 문서를 생성합니다 Create-specification es un skill que crea documentos de especificación estructurados desde ideas y requisitos del usuario, utilizando Go y varios interfaces como HTTP, CGI, MCP y contenedores Docker Create-specification est un skill qui crée des documents de spécification structurés à partir d''idées et d''exigences de l''utilisateur, en utilisant Go et diverses interfaces telles que HTTP, CGI, MCP et conteneurs Docker Create-specification ist ein Skill, der strukturierte Spezifikationsdokumente aus Benutzerideen und -anforderungen erstellt, indem er Go und verschiedene Schnittstellen wie HTTP, CGI, MCP und Docker-Container verwendet O Create-Specification é um framework que permite expor funções em Go como serviços web portáteis, criando especificações estruturadas a partir de ideias e requisitos do usuário Create-Specification - это фреймворк, который позволяет экспонировать функции на Go как веб-сервисы, создавая структурированные спецификации из идей и требований пользователя Create-Specification هو إطار عمل يسمح بتعرض دوال Go كخدمات ويب محمولة، من خلال إنشاء مواصفات منظمة من أفكار ومتطلبات المستخدم how to use create-specification create-specification setup guide what is create-specification create-specification alternative create-specification vs Kuniumi create-specification install generate structured specification documents create-specification workflow creation create-specification and Go language Kuniumi 框架 create-specification 技能 Go 语言 结构化规范文档 可移植的 Web 服务 AIエージェント 技术文档创建 Generates structured specification documents in Markdown format Utilizes scripts/utils/show_current_status.sh for status checks Extracts phase, branch, and next_idea_id from JSON output Determines output location based on phase and directory structure Supports creation of ideas and requirements in a portable format create-specification is a skill that creates structured specification documents from user-provided ideas and requirements, utilizing a workflow with specific scripts and directory structures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('j-roche-dev/personal-planner/daily-checkin', 'community', 'j-roche-dev', 'personal-planner', 'j-roche-dev/personal-planner', 'daily-checkin', 0, 0, 29, '2026-03-03T19:56:40Z', '2026-03-07T04:12:42.760Z', '279ce15ca378e152175cb3a5c09ac3b6e94895a0127dddf4726ff2e9b4bd6d39', '{"id":"j-roche-dev/personal-planner/daily-checkin","name":"daily-checkin","description":{"en":"The daily-checkin skill enables AI agents to perform morning check-ins, reviewing yesterday''s activities and planning today''s tasks. It benefits developers by streamlining their daily workflow.","zh":"日常签到技能使用Bash和npm实现自动化，通过date命令获取实际日期和时间，实现个性化问候","ja":"デイリー チェックイン スキルは、Bashとnpmを使用して自動化を実現し、dateコマンドで実際の日付と時間を取得し、個性化された挨拶を行います","ko":"일일 체크인 스킬은 Bash와 npm을 사용하여 자동화를 구현하며, date 명령을 통해 실제 날짜와 시간을 가져와 개인화된 인사를 제공합니다","es":"daily-checkin es una habilidad que facilita la gestión del tiempo con autenticación y programación. Utiliza Bash para ejecutar comandos y gestionar tokens de expiración","fr":"daily-checkin est une compétence qui facilite la gestion du temps avec authentification et planification. Elle utilise Bash pour exécuter des commandes et gérer les jetons d''expiration","de":"daily-checkin ist eine Fähigkeit, die die Zeitverwaltung mit Authentifizierung und Zeitplanung erleichtert. Sie verwendet Bash, um Befehle auszuführen und Ablaufzeichen zu verwalten","pt":"O Daily Check-In é uma ferramenta de automação que ajuda a gerenciar o tempo com check-in diário e planejamento","ru":"Ежедневный Чек-ин - это инструмент автоматизации, помогающий управлять временем с помощью ежедневного чек-ина и планирования от ИИ Агентов","ar":"체크-인 يومي هو أداة تautomatioن تساعد في إدارة الوقت مع 체크-ين يومي وتخطيط"},"seo":{"title":{"en":"daily-checkin: Setup Guide for AI Agents","zh":"日常签到Setup Guide：使用Bash和npm进行自动化","ja":"デイリー チェックイン Setup Guide：Bashとnpmを使用した自動化","ko":"일일 체크인 Setup Guide: Bash와 npm을 사용한 자동화","es":"Guía de Configuración de daily-checkin: Autenticación y P...","fr":"Guide d''Installation de daily-checkin: Authentification e...","de":"Einrichtungsleitfaden für daily-checkin: Authentifizierun...","pt":"Guia de Configuração do Daily Check-In: Automação de Chec...","ru":"Настройка Ежедневного Чек-ина: ИИ Агенты для Управления В...","ar":"دليل إعداد 체ك-ين يومي: أدوات ذكاء اصطناعي لتحسين الإنتاجية"},"description":{"en":"Discover how to implement daily-checkin for your AI agent, featuring Bash commands and npm authentication. Get started with our expert guide today!","zh":"了解如何使用日常签到技能，通过Bash和npm实现自动化，提高开发效率","ja":"デイリー チェックイン スキルを使用して、Bashとnpmで自動化を実現し、開発効率を向上させる方法を学びます","ko":"일일 체크인 스킬을 사용하여 Bash와 npm으로 자동화를 구현하고 개발 효율을 높이는 방법에 대해 알아보세요","es":"Aprende a configurar daily-checkin con autenticación y programación para una gestión eficiente del tiempo","fr":"Découvrez comment installer daily-checkin avec authentification et planification pour une gestion efficace du temps","de":"Erfahren Sie, wie Sie daily-checkin mit Authentifizierung und Zeitplanung für eine effiziente Zeitverwaltung einrichten","pt":"Aprenda a configurar o Daily Check-In para aumentar a produtividade com ferramentas de automação e gerenciamento de tempo","ru":"Узнайте, как настроить Ежедневный Чек-ин для повышения производительности с помощью инструментов автоматизации и управления временем от ИИ Агентов","ar":"تعرف على كيفية إعداد 체크-ين يومي لتحسين الإنتاجية باستخدام أدوات التutomatioن والتحكم في الوقت من أدوات الذكاء الاصطناعي"},"definition":{"en":"daily-checkin is a conversational AI skill that facilitates morning check-ins with a two-part review and planning process, utilizing Bash and npm for execution.","zh":"日常签到是一种使用Bash和npm实现自动化的技能，用于个性化问候和规划","ja":"デイリー チェックインは、Bashとnpmを使用して自動化を実現するスキルであり、個性化された挨拶と計画を行うために使用されます","ko":"일일 체크인은 Bash와 npm을 사용하여 자동화를 구현하는 스킬로서 개인화된 인사와 계획을 위해 사용됩니다","es":"daily-checkin es una habilidad de AI que realiza un chequeo diario con autenticación y programación","fr":"daily-checkin est une compétence d''IA qui effectue un contrôle quotidien avec authentification et planification","de":"daily-checkin ist eine KI-Fähigkeit, die ein tägliches Check-in mit Authentifizierung und Zeitplanung durchführt","pt":"O Daily Check-In é uma ferramenta de automação que realiza check-in diário e planejamento","ru":"Ежедневный Чек-ин - это инструмент автоматизации, который выполняет ежедневный чек-ин и планирование","ar":"체크-인 يومي هو أداة تautomatioن تقوم بتشغيل 체크-ين يومي وتخطيط"},"features":{"en":["Runs `date \"+%A %B %d %Y %l:%M %p\"` via Bash to determine the actual day of week, date, and time","Uses npm to re-authenticate via `npm run auth` in case of token expiry errors","Supports conversational greetings based on the time of day (good morning/afternoon/evening)","Enables planning and review of daily activities through a conversational interface"],"zh":["使用Bash的date命令获取实际日期和时间","通过npm run auth实现重新认证","个性化问候和规划","自动化日常任务","支持多种日期和时间格式"],"ja":["Bashのdateコマンドを使用して実際の日付と時間を取得","npm run authを使用して再認証を実現","個性化された挨拶と計画","自動化された日常タスク","複数の日付と時間形式をサポート"],"ko":["Bash의 date 명령을 사용하여 실제 날짜와 시간을 가져옴","npm run auth를 사용하여 재인증을 구현","개인화된 인사와 계획","자동화된 일일 작업","다양한 날짜와 시간 형식을 지원"],"es":["Utiliza Bash para ejecutar comandos","Autenticación con npm run auth","Gestión de tokens de expiración","Planificación del día con date y tiempo","Compatibilidad con CLI"],"fr":["Utilise Bash pour exécuter des commandes","Authentification avec npm run auth","Gestion des jetons d''expiration","Planification de la journée avec date et heure","Compatibilité avec CLI"],"de":["Verwendet Bash, um Befehle auszuführen","Authentifizierung mit npm run auth","Verwaltung von Ablaufzeichen","Zeitplanung des Tages mit Datum und Uhrzeit","Kompatibilität mit CLI"],"pt":["Utiliza o comando `date` para obter o dia da semana e data","Executa `npm run auth` para reautenticar em caso de token expirado","Realiza check-in diário com revisão do dia anterior e planejamento do dia atual","Utiliza Bash para executar comandos","Integração com ferramentas de calendário"],"ru":["Использует команду `date` для получения дня недели и даты","Выполняет `npm run auth` для переавторизации в случае истечения срока действия токена","Выполняет ежедневный чек-ин с обзором предыдущего дня и планированием текущего дня","Использует Bash для выполнения команд","Интеграция с инструментами календаря от ИИ Агентов"],"ar":["يستخدم الأمر `date` لاستخراج يوم الأسبوع والتاريخ","ينفذ `npm run auth` لإعادة المصادقة في حالة انتهاء صلاحية العلامة","يقوم بتشغيل 체크-ين يومي مع استعراض اليوم السابق وتخطيط اليوم الحالي","يستخدم Bash لتشغيل الأوامر","التكامل مع أدوات التقويم من أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use daily-checkin","daily-checkin setup guide","daily-checkin vs other AI skills","daily-checkin install","what is daily-checkin","daily-checkin alternative","daily-checkin for AI agents","daily-checkin tutorial","daily-checkin and Bash","daily-checkin and npm"],"zh":["日常签到","Bash自动化","npm脚本","date命令","个性化问候","自动化日常任务","AI工具","AIエージェント"],"ja":["デイリー チェックイン","Bash自動化","npmスクリプト","dateコマンド","個性化された挨拶","自動化された日常タスク","AIエージェント","AIツール"],"ko":["일일 체크인","Bash 자동화","npm 스크립트","date 명령","개인화된 인사","자동화된 일일 작업","AI 에이전트","AI 도구"],"es":["daily-checkin","autenticación AI","programación diaria","gestión del tiempo","Bash","npm run auth","CLI","tokens de expiración"],"fr":["daily-checkin","authentification IA","planification quotidienne","gestion du temps","Bash","npm run auth","CLI","jetons d''expiration"],"de":["daily-checkin","Authentifizierung KI","tägliche Planung","Zeitverwaltung","Bash","npm run auth","CLI","Ablaufzeichen"],"pt":["daily check-in","automação de check-in","gerenciamento de tempo","ferramentas de automação","Bash","npm","calendário","produtividade"],"ru":["Ежедневный Чек-ин","автоматизация чек-ина","управление временем","инструменты автоматизации","Bash","npm","календарь","производительность","ИИ Агенты"],"ar":["체크-인 يومي","تautomatioن 체크-ين","إدارة الوقت","أدوات التautomatioن","Bash","npm","التقويم","الإنتاجية","أدوات الذكاء الاصطناعي"]}},"owner":"j-roche-dev","repo":"personal-planner","repoPath":"j-roche-dev/personal-planner","stars":0,"forks":0,"updatedAt":"2026-03-03T19:56:40Z","topics":[],"category":"community","skillMd":{"name":"daily-checkin","description":"Morning check-in with yesterday review and todays plan (~3-5 min)","bodyPreview":"# Daily Check-In\n\nMorning check-in with two parts: review yesterday, plan today. Keep it conversational but concise.\n\n## Before Starting\n\n- **Check the time first:** Run `date \"+%A %B %d %Y %l:%M %p\"` via Bash to get the actual day of week, date, and time. Use this for greeting (good morning/afternoon/evening) and all date logic below. Never calculate the day of week mentally.\n- **Token expiry:** If any calendar tool returns a token expiry error, run `npm run auth` via Bash to re-authenticate. W","body":"# Daily Check-In\n\nMorning check-in with two parts: review yesterday, plan today. Keep it conversational but concise.\n\n## Before Starting\n\n- **Check the time first:** Run `date \"+%A %B %d %Y %l:%M %p\"` via Bash to get the actual day of week, date, and time. Use this for greeting (good morning/afternoon/evening) and all date logic below. Never calculate the day of week mentally.\n- **Token expiry:** If any calendar tool returns a token expiry error, run `npm run auth` via Bash to re-authenticate. Wait for the user to complete the browser OAuth flow, then retry.\n- Fetch the user''s profile (`profile_get`) — use their name and goals for context throughout.\n- Check today''s day of week (from the `date` output above):\n  - **Saturday/Sunday** → suggest `/weekend-checkin` instead (lighter touch for weekends).\n  - **Sunday evening or the user''s preferred planning day** → mention that `/weekly-planning` or `/weekly-review` might be due.\n- If `$ARGUMENTS` contains `skip-yesterday`, jump straight to Part 2.\n\n## Part 1 — Yesterday Review\n\n1. Fetch yesterday''s checklist (`checklist_get` with yesterday''s date) for any still-open items.\n   Ask: \"Did you finish these, or should they carry over?\"\n   **Tip:** When marking yesterday''s items complete, use `checklist_update` with `date` set to yesterday''s date — this triggers a cascade that auto-completes carried-over copies in today''s checklist.\n2. Fetch yesterday''s daily log (`daily_log_get`). If habits weren''t logged, ask briefly about each.\n3. Ask for a quick reflection: \"How was yesterday? One sentence is fine.\"\n   Optionally ask mood (great/good/okay/rough/bad) and energy (1-5) if it feels natural.\n4. Save yesterday''s log with the updated habits and reflection (`daily_log_update`).\n\n## Part 2 — Today''s Plan\n\n5. Fetch today''s calendar events and run `schedule_analyze`.\n6. Fetch today''s checklist with `checklist_get`.\n7. Create today''s daily log with habits pre-populated (`daily_log_update` with `plannedHighlights`).\n8. Brief overview: events, density, conflicts, warnings.\n9. Highlight the most important event and top checklist items.\n10. Show free slots and suggest an order of attack.\n\n## Launch Dashboard\n\nAfter presenting the plan, ensure the dashboard is running:\n- Start the Vite dev server if not already running: `cd dashboard && npm run dev` (run in background)\n- Open the browser: `open http://localhost:5173`\n\n## Throughout the Day\n\nWhen the user completes checklist items outside of the morning check-in, follow the **Item Completion Workflow** in CLAUDE.md — mark the item done, prompt for billing info if the area is billable, and update the daily log''s `actualHighlights`.\n\nWhen the checklist changes significantly (items added/removed, priorities shifted), consider updating `plannedHighlights` via `daily_log_update` — see **Planned Highlights Revisit** in CLAUDE.md.\n\n## Tone\n\nConversational, brief, encouraging. Don''t over-explain — the user does this daily. If yesterday was rough, acknowledge it without dwelling. Focus energy on today''s plan.\n"},"lastSynced":"2026-03-07T04:12:42.760Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring automated daily workflow streamlining and calendar integration.","zh":"适合需要自动化日常工作流程优化和日历集成的任务管理代理。","ja":"タスク管理エージェントが自動化された日常のワークフローをストリーミングし、カレンダー統合を必要とする場合に最適です。","ko":"자동화된 일일 워크플로우 스트리밍 및 캘린더 통합을 필요로 하는 태스크 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de tareas que requieren una automatización diaria de flujo de trabajo y una integración con calendarios.","fr":"Idéal pour les agents de gestion de tâches nécessitant une automatisation quotidienne du flux de travail et une intégration avec les calendriers.","de":"Ideal für Task-Management-Agents, die eine automatisierte tägliche Workflowsynchronisierung und eine Kalenderintegration erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que exigem otimização do fluxo de trabalho diário automatizado e integração de calendário.","ru":"Идеально для агентов по управлению задачами, требующих автоматизированной оптимизации ежедневного рабочего процесса и интеграции календаря.","ar":"مثالي لعمليات إدارة المهام التي تتطلب تسهيلات تدفق العمل اليومي الآلي وتكامل التقويم."},"recommendation":{"en":"Empowers agents to perform morning check-ins, reviewing yesterday''s activities and planning today''s tasks using Bash scripts and calendar tools, while handling token expiry errors through npm authentication.","zh":"赋予代理人执行早晨检查、使用Bash脚本和日历工具查看昨日活动并规划今日任务的能力，同时通过npm身份验证处理令牌过期错误。","ja":"エージェントがBashスクリプトとカレンダーツールを使用して昨日のアクティビティを確認し、今日のタスクを計画し、npm認証を介してトークンの有効期限エラーを処理する能力を提供します。","ko":"에이전트가 Bash 스크립트와 캘린더 툴을 사용하여 어제의 활동을 검토하고 오늘의 태스크를 계획하며, npm 인증을 통해 토큰 만료 오류를 처리할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a realizar verificaciones matutinas, revisar las actividades de ayer y planificar las tareas de hoy utilizando scripts de Bash y herramientas de calendario, mientras maneja errores de expiración de token a través de la autenticación de npm.","fr":"Permet aux agents d''effectuer des vérifications matinales, de passer en revue les activités de la veille et de planifier les tâches d''aujourd''hui en utilisant des scripts Bash et des outils de calendrier, tout en gérant les erreurs d''expiration de token via l''authentification npm.","de":"Ermächtigt die Agenten, morgendliche Prüfungen durchzuführen, gestriges Aktivitäten zu überprüfen und heute Aufgaben mit Bash-Skripten und Kalendertools zu planen, während Token-Abgelaufene-Fehler durch npm-Authentifizierung behandelt werden.","pt":"Habilita os agentes a realizar check-ins matutinos, revisando as atividades de ontem e planejando as tarefas de hoje usando scripts Bash e ferramentas de calendário, enquanto lida com erros de expiração de token por meio da autenticação npm.","ru":"Наделяет агентов возможностью выполнять утренние проверки, просматривая вчерашние活動ности и планируя сегодняшние задачи с помощью скриптов Bash и инструментов календаря, а также обрабатывать ошибки истечения срока действия токена через аутентификацию npm.","ar":"تمكّن الوكلاء من أداء الفحوصات الصباحية، ومراجعة الأنشطة السابقة وتنظيم المهام الحالية باستخدام سكريبتات Bash وأدوات التقويم، مع معالجة أخطاء انتهاء صلاحية Token من خلال المصادقة npm."},"useCases":{"en":["Automating daily task planning","Reviewing previous day''s activities","Handling calendar token expiry errors"],"zh":["自动化日常任务规划","查看前一天的活动","处理日历令牌过期错误"],"ja":["日常タスクの自動化","昨日のアクティビティの確認","カレンダートークンの有効期限エラーの処理"],"ko":["일일 태스크 자동화","전날의 활동 검토","캘린더 토큰 만료 오류 처리"],"es":["Automatización de la planificación de tareas diarias","Revisión de las actividades del día anterior","Manejo de errores de expiración de token de calendario"],"fr":["Automatisation de la planification des tâches quotidiennes","Révision des activités de la veille","Gestion des erreurs d''expiration de token de calendrier"],"de":["Automatisierung der täglichen Aufgabenplanung","Überprüfung der Aktivitäten des Vortages","Behandlung von Token-Abgelaufene-Fehlern in Kalendern"],"pt":["Automatizar a planejamento de tarefas diárias","Revisar as atividades do dia anterior","Lidar com erros de expiração de token do calendário"],"ru":["Автоматизировать планирование ежедневных задач","Просматривать вчерашние actividades","Обрабатывать ошибки истечения срока действия токена календаря"],"ar":["تسهيل مهام التخطيط اليومي","مراجعة الأنشطة السابقة","معالجة أخطاء انتهاء صلاحية Token للتقويم"]},"limitations":{"en":["Requires Bash support for date and time retrieval","Needs npm for authentication","Dependent on external calendar tools"],"zh":["需要Bash支持以检索日期和时间","需要npm进行身份验证","依赖于外部日历工具"],"ja":["日付と時刻の取得のためにBashのサポートが必要","認証のためにnpmが必要","外部カレンダーツールに依存する"],"ko":["날짜 및 시간检출을 위해 Bash 지원이 필요","인증을 위해 npm가 필요","외부 캘린더 툴에 의존"],"es":["Requiere soporte de Bash para la recuperación de fecha y hora","Necesita npm para la autenticación","Depende de herramientas de calendario externas"],"fr":["Nécessite un support Bash pour la récupération de date et d''heure","A besoin de npm pour l''authentification","Dépend de outils de calendrier externes"],"de":["Benötigt Bash-Unterstützung für die Abrufung von Datum und Uhrzeit","Benötigt npm für die Authentifizierung","Hängt von externen Kalendertools ab"],"pt":["Exige suporte Bash para recuperação de data e hora","Necessita npm para autenticação","Dependente de ferramentas de calendário externas"],"ru":["Требует поддержки Bash для получения даты и времени","Требует npm для аутентификации","Зависит от внешних инструментов календаря"],"ar":["يتطلب دعم Bash لاسترجاع التاريخ والوقت","يحتاج npm للمصادقة","يعتمد على أدوات التقويم الخارجية"]},"version":4},"contentHash":"279ce15ca378e152175cb3a5c09ac3b6e94895a0127dddf4726ff2e9b4bd6d39","qualityScore":29}');
