INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fnuAshutosh/Medimind/gsd-quick', 'gsd-quick', 'fnuAshutosh', 'Medimind', 'community', 'gsd-quick fnuAshutosh Medimind community gsd-quick is a skill that automates workflows by invoking commands via $gsd-quick. It benefits developers by streamlining interactions with AI agents. gsd-quick是一种高效的开发工具，支持AskUserQuestion和request_user_input功能 gsd-quickは効率的な開発ツールで、AskUserQuestionとrequest_user_input機能をサポート gsd-quick는 효율적인 개발 도구로 AskUserQuestion와 request_user_input 기능을 지원 gsd-quick es una habilidad de AI que se invoca mediante la mención de $gsd-quick, permitiendo el procesamiento de texto avanzado gsd-quick est une compétence IA invoquée via la mention de $gsd-quick, permettant un traitement de texte avancé gsd-quick ist eine KI-Fähigkeit, die durch die Erwähnung von $gsd-quick aufgerufen wird und erweiterte Textverarbeitung ermöglicht O gsd-quick é uma habilidade AI que permite invocar funções com argumentos personalizados, facilitando a integração com workflows de GSD Gsd-quick - это ИИ Агент, который позволяет вызывать функции с настраиваемыми аргументами, упрощая интеграцию с рабочими процессами GSD gsd-quick هو وسيط ذكاء اصطناعي يسمح باستدعاء الوظائف بالحجج المخصصة، مما يسهل التكامل مع سير عمل GSD how to use gsd-quick gsd-quick alternative gsd-quick setup guide what is gsd-quick gsd-quick vs other AI agent skills gsd-quick install gsd-quick workflow automation gsd-quick command invocation gsd-quick parameter mapping gsd-quick AI开发工具 AskUserQuestion request_user_input 开发语言 集成和开发 效率开发 开发工具 Invokes workflows using $gsd-quick command Maps AskUserQuestion to request_user_input for seamless interactions Supports parameter mapping for header, question, and options Treats user text after $gsd-quick as {{GSD_ARGS}} for flexible input handling Handles empty {{GSD_ARGS}} for default workflow execution gsd-quick is an AI agent skill that enables efficient workflow automation through command invocation and parameter mapping.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yiyousiow000814/XAUUSD-Calendar-Agent/ui-check-framework', 'community', 'yiyousiow000814', 'XAUUSD-Calendar-Agent', 'yiyousiow000814/XAUUSD-Calendar-Agent', 'ui-check-framework', 0, 0, 29, '2026-03-07T01:49:01.609Z', '2026-03-07T02:13:25.390Z', '2d107e4224db90e7d2524051832e87ff3a0e99baa61d7795fd3b5e3ef88004b5', '{"id":"yiyousiow000814/XAUUSD-Calendar-Agent/ui-check-framework","name":"ui-check-framework","description":{"en":"The ui-check-framework skill creates an automated UI self-check system, discovering UI blocks via data-qa tags and enforcing behavioral contracts. It benefits developers by scaling to new UI components without requiring new test cases.","zh":"UI Check Framework 是一个用于自动化 UI 测试的框架，通过数据标签和行为视觉契约来发现 UI 块","ja":"UI Check Framework は、データタグとビジュアル契約を使用して UI ブロックを自動的に検出するフレームワークです","ko":"UI Check Framework는 데이터 태그와 행동 시각 계약을 통해 UI 블록을 자동으로 발견하는 프레임워크입니다","es":"El framework ui-check es un sistema de autocomprobación de interfaz de usuario que utiliza etiquetas data-qa para detectar bloques de interfaz de usuario y hacer cumplir contratos de comportamiento y visuales.","fr":"Le framework ui-check est un système d''auto-vérification de l''interface utilisateur qui utilise des balises data-qa pour détecter les blocs d''interface utilisateur et faire respecter les contrats de comportement et visuels.","de":"Das ui-check-Framework ist ein System zur Selbstüberprüfung von Benutzeroberflächen, das data-qa-Tags verwendet, um Benutzeroberflächenblöcke zu erkennen und Verträge für Verhalten und Visualisierung durchzusetzen.","pt":"O ui-check-framework é uma ferramenta de automação de UI que descobre blocos de UI via tags data-qa e impõe contratos comportamentais e visuais","ru":"ИИ Агент ui-check-framework - это инструмент для автоматизации UI, который обнаруживает блоки UI через теги data-qa и обеспечивает поведенческие и визуальные контракты","ar":"وحدات ui-check-framework هي أداة لتحسين واجهة المستخدم التي تكتشف الكتل من خلال وسوم data-qa وتنفذ العقود السلوكية والبصرية"},"seo":{"title":{"en":"ui-check-framework: Automated UI Testing Setup Guide | AI...","zh":"UI 自动化测试框架 Setup Guide - UI Check Framework","ja":"UI 自動化テストフレームワークのベストプラクティス - UI Check Framework AIエージェント","ko":"UI 자동화 테스트 프레임워크 설정 가이드 - UI Check Framework","es":"Guía de configuración de ui-check-framework para agentes ...","fr":"Mise en place du framework ui-check pour les agents d''IA","de":"Einrichtungsleitfaden für ui-check-framework bei KI-Agents","pt":"Guia de Configuração do ui-check-framework para Automação...","ru":"Настройка ИИ Агентов: ui-check-framework для Автоматизаци...","ar":"دليل إعداد ui-check-framework لتحسين واجهة المستخدم"},"description":{"en":"Discover how to create a scalable UI self-check system with ui-check-framework. Learn to enforce behavioral contracts and automate testing for new UI compone...","zh":"了解 UI Check Framework 如何自动化 UI 测试，提高开发效率，缩短测试时间","ja":"UI Check Framework を使用して UI 自動化テストを実施し、開発効率を向上させる方法を学びましょう","ko":"UI Check Framework를 사용하여 UI 자동화 테스트를 구현하고 개발 효율성을 높이는 방법을 알아보세요","es":"Descubre cómo implementar ui-check-framework para automatizar la verificación de interfaz de usuario en tus proyectos de desarrollo con agentes de inteligenc...","fr":"Découvrez comment mettre en place le framework ui-check pour automatiser la vérification de l''interface utilisateur dans vos projets de développement avec de...","de":"Erfahren Sie, wie Sie ui-check-framework implementieren, um die Benutzeroberflächenprüfung in Ihren Entwicklungsprojekten mit KI-Agents zu automatisieren","pt":"Aprenda a configurar o ui-check-framework para automatizar testes de UI e melhorar a experiência do usuário com contratos comportamentais e visuais","ru":"Узнайте, как настроить ui-check-framework для автоматизации тестирования UI и улучшения пользовательского опыта с помощью поведенческих и визуальных контрактов","ar":"تعرف على كيفية إعداد ui-check-framework لتحسين تجربة المستخدم وتحقيق التطابق السلوكي والبصري"},"definition":{"en":"ui-check-framework is an automated UI testing framework that discovers UI blocks and enforces behavioral and visual contracts for themes, animations, and layout stability.","zh":"UI Check Framework 是一个自动化 UI 测试的工具，用于发现和验证 UI 组件的行为和视觉表现","ja":"UI Check Framework は、UI コンポーネントの動作とビジュアル表現を自動的に検証するツールです","ko":"UI Check Framework는 UI 컴포넌트의 동작과 시각적 표현을 자동으로 검증하는 도구입니다","es":"El framework ui-check es un sistema de autocomprobación de interfaz de usuario que utiliza tecnologías de automatización para detectar y corregir errores en la interfaz de usuario.","fr":"Le framework ui-check est un système d''auto-vérification de l''interface utilisateur qui utilise des technologies d''automatisation pour détecter et corriger les erreurs dans l''interface utilisateur.","de":"Das ui-check-Framework ist ein System zur Selbstüberprüfung von Benutzeroberflächen, das Automatisierungstechnologien verwendet, um Fehler in der Benutzeroberfläche zu erkennen und zu korrigieren.","pt":"ui-check-framework é um sistema de auto-verificação de UI que garante a estabilidade e a usabilidade da interface do usuário","ru":"ui-check-framework - это система самопроверки UI, обеспечивающая стабильность и удобство пользовательского интерфейса","ar":"ui-check-framework هو نظام للتحقق من واجهة المستخدم التي يضمن الاستقرار وسهولة استخدام الواجهة"},"features":{"en":["Discovers UI blocks via data-qa tags","Enforces behavioral and visual contracts for themes and animations","Ensures layout stability and modal usability","Supports scaling to new cards, modals, and actions without new test cases","Utilizes existing project scaffolding in the ui-tests/ folder","Enforces error visibility and loading contracts"],"zh":["自动化 UI 测试","数据标签发现 UI 块","行为视觉契约验证","支持新卡片、模态、吐司和操作的扩展","无需编写新测试用例"],"ja":["UI 自動化テスト","データタグによる UI ブロックの検出","ビジュアル契約の検証","新しいカード、モーダル、トースト、アクションの拡張をサポート","新しいテストケースを書く必要なし"],"ko":["UI 자동화 테스트","데이터 태그를 통한 UI 블록의 발견","행동 시각 계약의 검증","새로운 카드, 모달, 토스트, 액션의 확장을 지원","새로운 테스트 케이스를 작성할 필요 없음"],"es":["Detección de bloques de interfaz de usuario mediante etiquetas data-qa","Cumplimiento de contratos de comportamiento y visuales","Compatibilidad con nuevas tarjetas, modales, toasts y acciones sin necesidad de escribir nuevos casos de prueba","Escalabilidad para proyectos de desarrollo de gran tamaño","Integración con sistemas de automatización de pruebas"],"fr":["Détection de blocs d''interface utilisateur via des balises data-qa","Respect des contrats de comportement et visuels","Compatibilité avec de nouvelles cartes, modales, toasts et actions sans nécessité d''écrire de nouveaux cas de test","Évolutivité pour les projets de développement de grande taille","Intégration avec des systèmes d''automatisation de tests"],"de":["Erkennung von Benutzeroberflächenblöcken mittels data-qa-Tags","Durchsetzung von Verträgen für Verhalten und Visualisierung","Kompatibilität mit neuen Karten, Modals, Toasts und Aktionen ohne Notwendigkeit, neue Testfälle zu schreiben","Skalierbarkeit für große Entwicklungsprojekte","Integration mit Automatisierungstests"],"pt":["Descoberta de blocos de UI via tags data-qa","Impõe contratos comportamentais e visuais","Suporte a novos cartões, modais, toasts e ações sem necessidade de novos testes","Integração com o projeto existente via pasta ui-tests/","Garantia de estabilidade e usabilidade da interface do usuário"],"ru":["Обнаружение блоков UI через теги data-qa","Обеспечение поведенческих и визуальных контрактов","Поддержка новых карточек, модальных окон, уведомлений и действий без необходимости новых тестов","Интеграция с существующим проектом через папку ui-tests/","Гарантия стабильности и удобства пользовательского интерфейса"],"ar":["اكتشاف الكتل من خلال وسوم data-qa","تنفيذ العقود السلوكية والبصرية","دعم بطاقات وعمليات جديدة ورسائل وافعال بدون الحاجة إلى اختبارات جديدة","التكامل مع المشروع الحالي من خلال مجلد ui-tests/","ضمان الاستقرار وسهولة استخدام الواجهة"]},"keywords":{"en":["how to use ui-check-framework","ui-check-framework setup guide","automated UI testing with ui-check-framework","ui-check-framework alternative","ui-check-framework vs selenium","ui-check-framework install","what is ui-check-framework","ui-check-framework tutorial","ui-check-framework best practices"],"zh":["UI 自动化测试","UI Check Framework","数据标签","行为视觉契约","自动化测试工具","UI 测试框架","开发效率","测试时间缩短"],"ja":["UI 自動化テスト","UI Check Framework","データタグ","ビジュアル契約","自動化テストツール","UI テストフレームワーク","開発効率","テスト時間短縮","AIエージェント"],"ko":["UI 자동화 테스트","UI Check Framework","데이터 태그","행동 시각 계약","자동화 테스트 도구","UI 테스트 프레임워크","개발 효율성","테스트 시간 단축","AI 에이전트"],"es":["ui-check-framework","agentes de inteligencia artificial","automatización de pruebas","interfaz de usuario","data-qa","contratos de comportamiento","desarrollo de software","pruebas de interfaz de usuario"],"fr":["framework ui-check","agents d''IA","automatisation de tests","interface utilisateur","data-qa","contrats de comportement","développement de logiciels","tests d''interface utilisateur"],"de":["ui-check-Framework","KI-Agents","Automatisierungstests","Benutzeroberfläche","data-qa","Verträge für Verhalten","Softwareentwicklung","Benutzeroberflächentests"],"pt":["ui-check-framework","automação de UI","testes de UI","contratos comportamentais","contratos visuais","tags data-qa","ui-tests","estabilidade da interface do usuário"],"ru":["ui-check-framework","автоматизация UI","тестирование UI","поведенческие контракты","визуальные контракты","теги data-qa","ui-tests","стабильность пользовательского интерфейса"],"ar":["ui-check-framework","تحسين واجهة المستخدم","اختبارات واجهة المستخدم","العقود السلوكية","العقود البصرية","وسوم data-qa","ui-tests","استقرار واجهة المستخدم"]}},"owner":"yiyousiow000814","repo":"XAUUSD-Calendar-Agent","repoPath":"yiyousiow000814/XAUUSD-Calendar-Agent","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.609Z","topics":[],"category":"community","skillMd":{"name":"ui-check-framework","description":"Build or extend an extensible UI self-check framework for Web UIs (React/Vite or plain HTML) using Playwright. Use when asked to add/upgrade ui-check or ui-watch flows, enforce data-qa/data-testid discovery, add theme/contrast checks, animation verification, loading state-machine checks, layout stability/overlap checks, modal scroll rules, or to document QA tagging standards and UI testing commands.","bodyPreview":"# UI Check Framework\n\n## Overview\n\nCreate or refine an automated UI self-check system that discovers UI blocks via data-qa\ntags and enforces behavioral/visual contracts (themes, animations, loading, layout\nstability, modal usability, error visibility). The framework must scale to new cards,\nmodals, toasts, and actions without writing new test cases each time.\n\n## Workflow (use in order)\n\n1) **Inspect existing scaffolding**\n   - Prefer reusing the project''s `ui-tests/` folder if it exists.\n   - R","body":"# UI Check Framework\n\n## Overview\n\nCreate or refine an automated UI self-check system that discovers UI blocks via data-qa\ntags and enforces behavioral/visual contracts (themes, animations, loading, layout\nstability, modal usability, error visibility). The framework must scale to new cards,\nmodals, toasts, and actions without writing new test cases each time.\n\n## Workflow (use in order)\n\n1) **Inspect existing scaffolding**\n   - Prefer reusing the project''s `ui-tests/` folder if it exists.\n   - Read `ui-tests/docs/UI_TESTING.md` and `ui-tests/docs/QA_TAGGING.md` if present.\n   - Confirm scripts in root `package.json` (`ui:test`, `ui:update-baseline`,\n     `ui:report`, `ui:check`, `ui:watch`) point at Playwright flows.\n\n2) **Enforce discovery**\n   - Auto-collect all `data-qa` or `data-testid` elements that start with `qa:`.\n   - Capture component screenshots (cards, modals, menus, toolbars, toasts) at\n     small/medium/large sizes.\n   - For modals: verify internal scroll, single close button, and header visibility\n     at small window height.\n\n3) **Enforce contracts (generic, not hardcoded)**\n   - Theme contrast/readability for dark/light/system (see references).\n   - Animation/motion checks for spinners, transitions, toasts.\n   - Loading state machine for async actions: idle -> loading -> success/error -> idle.\n   - Layout stability (no layout shift for transient status/toasts).\n   - Overlap detection for action buttons and modal header/footer.\n   - Error visibility and blank-page detection.\n\n4) **Wire UI hooks for automation**\n   - Add minimal `window.__ui_check__` helpers (e.g., append log, trigger toast) to\n     make contracts testable without hardcoding selectors.\n   - Add required `data-qa` tags to new cards/modals/actions as they appear.\n\n5) **Artifacts and reporting**\n   - Store artifacts under `artifacts/ui-check/` (snapshots, frames, video, report.html).\n   - Ensure `ui:check` is interactive (open/close modal, hover/press, theme toggle, scroll).\n\n## Project-specific anchors\n\n- Primary UI tests live in `ui-tests/` and use Playwright.\n- Use `ui-tests/scripts/ui-check.mjs` and `ui-tests/scripts/ui-watch.mjs` as the\n  interactive validation entry points.\n- Keep user-facing docs in `ui-tests/docs/UI_TESTING.md` and\n  `ui-tests/docs/QA_TAGGING.md`.\n\n## References\n\n- `references/workflow.md` - extension workflow and verification checklist.\n- `references/qa-tagging.md` - required QA tokens and naming conventions.\n- `references/contracts.md` - required generic contracts and how to check them.\n"},"lastSynced":"2026-03-07T02:13:25.390Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated UI testing and validation capabilities.","zh":"适用于需要自动化UI测试和验证功能的前端代理。","ja":"フロントエンドエージェントが自動化されたUIテストと検証機能を必要とする場合に適しています。","ko":"자동화된 UI 테스트 및 검증 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes frontend que necesitan capacidades de prueba y validación de interfaz de usuario automatizadas.","fr":"Parfait pour les agents frontend ayant besoin de capacités de test et de validation d''interface utilisateur automatisées.","de":"Perfekt für Frontend-Agents, die automatisierte UI-Test- und Validierungsfunktionen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de teste e validação de UI automatizados.","ru":"Идеально подходит для агентов Frontend, которым необходимы автоматические возможности тестирования и проверки UI.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى قدرات اختبار و التحقق من الواجهة المستخدمة أتمتيكيا."},"recommendation":{"en":"Empowers agents to discover UI blocks via data-qa tags and enforce behavioral contracts, including themes, animations, loading, layout stability, modal usability, and error visibility, using protocols like data-qa and scaling to new UI components without requiring new test cases.","zh":"赋予代理发现UI块的能力，通过数据-qa标签，并强制执行行为 contrato，包括主题、动画、加载、布局稳定性、模态可用性和错误可见性，使用诸如数据-qa的协议，并且可以扩展到新的UI组件，而无需新的测试用例。","ja":"エージェントにUIブロックを検出する能力を与え、data-qaタグを介して、テーマ、動画、読み込み、レイアウトの安定性、モーダルの使用可能性、エラービジビリティを含む動作契約を適用する。data-qaなどのプロトコルを使用し、新しいUIコンポーネントに拡張することができ、新的テストケースを必要とせずに。","ko":"에이전트가 데이터-qa 태그를 통해 UI 블록을 발견하고 테마, 애니메이션, 로딩, 레이아웃 안정성, 모달 사용 가능성, 오류 가시성을 포함한 행동 계약을 적용할 수 있는 기능을 제공한다. 데이터-qa와 같은 프로토콜을 사용하여 새로운 UI 컴포�ント로 확장할 수 있으며, 새로운 테스트 케이스가 필요하지 않다.","es":"Habilita a los agentes a descubrir bloques de interfaz de usuario a través de etiquetas data-qa y a hacer cumplir contratos de comportamiento, incluidos temas, animaciones, carga, estabilidad de diseño, usabilidad de modales y visibilidad de errores, utilizando protocolos como data-qa y escalando a nuevos componentes de interfaz de usuario sin requerir nuevos casos de prueba.","fr":"Permet aux agents de découvrir des blocs d''interface utilisateur via des balises data-qa et de faire respecter des contrats de comportement, y compris des thèmes, des animations, un chargement, une stabilité de disposition, une utilisabilité de modales et une visibilité des erreurs, en utilisant des protocoles tels que data-qa et en évoluant vers de nouveaux composants d''interface utilisateur sans exiger de nouveaux cas de test.","de":"Ermächtigt Agenten, UI-Blöcke über data-qa-Tags zu erkennen und Verträge über das Verhalten durchzusetzen, einschließlich Themen, Animationen, Ladevorgang, Layoutstabilität, Modus-Benutzerfreundlichkeit und Fehlerhinweis, unter Verwendung von Protokollen wie data-qa und Skalierung auf neue UI-Komponenten ohne neue Testfälle zu erfordern.","pt":"Habilita os agentes a descobrirem blocos de UI via tags data-qa e impor contratos de comportamento, incluindo temas, animações, carregamento, estabilidade de layout, usabilidade de modais e visibilidade de erros, usando protocolos como data-qa e escalando para novos componentes de UI sem exigir novos casos de teste.","ru":"Наделяет агентов возможностью обнаруживать блоки UI через теги data-qa и обеспечивать выполнение поведенческих контрактов, включая темы, анимации, загрузку, стабильность макета, удобство использования модальных окон и видимость ошибок, используя протоколы типа data-qa и масштабируясь до новых компонентов UI без необходимости новых тестовых случаев.","ar":"تمكّن الوكلاء من اكتشاف كتل الواجهة المستخدمة عن طريق وسوم data-qa وفرض عقود السلوك، بما في ذلك المواضيع والرسوم المتحركة والتحميل وثبات التصميم وقابلية استخدام النوافذ المودال ووضوح الأخطاء، باستخدام بروتوكولات مثل data-qa وتوسيع نطاقها إلى مكونات الواجهة المستخدمة الجديدة دون الحاجة إلى حالات اختبار جديدة."},"useCases":{"en":["Automating UI self-checks for new UI components","Enforcing visual contracts for consistent theming and layout","Debugging UI issues with data-qa tag-based inspection"],"zh":["为新的UI组件自动化UI自检","强制执行视觉契约以保持一致的主题和布局","使用数据-qa标签基于的检查调试UI问题"],"ja":["新しいUIコンポーネントのためのUIセルフチェックの自動化","一貫したテーマとレイアウトを維持するための視覚契約の適用","data-qaタグベースのインスペクションを使用してUIの問題をデバッグする"],"ko":["새로운 UI 컴포넌트를 위한 UI 셀프 체크 자동화","일관된 테마와 레이아웃을 유지하기 위한 시각적 계약 적용","데이터-qa 태그 기반의 검사를 사용하여 UI 문제를 디버깅"],"es":["Automatización de autoverificaciones de interfaz de usuario para nuevos componentes de interfaz de usuario","Aplicación de contratos visuales para temas y diseños coherentes","Depuración de problemas de interfaz de usuario con inspección basada en etiquetas data-qa"],"fr":["Automation des auto-vérifications d''interface utilisateur pour les nouveaux composants d''interface utilisateur","Application de contrats visuels pour une mise en page et un thème cohérents","Débogage des problèmes d''interface utilisateur avec inspection basée sur des balises data-qa"],"de":["Automatisierung von UI-Selbstüberprüfungen für neue UI-Komponenten","Durchsetzung von visuellen Verträgen für konsistente Themen und Layouts","Fehlerbehebung von UI-Problemen mit data-qa-Tag-basierten Inspektionen"],"pt":["Automatizar verificações de UI para novos componentes de UI","Impor contratos visuais para theming e layout consistentes","Depurar problemas de UI com inspeção baseada em tags data-qa"],"ru":["Автоматизировать проверки UI для новых компонентов UI","Обеспечивать визуальные контракты для последовательного теминга и макета","Отлаживать проблемы UI с помощью инспекции на основе тегов data-qa"],"ar":["أتمتة التحقق من الواجهة المستخدمة لل组يات الجديدة","فرض العقود البصرية للتنسيق والتخطيط الثابت","تصحيح أخطاء الواجهة المستخدمة باستخدام التفتيش المعتمد على وسوم data-qa"]},"limitations":{"en":["Requires existing ui-tests/ folder or scaffolding","Limited to UI components with data-qa tags"],"zh":["需要现有的ui-tests/文件夹或脚手架","仅限于具有数据-qa标签的UI组件"],"ja":["既存のui-tests/フォルダまたはスキャフォールディングが必要","data-qaタグを持つUIコンポーネントに限定される"],"ko":["기존의 ui-tests/ 폴더 또는 스캐폴딩이 필요하다","데이터-qa 태그가 있는 UI 컴포넌트로 제한됨"],"es":["Requiere una carpeta ui-tests existente o andamiaje","Limitado a componentes de interfaz de usuario con etiquetas data-qa"],"fr":["Nécessite un dossier ui-tests existant ou un échafaudage","Limité aux composants d''interface utilisateur avec des balises data-qa"],"de":["Benötigt ein vorhandenes ui-tests-Verzeichnis oder ein Gerüst","Begrenzt auf UI-Komponenten mit data-qa-Tags"],"pt":["Exige pasta ui-tests existente ou scaffolding","Limitado a componentes de UI com tags data-qa"],"ru":["Требует существующей папки ui-tests или scafolding","Ограничен компонентами UI с тегами data-qa"],"ar":["يتطلب وجود مجلد ui-tests أو هيكلة","محدود بمكونات الواجهة المستخدمة التي تحتوي على وسوم data-qa"]},"version":4},"contentHash":"2d107e4224db90e7d2524051832e87ff3a0e99baa61d7795fd3b5e3ef88004b5","qualityScore":29}');
