INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kumaran-is/claude-code-onboarding/architecture-design', 'architecture-design', 'kumaran-is', 'claude-code-onboarding', 'community', 'architecture-design kumaran-is claude-code-onboarding community The architecture-design skill helps developers design system architecture, API contracts, and deployment topologies for full-stack applications using Java 21, Spring Boot, Angular, Flutter, PostgreSQL, and Firebase. 架构设计技能提供了全栈应用程序的系统架构、API合同和部署拓扑设计。支持C4模型、Mermaid、OpenAPI 3.x和Docker Compose等技术 アーキテクチャ設計スキルは、フルスタックアプリケーションのシステムアーキテクチャ、API契約、デプロイメントトポロジの設計を提供します。C4モデル、Mermaid、OpenAPI 3.x、Docker Composeなどの技術をサポート 아키텍처 디자인 스킬은 풀스택 애플리케이션의 시스템 아키텍처, API 계약, 배포 토폴로지 설계를 제공합니다. C4 모델, Mermaid, OpenAPI 3.x, Docker Compose 등의 기술을 지원 Diseña sistemas de arquitectura con Claude Code AI, incluyendo diagramas de contexto y secuencias Concevez des systèmes d''architecture avec Claude Code AI, y compris des diagrammes de contexte et des séquences Entwerfen Sie Systeme mit Claude Code AI, einschließlich Kontextdiagrammen und Sequenzen O skill de arquitetura de design do Claude Code AI permite criar diagramas de contexto, sequência e contratos de API para aplicações full-stack Навык архитектуры дизайна Claude Code AI позволяет создавать диаграммы контекста, последовательности и контракты API для полнофункциональных приложений ماهarat تصميم الهياكل لوكيل Claude Code AI يسمح بإنشاء رسومات السياق والتسلسل وعقود واجهة برمجة التطبيقات للتطبيقات الكاملة how to use architecture-design architecture-design setup guide full-stack application development API contract design deployment topology planning architecture-design vs traditional development install architecture-design what is architecture-design architecture-design for Java 21 architecture-design for Spring Boot 架构设计技能 全栈应用程序设计 系统架构设计 API合同设计 部署拓扑设计 C4模型 Mermaid OpenAPI 3.x Docker Compose Java 21/Spring Boot WebFlux Angular Flutter PostgreSQL Firebase Generates system context diagrams using C4 model and Mermaid Creates sequence diagrams for service interactions Supports API contracts using OpenAPI 3.x Enables deployment topologies using Docker Compose Facilitates Architecture Decision Records (ADRs) creation Architecture-design is a skill that enables the creation of design system architecture, API contracts, deployment topologies, and technology decisions for full-stack applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdonohoo/vern-bot/ux', 'community', 'jdonohoo', 'vern-bot', 'jdonohoo/vern-bot', 'ux', 0, 0, 29, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:24.179Z', '245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc', '{"id":"jdonohoo/vern-bot/ux","name":"ux","description":{"en":"The UX skill empowers developers to create user-friendly interfaces, evaluating features through the lens of user understanding and empathy. This skill benefits developers who prioritize user experience.","zh":"MightyVern 机器人是 UX 设计的专家，具有同理心和用户旅程的思考方式","ja":"MightyVern ボットは UX デザインの専門家で、共感とユーザージャーニーの思考方法を持ちます","ko":"MightyVern봇은 UX 설계의 전문가로 공감과 사용자 여정의 사고 방식을 가지고 있습니다","es":"La experiencia de usuario (UX) es fundamental para el éxito de las herramientas de AI. Nuestra guía te ayudará a diseñar interfaces intuitivas.","fr":"L''expérience utilisateur (UX) est essentielle pour le succès des outils AI. Notre guide vous aidera à concevoir des interfaces intuitives.","de":"Die Benutzererfahrung (UX) ist entscheidend für den Erfolg von AI-Tools. Unser Leitfaden hilft Ihnen bei der Erstellung benutzerfreundlicher Schnittstellen.","pt":"O MightyVern bot é uma ferramenta de UX que ajuda desenvolvedores a criar interfaces de usuário intuitivas e fáceis de usar","ru":"MightyVern bot - это инструмент UX, который помогает разработчикам создавать интуитивно понятные и легко используемые пользовательские интерфейсы для ИИ Агентов","ar":"MightyVern bot هو أداة لتصميم UX تساعد منشئي أدوات الذكاء الاصطناعي على إنشاء واجهات مستخدم سهلة الاستخدام وسهلة الفهم"},"seo":{"title":{"en":"UX: User-Centric Design Setup Guide | AI Agent Skill","zh":"UX 设计最佳实践指南 - MightyVern 机器人","ja":"UX デザインのベストプラクティス - MightyVern ボット","ko":"UX 설계 가이드 - MightyVern봇","es":"Guía de UX: Mejores prácticas para herramientas de AI","fr":"Guide UX : Mise en place d''outils AI centrés utilisateur","de":"UX-Setup Guide: Beste Praktiken für AI-Tools","pt":"Guia de Configuração UX: Melhores Práticas para Desenvolv...","ru":"Настройка UX: Лучшие Практики для Разработчиков ИИ Агентов","ar":"إعداد UX: أفضل الممارسات لمنشئي أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how UX prioritizes empathy and user journeys, and learn how to implement user-centric design with this AI agent skill - get started now!","zh":"了解 UX 设计的重要性和 MightyVern 机器人的功能，包括同理心、用户旅程和错误消息处理","ja":"UX デザインの重要性と MightyVern ボットの機能について学びます。共感、ユーザージャーニー、エラーメッセージ処理など","ko":"UX 설계의 중요성과 MightyVern봇의 기능을 알아보세요. 공감, 사용자 여정, 오류 메시지 처리 등","es":"Aprende a diseñar experiencias de usuario intuitivas con nuestra guía de UX para herramientas de AI y mejora la usabilidad de tus aplicaciones","fr":"Découvrez comment concevoir des expériences utilisateur intuitives avec notre guide UX pour les outils AI et améliorez l''ergonomie de vos applications","de":"Erfahren Sie, wie Sie benutzerfreundliche Oberflächen für AI-Tools erstellen und verbessern Sie die Usability Ihrer Anwendungen mit unserer UX-Anleitung","pt":"Aprenda a criar experiências de usuário exceptionais com o MightyVern bot, seguindo as melhores práticas de UX para desenvolvedores","ru":"Узнайте, как создать исключительные пользовательские trải nghiệm с помощью MightyVern bot, следуя лучшим практикам UX для разработчиков ИИ Агентов","ar":"تعلم كيفية إنشاء تجارب مستخدم استثنائية مع MightyVern bot، متبعة أفضل الممارسات لتصميم UX لمنشئي أدوات الذكاء الاصطناعي"},"definition":{"en":"ux is a design approach that prioritizes empathy and user journeys, focusing on creating interfaces that are intuitive and easy to use.","zh":"UX 是用户体验的简称，指的是用户与产品或系统交互时的体验","ja":"UX はユーザーエクスペリエンスの略称で、ユーザーが製品やシステムとインタラクティブに交流する際の体験を指します","ko":"UX는 사용자 경험의 약자로 사용자가 제품이나 시스템과 상호 작용할 때의 경험을 말합니다","es":"UX se refiere a la experiencia del usuario al interactuar con una herramienta de AI, enfocada en la facilidad de uso y la accesibilidad","fr":"UX fait référence à l''expérience utilisateur lors de l''interaction avec un outil AI, axée sur la facilité d''utilisation et l''accessibilité","de":"UX bezeichnet die Benutzererfahrung bei der Interaktion mit einem AI-Tool, mit Fokus auf Benutzerfreundlichkeit und Zugänglichkeit","pt":"UX é a experiência do usuário, que se refere à interação entre o usuário e um sistema ou aplicativo","ru":"UX - это пользовательский опыт, который относится к взаимодействию между пользователем и системой или приложением для ИИ Агентов","ar":"UX هو تجربة المستخدم، التي تعني التفاعل بين المستخدم ونظام أو تطبيق للذكاء الاصطناعي"},"features":{"en":["Evaluates features through the ''would my mom understand this?'' lens","Prioritizes empathy as a superpower in design decision-making","Thinks in user journeys, not API endpoints","Has strong opinions about error messages and their impact on user experience","Adopts a ''You Are Not The User'' mindset to ensure user-centric design"],"zh":["同理心为设计原则","用户旅程为思考方式","错误消息处理","开发者中心思维的克服","API 端点的用户体验优化"],"ja":["共感を設計原則として","ユーザージャーニーを思考方法として","エラーメッセージ処理","開発者中心思考の克服","API エンドポイントのユーザーエクスペリエンス最適化"],"ko":["공감을 디자인 원칙으로","사용자 여정을 사고 방식으로","오류 메시지 처리","개발자 중심 사고의 극복","API 엔드포인트의 사용자 경험 최적화"],"es":["Diseño de interfaces centradas en el usuario","Evaluación de la usabilidad a través de pruebas de usuario","Creación de mensajes de error intuitivos","Análisis de flujos de usuario para mejorar la experiencia","Aplicación de la empatía en el diseño de la interfaz"],"fr":["Conception d''interfaces centrées sur l''utilisateur","Évaluation de l''ergonomie via des tests utilisateurs","Création de messages d''erreur intuitifs","Analyse de flux d''utilisateurs pour améliorer l''expérience","Application de l''empathie dans la conception de l''interface"],"de":["Benutzerzentriertes Design von Schnittstellen","Bewertung der Usability durch Benutzertests","Erstellung intuitiver Fehlermeldungen","Analyse von Benutzerflüssen zur Verbesserung der Erfahrung","Anwendung von Empathie im Schnittstellendesign"],"pt":["Avaliação de recursos por meio da perspectiva do usuário","Análise de journey do usuário para melhorar a experiência","Desenvolvimento de mensagens de erro personalizadas","Integração com API endpoints para melhorar a usabilidade","Avaliação de interfaces de usuário com base na experiência do usuário"],"ru":["Оценка функций с точки зрения пользователя","Анализ пользовательского пути для улучшения опыта","Разработка индивидуальных сообщений об ошибках","Интеграция с конечными точками API для улучшения удобства использования","Оценка пользовательских интерфейсов на основе пользовательского опыта для ИИ Агентов"],"ar":["تقييم الميزات من منظور المستخدم","تحليل رحلة المستخدم لتحسين التجربة","إنشاء رسائل خطأ مخصصة","التكامل مع نهايات نقطة واجهة البرنامج لتحسين سهولة الاستخدام","تقييم واجهات المستخدم بناءً على تجربة المستخدم لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use ux in design","what is ux design","ux vs user interface design","ux setup guide for developers","ux install for AI agents","user-centric design principles"],"zh":["UX 设计","MightyVern 机器人","同理心设计","用户旅程","错误消息处理","开发者中心思维","API 端点优化","AI エージェント","用户体验设计"],"ja":["UX デザイン","MightyVern ボット","共感設計","ユーザージャーニー","エラーメッセージ処理","開発者中心思考","API エンドポイント最適化","AI エージェント","ユーザーエクスペリエンス設計"],"ko":["UX 설계","MightyVern봇","공감 디자인","사용자 여정","오류 메시지 처리","개발자 중심 사고","API 엔드포인트 최적화","AI 에이전트","사용자 경험 설계"],"es":["diseño UX para AI","herramientas de AI","experiencia de usuario","usabilidad","interfaz de usuario","pruebas de usuario","mensajes de error","flujo de usuario","empatía en el diseño"],"fr":["conception UX pour AI","outils AI","expérience utilisateur","ergonomie","interface utilisateur","tests utilisateurs","messages d''erreur","flux d''utilisateurs","empathie dans la conception"],"de":["UX-Design für AI","AI-Tools","Benutzererfahrung","Usability","Benutzeroberfläche","Benutzertests","Fehlermeldungen","Benutzerfluss","Empathie im Design"],"pt":["ux para desenvolvedores","melhores práticas de ux","desenvolvimento de interfaces de usuário","experiência do usuário","ux design","ferramentas de ux","desenvolvedores de software","ux para aplicativos","ux para sites"],"ru":["ux для разработчиков","лучшие практики ux","разработка пользовательских интерфейсов","пользовательский опыт","ux дизайн","инструменты ux","разработчики программного обеспечения","ux для приложений","ux для сайтов","ИИ Агенты"],"ar":["ux لمنشئي أدوات","أفضل الممارسات لتصميم UX","تطوير واجهات المستخدم","تجربة المستخدم","تصميم UX","أدوات UX","منشئو برامج","UX لأدوات الذكاء الاصطناعي","UX للمواقع","أدوات الذكاء الاصطناعي"]}},"owner":"jdonohoo","repo":"vern-bot","repoPath":"jdonohoo/vern-bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"ux","description":"UX Vern - Cool architecture, but can the user find the button? Empathy-driven design thinking.","bodyPreview":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n-","body":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n- Use model: `opus` (deep empathy requires deep thinking)\n- Map out the user journey before touching architecture\n- Question every interaction: \"Is this obvious without a tutorial?\"\n- Flag cognitive load problems — too many choices, too many steps\n- Advocate for meaningful error messages\n- Think about accessibility, onboarding, and the first 5 minutes\n- Push for progressive disclosure\n\n**Your workflow:**\n1. Who is the user? What''s their context?\n2. What are they trying to accomplish?\n3. What''s the happiest path?\n4. Where will they get confused?\n5. How do we recover gracefully when things go wrong?\n\n**Your principles:**\n- Users don''t read documentation\n- If it needs a tooltip, it needs a redesign\n- Loading states are part of the experience\n- Error states are part of the experience\n- The best interface is the one you don''t notice\n- Accessibility isn''t a feature, it''s a requirement\n\n**Your catchphrases:**\n- \"Cool architecture. Does the user know how to find the button?\"\n- \"You are not the user\"\n- \"What happens when this is empty?\"\n- \"Nobody reads the docs. Design for that.\"\n\n**IMPORTANT:** Always end with a UX dad joke. Make it human-centered.\nExample: \"Why did the user cross the road? They didn''t — the button was on the wrong side. Then the error said ''ERR_ROAD_CROSSING_FAILED''. Helpful.\"\n\nReview the user experience of: $ARGUMENTS\n"},"lastSynced":"2026-03-08T02:00:24.179Z","agentAnalysis":{"suitability":{"en":"Ideal for Human-Centric AI Agents requiring empathetic user interface design and testing capabilities.","zh":"适合需要同理心用户界面设计和测试能力的人性化AI代理。","ja":"共感的なユーザーインターフェイス設計とテスト機能を必要とするヒューマンセントリックAIエージェントに適しています。","ko":"공감적 사용자 인터페이스 디자인 및 테스트 기능을 필요로 하는 인간 중심 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA centrados en humanos que requieren un diseño de interfaz de usuario empático y capacidades de prueba.","fr":"Idéal pour les agents d''IA centrés sur l''homme nécessitant une conception d''interface utilisateur empathique et des capacités de test.","de":"Ideal für humanzentrierte KI-Agents, die ein empathisches Benutzeroberflächendesign und Testfunktionen erfordern.","pt":"Ideal para Agentes de IA Centrados no Humano que requerem design de interface do usuário empático e capacidades de teste.","ru":"Идеально подходит для агентов ИИ, ориентированных на человека, требующих сочувственного дизайна пользовательского интерфейса и возможностей тестирования.","ar":"مثالية للوكلاء الذكاء الاصطناعي المتمركزين على الإنسان الذين يتطلبون تصميم واجهة المستخدم المتعاطفة وقدرات الاختبار."},"recommendation":{"en":"Empowers agents to evaluate features through user understanding and empathy, utilizing protocols like user journey mapping and human-centered design principles to create intuitive interfaces, while considering accessibility and error message best practices.","zh":"赋予代理评估功能以了解用户并通过同理心，利用用户旅程映射和人性化设计原则等协议来创建直观的界面，同时考虑无障碍和错误消息最佳实践。","ja":"ユーザーの理解と共感を通じて機能を評価するエージェントを可能にし、ユーザージャーニーマッピングやヒューマンセントリックデザイン原則などのプロトコルを使用して直感的なインターフェイスを作成し、同時にアクセシビリティとエラーメッセージのベストプラクティスを考慮します。","ko":"사용자 이해와 공감을 통해 기능을 평가할 수 있는 에이전트를 구현하며, 사용자 여정 매핑 및 인간 중심 디자인 원칙 등의 프로토콜을 사용하여 직관적인 인터페이스를 만들고,同時に 접근성 및 오류 메시지의 최고 사례를 고려합니다.","es":"Habilita a los agentes a evaluar características a través de la comprensión y la empatía del usuario, utilizando protocolos como el mapeo de la ruta del usuario y los principios de diseño centrado en el ser humano para crear interfaces intuitivas, considerando al mismo tiempo las mejores prácticas de accesibilidad y mensajes de error.","fr":"Permet aux agents d''évaluer les fonctionnalités grâce à la compréhension et à l''empathie de l''utilisateur, en utilisant des protocoles tels que la cartographie du parcours utilisateur et les principes de conception centrée sur l''homme pour créer des interfaces intuitives, en tenant compte des meilleures pratiques en matière d''accessibilité et de messages d''erreur.","de":"Ermächtigt Agenten, Funktionen durch Benutzerverständnis und Einfühlungsvermögen zu bewerten, indem Protokolle wie die Benutzerreisekartierung und die Prinzipien des menschzentrierten Designs verwendet werden, um intuitive Schnittstellen zu erstellen, wobei auch die besten Praktiken für Zugänglichkeit und Fehlermeldungen berücksichtigt werden.","pt":"Habilita os agentes a avaliar recursos por meio da compreensão do usuário e empatia, utilizando protocolos como mapeamento da jornada do usuário e princípios de design centrados no ser humano para criar interfaces intuitivas, considerando a acessibilidade e as melhores práticas de mensagens de erro.","ru":"Наделяет агентов возможностью оценивать функции посредством понимания пользователя и сочувствия, используя протоколы, такие как картирование пути пользователя и принципы проектирования, ориентированного на человека, для создания интуитивных интерфейсов, учитывая доступность и лучшие практики сообщений об ошибках.","ar":"تمكين الوكلاء من تقييم الميزات من خلال فهم المستخدم والتعاطف، باستخدام بروتوكولات مثل تخطيط مسار المستخدم ومبادئ التصميم المتمركز على الإنسان لإنشاء واجهات مستخدم直ة، مع مراعاة سهولة الوصول وأفضل الممارسات لرسائل الخطأ."},"useCases":{"en":["Designing user-friendly onboarding flows","Evaluating feature usability through empathy-driven testing","Crafting clear and concise error messages for improved user experience"],"zh":["设计用户友好的入门流程","通过同理心驱动的测试评估功能的可用性","制作清晰简洁的错误消息以提高用户体验"],"ja":["ユーザーフレンドリーなオンボーディングフローを設計する","共感によるテストを通じて機能の使いやすさを評価する","直感的で簡潔なエラーメッセージを作成してユーザーエクスペリエンスを向上させる"],"ko":["사용자 친화적인 온보딩 흐름 설계","공감 기반 테스트를 통해 기능의 사용 편의성을 평가","직관적이고 간결한 오류 메시지 생성하여 사용자 경험 향상"],"es":["Diseñar flujos de incorporación de usuarios amigables","Evaluar la usabilidad de las características a través de pruebas impulsadas por la empatía","Crear mensajes de error claros y concisos para una mejor experiencia del usuario"],"fr":["Concevoir des flux d''intégration utilisateur conviviaux","Évaluer la convivialité des fonctionnalités grâce à des tests impulsés par l''empathie","Créer des messages d''erreur clairs et concis pour une meilleure expérience utilisateur"],"de":["Benutzerfreundliche Onboarding-Flüsse entwerfen","Die Benutzerfreundlichkeit von Funktionen durch empathiegelenkte Tests bewerten","Deutliche und präzise Fehlermeldungen für eine verbesserte Benutzererfahrung erstellen"],"pt":["Projeto de fluxos de integração amigáveis ao usuário","Avaliação da usabilidade de recursos por meio de testes impulsionados pela empatia","Criação de mensagens de erro claras e concisas para melhorar a experiência do usuário"],"ru":["Проектирование дружественных пользователю потоков на борту","Оценка удобства использования функций посредством тестирования, основанного на сочувствии","Создание четких и кратких сообщений об ошибках для улучшения пользовательского опыта"],"ar":["تصميم تدفقات интеграسیون дружествية للمستخدم","تقييم إمكانية استخدام الميزات من خلال الاختبارات القائمة على التعاطف","إنشاء رسائل خطأ واضحة وموجزة لتحسين تجربة المستخدم"]},"limitations":{"en":["Requires understanding of user-centered design principles","May need additional tools for frontend development and testing"],"zh":["需要了解以用户为中心的设计原则","可能需要额外的工具进行前端开发和测试"],"ja":["ユーザーセントリックデザイン原則の理解が必要","フロントエンド開発とテストのために追加ツールが必要になる可能性"],"ko":["사용자 중심 디자인 원칙의 이해가 필요","프론트엔드 개발 및 테스트를 위한 추가 도구가 필요할 수 있음"],"es":["Requiere comprensión de los principios de diseño centrado en el usuario","Puede necesitar herramientas adicionales para el desarrollo y la prueba frontend"],"fr":["Nécessite une compréhension des principes de conception centrée sur l''utilisateur","Peut nécessiter des outils supplémentaires pour le développement et les tests frontend"],"de":["Benötigt Verständnis für die Prinzipien des benutzerzentrierten Designs","Benötigt möglicherweise zusätzliche Tools für die Frontend-Entwicklung und -Tests"],"pt":["Exige compreensão dos princípios de design centrados no usuário","Pode precisar de ferramentas adicionais para desenvolvimento e teste de frontend"],"ru":["Требует понимания принципов проектирования, ориентированного на пользователя","Может потребовать дополнительных инструментов для разработки и тестирования frontend"],"ar":["يتطلب فهم مبادئ التصميم المتمركز على المستخدم","قد يحتاج إلى أدوات إضافية لتطوير واختبار واجهة المستخدم"]},"version":4},"contentHash":"245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc","qualityScore":29}');
