INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jdonohoo/vern-bot/ux', 'ux', 'jdonohoo', 'vern-bot', 'community', 'ux jdonohoo vern-bot community The UX skill empowers developers to create user-friendly interfaces, evaluating features through the lens of user understanding and empathy. This skill benefits developers who prioritize user experience. MightyVern 机器人是 UX 设计的专家，具有同理心和用户旅程的思考方式 MightyVern ボットは UX デザインの専門家で、共感とユーザージャーニーの思考方法を持ちます MightyVern봇은 UX 설계의 전문가로 공감과 사용자 여정의 사고 방식을 가지고 있습니다 La experiencia de usuario (UX) es fundamental para el éxito de las herramientas de AI. Nuestra guía te ayudará a diseñar interfaces intuitivas. L''expérience utilisateur (UX) est essentielle pour le succès des outils AI. Notre guide vous aidera à concevoir des interfaces intuitives. Die Benutzererfahrung (UX) ist entscheidend für den Erfolg von AI-Tools. Unser Leitfaden hilft Ihnen bei der Erstellung benutzerfreundlicher Schnittstellen. O MightyVern bot é uma ferramenta de UX que ajuda desenvolvedores a criar interfaces de usuário intuitivas e fáceis de usar MightyVern bot - это инструмент UX, который помогает разработчикам создавать интуитивно понятные и легко используемые пользовательские интерфейсы для ИИ Агентов MightyVern bot هو أداة لتصميم UX تساعد منشئي أدوات الذكاء الاصطناعي على إنشاء واجهات مستخدم سهلة الاستخدام وسهلة الفهم how to use ux in design what is ux design ux vs user interface design ux setup guide for developers ux install for AI agents user-centric design principles UX 设计 MightyVern 机器人 同理心设计 用户旅程 错误消息处理 开发者中心思维 API 端点优化 AI エージェント 用户体验设计 Evaluates features through the ''would my mom understand this?'' lens Prioritizes empathy as a superpower in design decision-making Thinks in user journeys, not API endpoints Has strong opinions about error messages and their impact on user experience Adopts a ''You Are Not The User'' mindset to ensure user-centric design ux is a design approach that prioritizes empathy and user journeys, focusing on creating interfaces that are intuitive and easy to use.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ibelick/ui-skills/baseline-ui', 'community', 'ibelick', 'ui-skills', 'ibelick/ui-skills', 'baseline-ui', 0, 0, 29, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.687Z', '9bb2f868098a9d28ce7d10383039a28169d838cea6299f9df3706ecda7932949', '{"id":"ibelick/ui-skills/baseline-ui","name":"baseline-ui","description":{"en":"baseline-ui enforces a consistent UI baseline for AI-generated interfaces, benefiting developers who want to polish their interface builds. It applies constraints to prevent UI slop.","zh":"Baseline UI 是一个强制执行一致的界面基准的技能，用于优化 AI 生成的界面。它使用 Tailwind CSS 默认值来确保一致性和良好的用户体验","ja":"Baseline UIは、AIエージェントが生成したインターフェイスを一貫性と良好的ユーザーエクスペリエンスを持つようにするための、一貫したインターフェイス基準を強制適用するスキルです。Tailwind CSSのデフォルト値を使用して一貫性を保ちます","ko":"Baseline UI는 일관된 인터페이스 기준을 적용하여 AI 에이전트가 생성한 인터페이스를 최적화하는 기술입니다. Tailwind CSS 기본 값을 사용하여 일관성을 유지합니다","es":"Baseline-ui es un conjunto de habilidades que aplican una base de interfaz de usuario opinada para evitar la generación de interfaces descuidadas por agentes de IA.","fr":"Baseline-ui est un ensemble de compétences qui appliquent une base d''interface utilisateur avisée pour éviter la génération d''interfaces négligées par les outils d''IA","de":"Baseline-ui ist ein Satz von Fähigkeiten, die eine Meinungsbasierte Benutzeroberflächen-Basis anwenden, um die Erzeugung von vernachlässigten Oberflächen durch IA-Tools zu vermeiden","pt":"O Baseline UI é um conjunto de habilidades para melhorar a qualidade das interfaces geradas por agentes de IA, utilizando o Tailwind CSS e outras ferramentas.","ru":"Baseline UI - это набор навыков для улучшения качества интерфейсов, созданных ИИ Агентами, с использованием Tailwind CSS и других инструментов.","ar":"Baseline UI هو مجموعة من المهارات لتحسين جودة الواجهات التي يгенّرها وكلاء الذكاء الاصطناعي، باستخدام Tailwind CSS وأدوات أخرى."},"seo":{"title":{"en":"baseline-ui: UI Polish Setup Guide | AI Agent Skill","zh":"Baseline UI 设置指南：AI界面优化最佳实践","ja":"Baseline UI セットアップガイド：AIエージェントのインターフェイスを磨く","ko":"Baseline UI 설정 가이드: AI 에이전트 인터페이스 최적화","es":"Guía de configuración de baseline-ui para interfaces de a...","fr":"Guide de mise en place de baseline-ui pour les interfaces...","de":"Einrichtungsleitfaden für baseline-ui zur Verbesserung vo...","pt":"Baseline UI: Guia de Configuração para Interfaces Polidas","ru":"Baseline UI: Настройка Интерфейсов с ИИ Агентами","ar":"Baseline UI: دليل إعداد الواجهات المصقولة بالوكلاء الذكية"},"description":{"en":"Discover how to refine AI-generated interfaces with baseline-ui. Learn to apply opinionated UI baselines and fix violations with concrete code suggestions.","zh":"使用 Baseline UI 优化 AI 生成的界面，确保一致性和良好的用户体验","ja":"AIエージェントが生成したインターフェイスを磨くためにBaseline UIを使用し、一貫性と良好的ユーザーエクスペリエンスを実現","ko":"AI 에이전트가 생성한 인터페이스를 다듬기위한 Baseline UI 사용, 일관성과 양질의 사용자 경험 실현","es":"Mejora la calidad de tus interfaces con baseline-ui, un conjunto de habilidades para agentes de IA que aplican Tailwind CSS","fr":"Améliorez la qualité de vos interfaces avec baseline-ui, un ensemble de compétences pour les outils d''IA qui appliquent Tailwind CSS","de":"Verbessern Sie die Qualität Ihrer Oberflächen mit baseline-ui, einem Satz von Fähigkeiten für IA-Tools, die Tailwind CSS anwenden","pt":"Aprenda a aplicar o Baseline UI para melhorar a qualidade das interfaces geradas por agentes de IA. Descubra como usar o Tailwind CSS e outras ferramentas.","ru":"Узнайте, как применить Baseline UI для улучшения качества интерфейсов, созданных ИИ Агентами. Ознакомьтесь с использованием Tailwind CSS и других инструментов.","ar":"تعلم كيفية تطبيق Baseline UI لتحسين جودة الواجهات التي يгенّرها وكلاء الذكاء الاصطناعي. اكتشف كيفية استخدام Tailwind CSS وأدوات أخرى."},"definition":{"en":"baseline-ui is a set of skills that polishes interfaces built by agents, enforcing an opinionated UI baseline to prevent AI-generated interface slop.","zh":"Baseline UI 是一种用于优化 AI 生成界面的技术，强制执行一致的界面基准","ja":"Baseline UIは、AIエージェントが生成したインターフェイスを最適化するために、一貫したインターフェイス基準を強制適用する技術です","ko":"Baseline UI는 AI 에이전트가 생성한 인터페이스를 최적화하는 기술로 일관된 인터페이스 기준을 적용합니다","es":"Baseline-ui es una habilidad que establece una base de interfaz de usuario para agentes de IA","fr":"Baseline-ui est une compétence qui établit une base d''interface utilisateur pour les outils d''IA","de":"Baseline-ui ist eine Fähigkeit, die eine Benutzeroberflächen-Basis für IA-Tools festlegt","pt":"O que é Baseline UI? É um conjunto de habilidades para padronizar e melhorar a qualidade das interfaces geradas por agentes de IA.","ru":"Что такое Baseline UI? Это набор навыков для стандартизации и улучшения качества интерфейсов, созданных ИИ Агентами.","ar":"ما هو Baseline UI؟ هو مجموعة من المهارات لتوحيد و تحسين جودة الواجهات التي يгенّرها وكلاء الذكاء الاصطناعي."},"features":{"en":["Applies opinionated UI baseline to prevent AI-generated interface slop","Reviews files against constraints using the `/baseline-ui <file>` command","Outputs violations, explanations, and concrete fix suggestions at the code level","Enforces use of Tailwind CSS defaults unless custom values exist","Supports constraint application via the `/baseline-ui` command"],"zh":["强制执行一致的界面基准","使用 Tailwind CSS 默认值","优化 AI 生成的界面","支持 `/baseline-ui` 命令","支持 `/baseline-ui <file>` 命令","输出违规、原因和修复建议"],"ja":["一貫したインターフェイス基準を強制適用","Tailwind CSSのデフォルト値を使用","AIエージェントが生成したインターフェイスを最適化","/baseline-ui コマンドをサポート","/baseline-ui <file> コマンドをサポート","違反、原因、修復提案を出力"],"ko":["일관된 인터페이스 기준을 적용","Tailwind CSS 기본 값을 사용","AI 에이전트가 생성한 인터페이스를 최적화","/baseline-ui 명령어 지원","/baseline-ui <file> 명령어 지원","위반, 이유, 수정 제안 출력"],"es":["Aplica Tailwind CSS por defecto","Revisa archivos contra restricciones de interfaz de usuario","Proporciona violaciones, motivos y soluciones concretas","Mejora la calidad de las interfaces de usuario","Soporta comandos como /baseline-ui y /baseline-ui <file>"],"fr":["Applique Tailwind CSS par défaut","Vérifie les fichiers contre les contraintes d''interface utilisateur","Fournit des violations, des raisons et des solutions concrètes","Améliore la qualité des interfaces utilisateur","Prend en charge les commandes comme /baseline-ui et /baseline-ui <file>"],"de":["Wendet Tailwind CSS standardmäßig an","Überprüft Dateien gegen Benutzeroberflächen-Beschränkungen","Bietet Verletzungen, Gründe und konkrete Lösungen","Verbessert die Qualität der Benutzeroberflächen","Unterstützt Befehle wie /baseline-ui und /baseline-ui <file>"],"pt":["Aplicação de padrões de UI com Tailwind CSS","Análise de violações de constraints e sugestões de correção","Integração com outros instrumentos de desenvolvimento","Melhoria da qualidade das interfaces geradas por agentes de IA","Suporte à customização de valores e configurações"],"ru":["Применение стандартов UI с помощью Tailwind CSS","Анализ нарушений ограничений и предложения исправления","Интеграция с другими инструментами разработки","Улучшение качества интерфейсов, созданных ИИ Агентами","Поддержка настройки значений и конфигураций"],"ar":["تطبيق معايير الواجهة باستخدام Tailwind CSS","تحليل انتهاكات القيود واقتراحات التصحيح","التكامل مع أدوات تطوير أخرى","تحسين جودة الواجهات التي يجنّرها وكلاء الذكاء الاصطناعي","دعم تخصيص القيم والتكوين"]},"keywords":{"en":["how to use baseline-ui","baseline-ui setup guide","what is baseline-ui","baseline-ui alternative","baseline-ui vs material ui","baseline-ui install"," Tailwind CSS integration","AI-generated interface polish","UI baseline enforcement"],"zh":["AI界面优化","Baseline UI","Tailwind CSS","AIエージェント","界面优化工具","AI 生成界面","一致的界面基准","界面设计最佳实践"],"ja":["AIエージェント","インターフェイス最適化","Baseline UI","Tailwind CSS","AIエージェントツール","インターフェイスデザイン","一貫したインターフェイス基準","インターフェイス設計ベストプラクティス"],"ko":["AI 에이전트","인터페이스 최적화","Baseline UI","Tailwind CSS","AI 에이전트 도구","인터페이스 디자인","일관된 인터페이스 기준","인터페이스 디자인 베스트 프랙티스"],"es":["baseline-ui","agentes de IA","interfaces de usuario","Tailwind CSS","desarrollo de software","herramientas de IA","mejora de la calidad","configuración de baseline-ui"],"fr":["baseline-ui","outils d''IA","interfaces utilisateur","Tailwind CSS","développement de logiciels","outils d''IA","amélioration de la qualité","configuration de baseline-ui"],"de":["baseline-ui","IA-Tools","Benutzeroberflächen","Tailwind CSS","Software-Entwicklung","IA-Tools","Qualitätsverbesserung","Konfiguration von baseline-ui"],"pt":["Baseline UI","IA Agents","Tailwind CSS","Desenvolvimento de interfaces","Padronização de UI","Análise de violações","Correção de constraints","Customização de valores"],"ru":["Baseline UI","ИИ Агенты","Tailwind CSS","Разработка интерфейсов","Стандартизация UI","Анализ нарушений","Исправление ограничений","Настройка значений"],"ar":["Baseline UI","وكلاء الذكاء الاصطناعي","Tailwind CSS","تطوير الواجهات","توحيد الواجهة","تحليل انتهاكات","تصحيح القيود","تخصيص القيم"]}},"owner":"ibelick","repo":"ui-skills","repoPath":"ibelick/ui-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"baseline-ui","description":"Validates animation durations, enforces typography scale, checks component accessibility, and prevents layout anti-patterns in Tailwind CSS projects. Use when building UI components, reviewing CSS utilities, styling React views, or enforcing design consistency.","bodyPreview":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requ","body":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requested\n- MUST use `motion/react` (formerly `framer-motion`) when JavaScript animation is required\n- SHOULD use `tw-animate-css` for entrance and micro-animations in Tailwind CSS\n- MUST use `cn` utility (`clsx` + `tailwind-merge`) for class logic\n\n## Components\n\n- MUST use accessible component primitives for anything with keyboard or focus behavior (`Base UI`, `React Aria`, `Radix`)\n- MUST use the project’s existing component primitives first\n- NEVER mix primitive systems within the same interaction surface\n- SHOULD prefer [`Base UI`](https://base-ui.com/react/components) for new primitives if compatible with the stack\n- MUST add an `aria-label` to icon-only buttons\n- NEVER rebuild keyboard or focus behavior by hand unless explicitly requested\n\n## Interaction\n\n- MUST use an `AlertDialog` for destructive or irreversible actions\n- SHOULD use structural skeletons for loading states\n- NEVER use `h-screen`, use `h-dvh`\n- MUST respect `safe-area-inset` for fixed elements\n- MUST show errors next to where the action happens\n- NEVER block paste in `input` or `textarea` elements\n\n## Animation\n\n- NEVER add animation unless it is explicitly requested\n- MUST animate only compositor props (`transform`, `opacity`)\n- NEVER animate layout properties (`width`, `height`, `top`, `left`, `margin`, `padding`)\n- SHOULD avoid animating paint properties (`background`, `color`) except for small, local UI (text, icons)\n- SHOULD use `ease-out` on entrance\n- NEVER exceed `200ms` for interaction feedback\n- MUST pause looping animations when off-screen\n- SHOULD respect `prefers-reduced-motion`\n- NEVER introduce custom easing curves unless explicitly requested\n- SHOULD avoid animating large images or full-screen surfaces\n\n## Typography\n\n- MUST use `text-balance` for headings and `text-pretty` for body/paragraphs\n- MUST use `tabular-nums` for data\n- SHOULD use `truncate` or `line-clamp` for dense UI\n- NEVER modify `letter-spacing` (`tracking-*`) unless explicitly requested\n\n## Layout\n\n- MUST use a fixed `z-index` scale (no arbitrary `z-*`)\n- SHOULD use `size-*` for square elements instead of `w-*` + `h-*`\n\n## Performance\n\n- NEVER animate large `blur()` or `backdrop-filter` surfaces\n- NEVER apply `will-change` outside an active animation\n- NEVER use `useEffect` for anything that can be expressed as render logic\n\n## Design\n\n- NEVER use gradients unless explicitly requested\n- NEVER use purple or multicolor gradients\n- NEVER use glow effects as primary affordances\n- SHOULD use Tailwind CSS default shadow scale unless explicitly requested\n- MUST give empty states one clear next action\n- SHOULD limit accent color usage to one per view\n- SHOULD use existing theme or Tailwind CSS color tokens before introducing new ones\n"},"lastSynced":"2026-03-08T02:00:38.687Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing consistent UI interface generation with Tailwind CSS defaults.","zh":"非常适合需要使用Tailwind CSS默认值生成一致的UI接口的前端代理。","ja":"Tailwind CSSのデフォルト値を使用して一貫したUIインターフェイスを生成する必要があるフロントエンドエージェントに最適です。","ko":"Tailwind CSS 기본값을 사용하여 일관된 UI 인터페이스를 생성해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan generación de interfaz de usuario coherente con valores predeterminados de Tailwind CSS.","fr":"Parfait pour les agents Frontend ayant besoin d''une génération d''interface utilisateur cohérente avec les valeurs par défaut de Tailwind CSS.","de":"Perfekt für Frontend-Agents, die eine konsistente Benutzeroberflächen-Generierung mit Tailwind CSS-Standardwerten benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração de interface de usuário consistente com padrões do Tailwind CSS.","ru":"Идеально для агентов Frontend, которым необходима последовательная генерация интерфейса пользователя с использованием настроек Tailwind CSS по умолчанию.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى توليد واجهة مستخدم متسقة مع إعدادات Tailwind CSS الافتراضية."},"recommendation":{"en":"Empowers agents to enforce a consistent UI baseline, preventing slop and ensuring polished interface builds using opinionated constraints and Tailwind CSS defaults, with capabilities for reviewing files against constraints and outputting violations, reasons, and concrete fixes.","zh":"赋予代理人执行一致的UI基线的能力，防止混乱，并确保使用有见解的约束和Tailwind CSS默认值生成精致的接口构建，同时具有审查文件与约束、输出违规、原因和具体修复的能力。","ja":"エージェントに一貫したUI基準を施行する能力を付与し、 Tailwind CSSのデフォルト値と意見のある制約を使用して混乱を防ぎ、洗練されたインターフェイス構築を保証します。さらに、制約に対するファイルのレビュー、違反、理由、具体的な修正の出力が可能です。","ko":"에이전트가 일관된 UI 기준을 강제할 수 있도록 하여 Tailwind CSS 기본값과 의견이 있는 제약을 사용하여 혼란을 방지하고 세련된 인터페이스 구축을 보장합니다. 또한 제약에 대한 파일 검토, 위반, 이유 및 구체적인 수정의 출력이 가능합니다.","es":"Habilita a los agentes a aplicar una base de interfaz de usuario coherente, evitando la falta de uniformidad y asegurando construcciones de interfaz pulidas utilizando restricciones de opinión y valores predeterminados de Tailwind CSS, con capacidades para revisar archivos contra restricciones y generar violaciones, razones y soluciones concretas.","fr":"Permet aux agents d''appliquer une base d''interface utilisateur cohérente, évitant les incohérences et garantissant des constructions d''interface polies en utilisant des contraintes d''opinion et les valeurs par défaut de Tailwind CSS, avec des capacités pour examiner des fichiers contre des contraintes et produire des violations, des raisons et des solutions concrètes.","de":"Ermächtigt Agenten, eine konsistente Benutzeroberflächen-Basis durchzusetzen, Unordnung zu vermeiden und polierte Oberflächenkonstruktionen sicherzustellen, indem sie voreingenommene Einschränkungen und Tailwind CSS-Standardwerte verwenden, mit Fähigkeiten zum Überprüfen von Dateien gegen Einschränkungen und zum Ausgeben von Verletzungen, Gründen und konkreten Lösungen.","pt":"Habilita os agentes a impor uma linha de base de interface de usuário consistente, prevenindo inconsistências e garantindo compilações de interface polidas usando restrições opinadas e padrões do Tailwind CSS, com capacidades para revisar arquivos contra restrições e produzir violações, razões e correções concretas.","ru":"Наделяет агентов возможностью обеспечить последовательную базовую линию интерфейса пользователя, предотвращая беспорядок и гарантируя отполированные сборки интерфейса с использованием предвзятых ограничений и настроек Tailwind CSS по умолчанию, а также имея возможности для проверки файлов на соответствие ограничениям и вывода нарушений, причин и конкретных исправлений.","ar":"يمنح الوكلاء صلاحية فرض قاعدة اساسية متسقة لواجهة المستخدم، ومنع الفوضى وضمان إنشاء واجهة متطورة باستخدام قيود مشروعة وإعدادات Tailwind CSS الافتراضية، مع القدرة على مراجعة الملفات مقابل القيود وإخراج انتهاكات وأسباب وتصحيحات ملموسة."},"useCases":{"en":["Enforcing consistent UI design patterns","Reviewing UI files for constraint violations","Generating polished interface builds with Tailwind CSS"],"zh":["执行一致的UI设计模式","审查UI文件以查找约束违规","使用Tailwind CSS生成精致的接口构建"],"ja":["一貫したUIデザインパターンの実施","制約違反のためのUIファイルのレビュー","Tailwind CSSを使用した洗練されたインターフェイス構築の生成"],"ko":["일관된 UI 디자인 패턴의 적용","제약 위반에 대한 UI 파일의 검토","Tailwind CSS를 사용한 세련된 인터페이스 구축의 생성"],"es":["Aplicar patrones de diseño de interfaz de usuario coherentes","Revisar archivos de interfaz de usuario para violaciones de restricciones","Generar construcciones de interfaz pulidas con Tailwind CSS"],"fr":["Mettre en œuvre des modèles de conception d''interface utilisateur cohérents","Examiner les fichiers d''interface utilisateur pour les violations de contraintes","Générer des constructions d''interface polies avec Tailwind CSS"],"de":["Durchsetzen konsistenter Benutzeroberflächen-Designmuster","Überprüfen von Benutzeroberflächen-Dateien auf Einschränkungsverletzungen","Erzeugen polierter Oberflächenkonstruktionen mit Tailwind CSS"],"pt":["Impor padrões de design de interface de usuário consistentes","Revisar arquivos de interface de usuário para violações de restrições","Gerar compilações de interface polidas com Tailwind CSS"],"ru":["Внедрение последовательных шаблонов дизайна интерфейса пользователя","Проверка файлов интерфейса пользователя на нарушения ограничений","Генерация отполированных сборок интерфейса с использованием Tailwind CSS"],"ar":["فرض أنماط تصميم واجهة المستخدم المتسقة","مراجعة ملفات واجهة المستخدم لانتهاكات القيود","توليد بناء واجهة متطورة باستخدام Tailwind CSS"]},"limitations":{"en":["Requires Tailwind CSS defaults unless custom values exist","Limited to enforcing predefined UI baseline constraints"],"zh":["需要Tailwind CSS默认值，除非自定义值存在","仅限于执行预定义的UI基线约束"],"ja":["カスタム値が存在しない限り、Tailwind CSSのデフォルト値が必要","予め定義されたUI基準の制約の施行のみに限定"],"ko":["사용자 정의 값이 있는 경우를 제외하고 Tailwind CSS 기본값이 필요하다","사전에 정의된 UI 기준 제약의 적용에만 제한됨"],"es":["Requiere valores predeterminados de Tailwind CSS a menos que existan valores personalizados","Limitado a la aplicación de restricciones de base de interfaz de usuario predefinidas"],"fr":["Nécessite les valeurs par défaut de Tailwind CSS à moins que des valeurs personnalisées existent","Limité à l''application de contraintes de base d''interface utilisateur prédéfinies"],"de":["Erfordert Tailwind CSS-Standardwerte, sofern keine benutzerdefinierten Werte vorhanden sind","Begrenzt auf die Durchsetzung von vorgegebenen Benutzeroberflächen-Basiseinschränkungen"],"pt":["Exige padrões do Tailwind CSS a menos que existam valores personalizados","Limitado a impor restrições de linha de base de interface de usuário predefinidas"],"ru":["Требует настроек Tailwind CSS по умолчанию, если не существуют пользовательские значения","Ограничен обеспечением предопределенных ограничений базовой линии интерфейса пользователя"],"ar":["يتطلب إعدادات Tailwind CSS الافتراضية除 إذا كانت هناك قيم مخصصة","محدود بفرض قيود قاعدة اساسية لواجهة المستخدم مسبقة التعريف"]},"version":4},"contentHash":"9bb2f868098a9d28ce7d10383039a28169d838cea6299f9df3706ecda7932949","qualityScore":29}');
