INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ibelick/ui-skills/baseline-ui', 'baseline-ui', 'ibelick', 'ui-skills', 'community', 'baseline-ui ibelick ui-skills community baseline-ui enforces a consistent UI baseline for AI-generated interfaces, benefiting developers who want to polish their interface builds. It applies constraints to prevent UI slop. Baseline UI 是一个强制执行一致的界面基准的技能，用于优化 AI 生成的界面。它使用 Tailwind CSS 默认值来确保一致性和良好的用户体验 Baseline UIは、AIエージェントが生成したインターフェイスを一貫性と良好的ユーザーエクスペリエンスを持つようにするための、一貫したインターフェイス基準を強制適用するスキルです。Tailwind CSSのデフォルト値を使用して一貫性を保ちます Baseline UI는 일관된 인터페이스 기준을 적용하여 AI 에이전트가 생성한 인터페이스를 최적화하는 기술입니다. Tailwind CSS 기본 값을 사용하여 일관성을 유지합니다 Baseline-ui es un conjunto de habilidades que aplican una base de interfaz de usuario opinada para evitar la generación de interfaces descuidadas por agentes de IA. Baseline-ui est un ensemble de compétences qui appliquent une base d''interface utilisateur avisée pour éviter la génération d''interfaces négligées par les outils d''IA Baseline-ui ist ein Satz von Fähigkeiten, die eine Meinungsbasierte Benutzeroberflächen-Basis anwenden, um die Erzeugung von vernachlässigten Oberflächen durch IA-Tools zu vermeiden O Baseline UI é um conjunto de habilidades para melhorar a qualidade das interfaces geradas por agentes de IA, utilizando o Tailwind CSS e outras ferramentas. Baseline UI - это набор навыков для улучшения качества интерфейсов, созданных ИИ Агентами, с использованием Tailwind CSS и других инструментов. Baseline UI هو مجموعة من المهارات لتحسين جودة الواجهات التي يгенّرها وكلاء الذكاء الاصطناعي، باستخدام Tailwind CSS وأدوات أخرى. how to use baseline-ui baseline-ui setup guide what is baseline-ui baseline-ui alternative baseline-ui vs material ui baseline-ui install Tailwind CSS integration AI-generated interface polish UI baseline enforcement AI界面优化 Baseline UI Tailwind CSS AIエージェント 界面优化工具 AI 生成界面 一致的界面基准 界面设计最佳实践 Applies opinionated UI baseline to prevent AI-generated interface slop Reviews files against constraints using the `/baseline-ui <file>` command Outputs violations, explanations, and concrete fix suggestions at the code level Enforces use of Tailwind CSS defaults unless custom values exist Supports constraint application via the `/baseline-ui` command baseline-ui is a set of skills that polishes interfaces built by agents, enforcing an opinionated UI baseline to prevent AI-generated interface slop.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CloudAI-X/claude-workflow-v2/vercel-react-best-practices', 'community', 'CloudAI-X', 'claude-workflow-v2', 'CloudAI-X/claude-workflow-v2', 'vercel-react-best-practices', 0, 0, 29, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:54.349Z', '4c0cd31ccfe6314b8209218baaf9e1721d08ee30955ff023d2e6cd48fde0e945', '{"id":"CloudAI-X/claude-workflow-v2/vercel-react-best-practices","name":"vercel-react-best-practices","description":{"en":"The Vercel React Best Practices skill provides a comprehensive performance optimization guide for React and Next.js applications, with 45 rules to automate refactoring and code generation.","zh":"Vercel React 最佳实践提供了 45 条规则，用于优化 React 和 Next.js 应用性能","ja":"Vercel React ベストプラクティスは、React と Next.js アプリのパフォーマンスを最適化する 45 のルールを提供します","ko":"Vercel React 최적화는 React 및 Next.js 애플리케이션의 성능을 최적화하는 45개의 규칙을 제공합니다","es":"Guía de optimización de rendimiento para aplicaciones React y Next.js, con 45 reglas en 8 categorías para una refactorización y generación de código automatizada","fr":"Guide d''optimisation des performances pour les applications React et Next.js, avec 45 règles dans 8 catégories pour une refactoring et une génération de code automatisées","de":"Leitfaden zur Leistungsoptimierung für React- und Next.js-Anwendungen, mit 45 Regeln in 8 Kategorien für eine automatisierte Refactoring und Codegenerierung","pt":"Otimização de desempenho para aplicações React e Next.js com 45 regras em 8 categorias","ru":"Оптимизация производительности для приложений React и Next.js с 45 правилами в 8 категориях","ar":"تحسين الأداء لتطبيقات React و Next.js مع 45 قاعدة في 8 فئات"},"seo":{"title":{"en":"Vercel React Best Practices: Optimization Guide for AI Ag...","zh":"Vercel React 最佳实践设置指南","ja":"Vercel React ベストプラクティス設定ガイド","ko":"Vercel React 최적화 설정 가이드","es":"Guía de configuración de Vercel React Best Practices","fr":"Configurer Vercel React Best Practices pour une meilleure...","de":"Vercel React Best Practices Einrichtungsleitfaden","pt":"Guia de Configuração do Vercel React Best Practices","ru":"ИИ Агенты: Vercel React Лучшие Практики","ar":"إعداد أداة Vercel React لأفضل الممارسات"},"description":{"en":"Unlock performance optimization for React and Next.js apps with Vercel''s comprehensive guide, featuring 45 rules across 8 categories - get started now!","zh":"使用 Vercel React 最佳实践提高性能，优化 React 和 Next.js 应用","ja":"Vercel React ベストプラクティスを使用してパフォーマンスを向上させる","ko":"Vercel React 최적화하여 React 및 Next.js 애플리케이션 성능 개선","es":"Optimice el rendimiento de sus aplicaciones React y Next.js con las mejores prácticas de Vercel, incluyendo 45 reglas en 8 categorías","fr":"Améliorez les performances de vos applications React et Next.js avec les meilleures pratiques de Vercel, comprenant 45 règles dans 8 catégories","de":"Optimieren Sie die Leistung Ihrer React- und Next.js-Anwendungen mit den Best Practices von Vercel, einschließlich 45 Regeln in 8 Kategorien","pt":"Aprenda a otimizar o desempenho do seu aplicativo React com as melhores práticas do Vercel","ru":"Узнайте, как оптимизировать производительность вашего приложения React с помощью лучших практик Vercel","ar":"تعلم كيف تحسن أداء تطبيقك React باستخدام أفضل الممارسات من Vercel"},"definition":{"en":"Vercel-react-best-practices is a Universal Claude Code workflow plugin providing guidelines for React and Next.js development, component writing, and data fetching patterns.","zh":"Vercel React 最佳实践是一套用于优化 React 和 Next.js 应用性能的规则集合","ja":"Vercel React ベストプラクティスは、React と Next.js アプリのパフォーマンスを最適化するためのルールの集合です","ko":"Vercel React 최적화는 React 및 Next.js 애플리케이션의 성능을 최적화하는 규칙의 집합입니다","es":"Vercel React Best Practices es una guía de optimización de rendimiento para aplicaciones React y Next.js","fr":"Vercel React Best Practices est un guide d''optimisation des performances pour les applications React et Next.js","de":"Vercel React Best Practices ist ein Leitfaden zur Leistungsoptimierung für React- und Next.js-Anwendungen","pt":"O que são as melhores práticas do Vercel para React?","ru":"Что такое лучшие практики Vercel для React?","ar":"ما هي أفضل الممارسات من Vercel ل React?"},"features":{"en":["Contains 45 rules across 8 categories for performance optimization","Prioritizes rules by impact for automated refactoring and code generation","Provides guidelines for React and Next.js development, component writing, and data fetching patterns","Supports bundle optimization for improved application performance","Includes triggers for React or Next.js development, component writing, and data fetching patterns"],"zh":["包含 45 条优化规则","覆盖 8 个优化类别","支持 React 和 Next.js 应用","自动重构和代码生成","优化数据获取和包大小"],"ja":["45 の最適化ルールを含む","8 つの最適化カテゴリをカバー","React と Next.js アプリをサポート","自動リファクタリングとコード生成","データ取得とパッケージサイズの最適化"],"ko":["45개의 최적화 규칙 포함","8개의 최적화 카테고리 커버","React 및 Next.js 애플리케이션 지원","자동 리팩토링 및 코드 생성","데이터 가져오기 및 패키지 크기 최적화"],"es":["45 reglas en 8 categorías para la optimización de rendimiento","Refactorización y generación de código automatizada","Guía para la escritura de componentes y patrones de obtención de datos","Optimización de paquetes para una mejor carga","Compatibilidad con React y Next.js"],"fr":["45 règles dans 8 catégories pour l''optimisation des performances","Refactoring et génération de code automatisées","Guide pour l''écriture de composants et de modèles de récupération de données","Optimisation des bundles pour un meilleur chargement","Compatibilité avec React et Next.js"],"de":["45 Regeln in 8 Kategorien für die Leistungsoptimierung","Automatisierte Refactoring und Codegenerierung","Leitfaden für die Erstellung von Komponenten und Datenabrufmustern","Optimierung von Paketen für eine bessere Ladezeit","Kompatibilität mit React und Next.js"],"pt":["45 regras de otimização em 8 categorias","Guia de refatoração automática e geração de código","Otimização de bundle e padrões de busca de dados","Compatibilidade com React e Next.js","Priorização de regras por impacto"],"ru":["45 правил оптимизации в 8 категориях","Руководство по автоматической рефакторации и генерации кода","Оптимизация пакета и шаблонов поиска данных","Совместимость с React и Next.js","Приоритизация правил по воздействию"],"ar":["45 قاعدة لتحسين الأداء في 8 فئات","دليل لإعادة هيكلة تلقائية وتوليد رمز","تحسين حزمة ونمط بحث البيانات","التوافق مع React و Next.js","التحديد الأولوي لالقواعد حسب التأثير"]},"keywords":{"en":["how to use vercel-react-best-practices","vercel-react-best-practices setup guide","react performance optimization","next.js optimization techniques","vercel-react-best-practices vs webpack","vercel-react-best-practices install","what is vercel-react-best-practices","vercel-react-best-practices alternative","react and next.js best practices"],"zh":["Vercel React 最佳实践","React 优化","Next.js 优化","性能优化","自动重构","代码生成","AIエージェント","React 开发"],"ja":["Vercel React ベストプラクティス","React 最適化","Next.js 最適化","パフォーマンス最適化","自動リファクタリング","コード生成","AIエージェント","React 開発"],"ko":["Vercel React 최적화","React 최적화","Next.js 최적화","성능 최적화","자동 리팩토링","코드 생성","AI 에이전트","React 개발"],"es":["Vercel React Best Practices","optimización de rendimiento React","mejores prácticas Next.js","refactorización automatizada","generación de código React","optimización de paquetes","desarrollo de aplicaciones web","herramientas de desarrollo React","AI Agents para desarrollo web"],"fr":["Vercel React Best Practices","optimisation des performances React","meilleures pratiques Next.js","refactoring automatisé","génération de code React","optimisation des bundles","développement d''applications web","outils de développement React","Agents IA pour le développement web"],"de":["Vercel React Best Practices","Leistungsoptimierung React","Best Practices Next.js","automatisierte Refactoring","Codegenerierung React","Optimierung von Paketen","Webanwendungs-Entwicklung","React-Entwicklungstools","KI-Agents für Webentwicklung"],"pt":["vercel react","otimização de desempenho react","melhores práticas react","react next.js","otimização de bundle","padrões de busca de dados","refatoração automática","geração de código"],"ru":["vercel react","оптимизация производительности react","лучшие практики react","react next.js","оптимизация пакета","шаблоны поиска данных","автоматическая рефакторация","генерация кода"],"ar":["vercel react","تحسين الأداء react","أفضل الممارسات react","react next.js","تحسين حزمة","نمط بحث البيانات","إعادة هيكلة تلقائية","توليد رمز"]}},"owner":"CloudAI-X","repo":"claude-workflow-v2","repoPath":"CloudAI-X/claude-workflow-v2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.283Z","topics":[],"category":"community","skillMd":{"name":"vercel-react-best-practices","description":"React and Next.js performance optimization guidelines from Vercel Engineering. This skill should be used when writing, reviewing, or refactoring React/Next.js code to ensure optimal performance patterns. Triggers on tasks involving React components, Next.js pages, data fetching, bundle optimization, or performance improvements.","bodyPreview":"# Vercel React Best Practices\n\n### When to Load\n\n- **Trigger**: React or Next.js development, component writing, data fetching patterns, bundle optimization\n- **Skip**: Project does not use React or Next.js\n\nComprehensive performance optimization guide for React and Next.js applications, maintained by Vercel. Contains 45 rules across 8 categories, prioritized by impact to guide automated refactoring and code generation.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Writing new React com","body":"# Vercel React Best Practices\n\n### When to Load\n\n- **Trigger**: React or Next.js development, component writing, data fetching patterns, bundle optimization\n- **Skip**: Project does not use React or Next.js\n\nComprehensive performance optimization guide for React and Next.js applications, maintained by Vercel. Contains 45 rules across 8 categories, prioritized by impact to guide automated refactoring and code generation.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Writing new React components or Next.js pages\n- Implementing data fetching (client or server-side)\n- Reviewing code for performance issues\n- Refactoring existing React/Next.js code\n- Optimizing bundle size or load times\n\n## Rule Categories by Priority\n\n| Priority | Category                  | Impact      | Prefix       |\n| -------- | ------------------------- | ----------- | ------------ |\n| 1        | Eliminating Waterfalls    | CRITICAL    | `async-`     |\n| 2        | Bundle Size Optimization  | CRITICAL    | `bundle-`    |\n| 3        | Server-Side Performance   | HIGH        | `server-`    |\n| 4        | Client-Side Data Fetching | MEDIUM-HIGH | `client-`    |\n| 5        | Re-render Optimization    | MEDIUM      | `rerender-`  |\n| 6        | Rendering Performance     | MEDIUM      | `rendering-` |\n| 7        | JavaScript Performance    | LOW-MEDIUM  | `js-`        |\n| 8        | Advanced Patterns         | LOW         | `advanced-`  |\n\n## Quick Reference\n\n### 1. Eliminating Waterfalls (CRITICAL)\n\n- `async-defer-await` - Move await into branches where actually used\n- `async-parallel` - Use Promise.all() for independent operations\n- `async-dependencies` - Use better-all for partial dependencies\n- `async-api-routes` - Start promises early, await late in API routes\n- `async-suspense-boundaries` - Use Suspense to stream content\n\n### 2. Bundle Size Optimization (CRITICAL)\n\n- `bundle-barrel-imports` - Import directly, avoid barrel files\n- `bundle-dynamic-imports` - Use next/dynamic for heavy components\n- `bundle-defer-third-party` - Load analytics/logging after hydration\n- `bundle-conditional` - Load modules only when feature is activated\n- `bundle-preload` - Preload on hover/focus for perceived speed\n\n### 3. Server-Side Performance (HIGH)\n\n- `server-cache-react` - Use React.cache() for per-request deduplication\n- `server-cache-lru` - Use LRU cache for cross-request caching\n- `server-serialization` - Minimize data passed to client components\n- `server-parallel-fetching` - Restructure components to parallelize fetches\n- `server-after-nonblocking` - Use after() for non-blocking operations\n\n### 4. Client-Side Data Fetching (MEDIUM-HIGH)\n\n- `client-swr-dedup` - Use SWR for automatic request deduplication\n- `client-event-listeners` - Deduplicate global event listeners\n\n### 5. Re-render Optimization (MEDIUM)\n\n- `rerender-defer-reads` - Don''t subscribe to state only used in callbacks\n- `rerender-memo` - Extract expensive work into memoized components\n- `rerender-dependencies` - Use primitive dependencies in effects\n- `rerender-derived-state` - Subscribe to derived booleans, not raw values\n- `rerender-functional-setstate` - Use functional setState for stable callbacks\n- `rerender-lazy-state-init` - Pass function to useState for expensive values\n- `rerender-transitions` - Use startTransition for non-urgent updates\n\n### 6. Rendering Performance (MEDIUM)\n\n- `rendering-animate-svg-wrapper` - Animate div wrapper, not SVG element\n- `rendering-content-visibility` - Use content-visibility for long lists\n- `rendering-hoist-jsx` - Extract static JSX outside components\n- `rendering-svg-precision` - Reduce SVG coordinate precision\n- `rendering-hydration-no-flicker` - Use inline script for client-only data\n- `rendering-activity` - Use Activity component for show/hide\n- `rendering-conditional-render` - Use ternary, not && for conditionals\n\n### 7. JavaScript Performance (LOW-MEDIUM)\n\n- `js-batch-dom-css` - Group CSS changes via classes or cssText\n- `js-index-maps` - Build Map for repeated lookups\n- `js-cache-property-access` - Cache object properties in loops\n- `js-cache-function-results` - Cache function results in module-level Map\n- `js-cache-storage` - Cache localStorage/sessionStorage reads\n- `js-combine-iterations` - Combine multiple filter/map into one loop\n- `js-length-check-first` - Check array length before expensive comparison\n- `js-early-exit` - Return early from functions\n- `js-hoist-regexp` - Hoist RegExp creation outside loops\n- `js-min-max-loop` - Use loop for min/max instead of sort\n- `js-set-map-lookups` - Use Set/Map for O(1) lookups\n- `js-tosorted-immutable` - Use toSorted() for immutability\n\n### 8. Advanced Patterns (LOW)\n\n- `advanced-event-handler-refs` - Store event handlers in refs\n- `advanced-use-latest` - useLatest for stable callback refs\n\n## Full Compiled Document\n\nFor the complete guide with all rules expanded and detailed code examples, see: `AGENTS.md`\n\nEach rule contains:\n\n- Brief explanation of why it matters\n- Incorrect code example with explanation\n- Correct code example with explanation\n- Additional context and references\n"},"lastSynced":"2026-03-08T02:00:54.349Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced React and Next.js performance optimization capabilities.","zh":"非常适合需要高级 React 和 Next.js 性能优化能力的前端代理。","ja":"React と Next.js の高度なパフォーマンス最適化機能が必要なフロントエンドエージェントに最適です。","ko":"고급 React 및 Next.js 성능 최적화 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes de frontend que necesitan capacidades avanzadas de optimización de rendimiento de React y Next.js.","fr":"Parfait pour les agents frontend nécessitant des fonctionnalités avancées d''optimisation des performances de React et Next.js.","de":"Perfekt für Frontend-Agents, die erweiterte Leistungsoptimierungsfunktionen für React und Next.js benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de otimização de performance do React e Next.js.","ru":"Идеально подходит для агентов фронтенда, которым требуются расширенные возможности оптимизации производительности React и Next.js.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إمكانيات متقدمة لتحسين أداء React و Next.js."},"recommendation":{"en":"Empowers agents to automate refactoring and code generation for React and Next.js applications using 45 rules across 8 categories, prioritized by impact, and leveraging Vercel''s best practices for bundle optimization and data fetching patterns.","zh":"赋予代理人使用 45 条规则、跨 8 个类别、按影响优先排序，并利用 Vercel 的最佳实践来优化包和数据获取模式，自动化 React 和 Next.js 应用的重构和代码生成。","ja":"エージェントに、45 のルールを使用して、8 つのカテゴリにわたって、影響度に基づいて優先順位付けを行い、Vercel のベストプラクティスを活用してバンドルとデータ取得パターンを最適化し、React と Next.js アプリケーションのリファクタリングとコード生成を自動化する機能を提供します。","ko":"45개의 규칙을 사용하여 8개의 카테고리에서 영향에 따라 우선 순위를 정하고 Vercel의 최적화 및 데이터 가져오기 패턴에 대한 모범 사례를 활용하여 React 및 Next.js 애플리케이션의 리팩토링 및 코드 생성을 자동화하는 기능을 에이전트에게 제공합니다.","es":"Habilita a los agentes a automatizar la refactorización y la generación de código para aplicaciones de React y Next.js utilizando 45 reglas en 8 categorías, priorizadas por impacto, y aprovechando las mejores prácticas de Vercel para la optimización de paquetes y los patrones de obtención de datos.","fr":"Permet aux agents d''automatiser la réorganisation et la génération de code pour les applications React et Next.js en utilisant 45 règles dans 8 catégories, priorisées par impact, et en exploitant les meilleures pratiques de Vercel pour l''optimisation des packages et les modèles d''obtention de données.","de":"Ermächtigt die Agenten, die Neukonfiguration und Codegenerierung für React- und Next.js-Anwendungen zu automatisieren, indem sie 45 Regeln in 8 Kategorien verwenden, die nach Auswirkung priorisiert sind und die besten Praktiken von Vercel für die Optimierung von Paketen und die Datenabrufmuster nutzen.","pt":"Habilita os agentes a automatizar a refatoração e geração de código para aplicações React e Next.js usando 45 regras em 8 categorias, priorizadas por impacto, e aproveitando as melhores práticas da Vercel para otimização de bundle e padrões de busca de dados.","ru":"Наделяет агентов возможностью автоматизировать рефакторинг и генерацию кода для приложений React и Next.js с использованием 45 правил в 8 категориях, отсортированных по степени воздействия, и использует лучшие практики Vercel для оптимизации пакетов и шаблонов запроса данных.","ar":"تمكّن الوكلاء من تلقين إعادة هيكلة وتوليد رمز لتقنيات React و Next.js باستخدام 45 قاعدة في 8 فئات، مصنفة حسب التأثير، واستخدام أفضل الممارسات من Vercel لتحسين الحزمة وأنماط استرجاع البيانات."},"useCases":{"en":["Automating code optimization for React components","Generating optimized Next.js configurations","Refactoring data fetching patterns for improved performance"],"zh":["自动优化 React 组件的代码","生成优化的 Next.js 配置","重构数据获取模式以提高性能"],"ja":["React コンポーネントのコードを自動で最適化する","最適化された Next.js 構成を生成する","パフォーマンスの向上のためにデータ取得パターンをリファクタリングする"],"ko":["React 컴포넌트의 코드를 자동으로 최적화하는 것","최적화된 Next.js 구성을 생성하는 것","성능 향상을 위해 데이터 가져오기 패턴을 리팩토링하는 것"],"es":["Automatizar la optimización de código para componentes de React","Generar configuraciones de Next.js optimizadas","Reorganizar los patrones de obtención de datos para mejorar el rendimiento"],"fr":["Automatiser l''optimisation du code pour les composants React","Générer des configurations Next.js optimisées","Réorganiser les modèles d''obtention de données pour améliorer les performances"],"de":["Automatisieren der Codeoptimierung für React-Komponenten","Generieren von optimierten Next.js-Konfigurationen","Neukonfigurieren der Datenabrufmuster für verbesserte Leistung"],"pt":["Automatizar otimização de código para componentes React","Gerar configurações otimizadas do Next.js","Refatorar padrões de busca de dados para melhorar o desempenho"],"ru":["Автоматизировать оптимизацию кода для компонентов React","Генерировать оптимизированные конфигурации Next.js","Пересмотреть шаблоны запроса данных для улучшения производительности"],"ar":["تلقين تحسين رمز للمكونات React","توليد تكوينات Next.js المُحسّنة","إعادة هيكلة أنماط استرجاع البيانات لتحسين الأداء"]},"limitations":{"en":["Requires React or Next.js project","Limited to JavaScript and TypeScript support"],"zh":["需要 React 或 Next.js 项目","仅限 JavaScript 和 TypeScript 支持"],"ja":["React または Next.js プロジェクトが必要","JavaScript と TypeScript のみをサポート"],"ko":["React 또는 Next.js 프로젝트가 필요함","JavaScript 및 TypeScript만 지원"],"es":["Requiere un proyecto de React o Next.js","Limitado al soporte de JavaScript y TypeScript"],"fr":["Nécessite un projet React ou Next.js","Limité au support de JavaScript et TypeScript"],"de":["Benötigt ein React- oder Next.js-Projekt","Begrenzt auf JavaScript- und TypeScript-Unterstützung"],"pt":["Exige projeto React ou Next.js","Limitado ao suporte a JavaScript e TypeScript"],"ru":["Требуется проект React или Next.js","Ограничен поддержкой только JavaScript и TypeScript"],"ar":["يتطلب مشروع React أو Next.js","محدود بالدعم لجافا سكريبت وطيب سكريبت فقط"]},"version":4},"contentHash":"4c0cd31ccfe6314b8209218baaf9e1721d08ee30955ff023d2e6cd48fde0e945","qualityScore":29}');
