INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grndlvl/software-patterns/gof-patterns', 'community', 'grndlvl', 'software-patterns', 'grndlvl/software-patterns', 'gof-patterns', 0, 0, 29, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:38.179Z', '90627ded5fee2428f28030d5ca82e7f35088d0344c2ca36b4ba7c20cccd17f55', '{"id":"grndlvl/software-patterns/gof-patterns","name":"gof-patterns","description":{"en":"The gof-patterns skill provides a comprehensive reference for Gang of Four design patterns, offering language-agnostic guidance with pseudocode examples for developers.","zh":"GoF 设计模式参考指南提供了语言无关的指导和伪代码示例，适用于任何编程语言","ja":"GoF デザインパターンリファレンスガイドは、言語非依存のガイダンスと疑似コードの例を提供","ko":"GoF 디자인 패턴 레퍼런스 가이드는 언어 중립 가이드 및 유사 코드 예제를 제공","es":"Habilidad de referencia para patrones de diseño GoF con ejemplos de pseudocódigo para mejorar la estructura del código","fr":"Compétence de référence pour les modèles de conception GoF avec des exemples de pseudocode pour améliorer la structure du code","de":"Referenzfähigkeit für GoF-Entwurfsmuster mit Pseudocode-Beispielen zur Verbesserung der Code-Struktur","pt":"O GoF Patterns é um recurso de referência abrangente para padrões de projeto, fornecendo orientação linguagem-agnóstica com exemplos de pseudocódigo","ru":"ИИ Агенты: Шаблоны проектирования GoF - это полный справочник для разработчиков, предлагающий языково-независимое руководство с примерами псевдокода","ar":"ميزة أنماط التصميم GoF هي مرجع شامل لتنمية التطبيقات، يوفر إرشادات غير متعلقة باللغة مع أمثلة من الكود"},"seo":{"title":{"en":"gof-patterns: Comprehensive Design Patterns Reference | A...","zh":"GoF 设计模式参考指南 - Claude Code AIエージェント","ja":"GoF デザインパターンリファレンスガイド - Claude Code AIエージェント","ko":"GoF 디자인 패턴 레퍼런스 가이드 - Claude Code AI 에이전트","es":"Guía de Patrones de Diseño GoF para Desarrolladores","fr":"Guide des Modèles de Conception GoF pour Développeurs","de":"GoF-Entwurfsmuster-Handbuch für Entwickler","pt":"Guia de Padrões de Projeto GoF: Melhores Práticas para De...","ru":"ИИ Агенты: Руководство по шаблонам проектирования GoF для...","ar":"دليل أنماط التصميم GoF: إرشادات لتنمية التطبيقات"},"description":{"en":"Unlock the power of Gang of Four design patterns with gof-patterns. Get language-agnostic guidance and pseudocode examples to improve your code architecture","zh":"了解 GoF 设计模式的综合参考指南，包括语言无关的指导和伪代码示例","ja":"GoF デザインパターンの包括的なリファレンスガイド。言語非依存のガイダンスと疑似コードの例を提供","ko":"GoF 디자인 패턴에 대한 종합 참조 가이드, 언어 중립 가이드 및 유사 코드 예제 제공","es":"Aprende a implementar patrones de diseño GoF con ejemplos de pseudocódigo y mejora tu código con esta habilidad de Claude Code","fr":"Apprenez à implémenter les modèles de conception GoF avec des exemples de pseudocode et améliorez votre code avec cette compétence de Claude Code","de":"Erfahren Sie, wie Sie GoF-Entwurfsmuster mit Pseudocode-Beispielen implementieren und Ihren Code mit dieser Fähigkeit von Claude Code verbessern","pt":"Aprenda a implementar padrões de projeto GoF com nosso guia completo, incluindo pseudocódigo e exemplos para melhorar sua arquitetura de software","ru":"Изучите шаблоны проектирования GoF с нашей полной справкой, включая псевдокод и примеры для улучшения вашей программной архитектуры с помощью ИИ Агентов","ar":"تعلم كيفية تنفيذ أنماط التصميم GoF مع دليلنا الشامل، بما في ذلك الأمثلة والكود لتحسين هيكل البرمجيات"},"definition":{"en":"gof-patterns is a comprehensive reference skill for Gang of Four design patterns, providing language-agnostic guidance and pseudocode examples","zh":"GoF 设计模式是指 Gang of Four 设计模式，提供了软件设计的最佳实践","ja":"GoF デザインパターンは、Gang of Four デザインパターンのこと。ソフトウェア設計のベストプラクティスを提供","ko":"GoF 디자인 패턴은 Gang of Four 디자인 패턴을 말하며, 소프트웨어 설계의 모범 사례를 제공","es":"¿Qué es GoF? GoF son patrones de diseño de software que proporcionan soluciones a problemas comunes de diseño","fr":"Qu''est-ce que GoF? GoF sont des modèles de conception de logiciel qui fournissent des solutions à des problèmes de conception courants","de":"Was ist GoF? GoF sind Entwurfsmuster für Software, die Lösungen für häufige Entwurfsprobleme bereitstellen","pt":"O que são padrões de projeto GoF? São soluções reutilizáveis para problemas comuns de design de software","ru":"Что такое шаблоны проектирования GoF? Это повторно используемые решения для общих проблем проектирования программного обеспечения","ar":"ما هي أنماط التصميم GoF؟ هي حلول قابلة لإعادة الاستخدام لمشاكل تصميم البرمجيات الشائعة"},"features":{"en":["Provides language-agnostic guidance for design pattern implementation","Offers pseudocode examples for translation to any programming language","Automatically activates for design pattern-related queries and refactoring","Supports architecture and decoupling discussions","Includes reference for choosing between patterns for design problems"],"zh":["语言无关的指导","伪代码示例","设计模式的综合参考","结构改进的建议","架构和解耦的讨论"],"ja":["言語非依存のガイダンス","疑似コードの例","デザインパターンの包括的なリファレンス","構造改善の提案","アーキテクチャと結合の議論"],"ko":["언어 중립 가이드","유사 코드 예제","디자인 패턴의 종합 참조","구조 개선의 제안","아키텍처와 결합의 논의"],"es":["Guía de patrones de diseño GoF","Ejemplos de pseudocódigo para implementación","Mejora de la estructura del código","Apoyo para la refactorización de código","Discusión de arquitectura y desacoplamiento"],"fr":["Guide des modèles de conception GoF","Exemples de pseudocode pour la mise en œuvre","Amélioration de la structure du code","Support pour la refactorisation de code","Discussion d''architecture et de découplage"],"de":["Handbuch für GoF-Entwurfsmuster","Pseudocode-Beispiele für die Implementierung","Verbesserung der Code-Struktur","Unterstützung für die Refaktorierung von Code","Diskussion von Architektur und Entkopplung"],"pt":["Orientação linguagem-agnóstica para implementação de padrões de projeto","Exemplos de pseudocódigo para facilitar a tradução para qualquer linguagem de programação","Guia para escolher entre padrões para resolver problemas de design","Melhorias estruturais para refatoração de código","Discussão de arquitetura e decoupling"],"ru":["Языково-независимое руководство для реализации шаблонов проектирования","Примеры псевдокода для облегчения перевода на любой язык программирования","Справочник для выбора между шаблонами для решения проблем проектирования","Структурные улучшения для рефакторинга кода","Обсуждение архитектуры и декуплинга"],"ar":["توجيه غير متعلقة باللغة لتنفيذ أنماط التصميم","أمثلة من الكود لتحويله بسهولة إلى أي لغة برمجة","دليل لاختيار بين الأنماط لحل مشاكل التصميم","تحسينات هيكلية لتحسين الكود","مناقشة هيكل البرمجيات وتنسيقها"]},"keywords":{"en":["how to use gof-patterns","gof-patterns design patterns reference","gof-patterns alternative","gof-patterns vs creational patterns","gof-patterns setup guide","gof-patterns install for Claude Code"],"zh":["GoF 设计模式","语言无关的指导","伪代码示例","软件设计","设计模式","结构改进","架构","解耦","AIエージェント","Claude Code"],"ja":["GoF デザインパターン","言語非依存のガイダンス","疑似コードの例","ソフトウェア設計","デザインパターン","構造改善","アーキテクチャ","結合","AIエージェント","Claude Code"],"ko":["GoF 디자인 패턴","언어 중립 가이드","유사 코드 예제","소프트웨어 설계","디자인 패턴","구조 개선","아키텍처","결합","AI 에이전트","Claude Code"],"es":["patrones de diseño GoF","ejemplos de pseudocódigo","mejora de código","refactorización de código","arquitectura de software","desacoplamiento","herramientas de desarrollo"," Claude Code"],"fr":["modèles de conception GoF","exemples de pseudocode","amélioration de code","refactorisation de code","architecture de logiciel","découplage","outils de développement","Claude Code"],"de":["GoF-Entwurfsmuster","Pseudocode-Beispiele","Code-Verbesserung","Refaktorierung von Code","Software-Architektur","Entkopplung","Entwicklungstools","Claude Code","Künstliche Intelligenz Tools"],"pt":["padrões de projeto GoF","desenvolvimento de software","arquitetura de software","refatoração de código","decoupling","pseudocódigo","linguagem-agnóstica","desenvolvedores"],"ru":["шаблоны проектирования GoF","разработка программного обеспечения","архитектура программного обеспечения","рефакторинг кода","декуплинг","псевдокод","языково-независимое","разработчики"],"ar":["أنماط التصميم GoF","تنمية البرمجيات","هيكل البرمجيات","تحسين الكود","تنسيق","الكود","غير متعلقة باللغة","مطوّرون"]}},"owner":"grndlvl","repo":"software-patterns","repoPath":"grndlvl/software-patterns","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"gof-patterns","description":"Gang of Four design patterns reference. Use this skill when implementing, discussing, or choosing object-oriented design patterns. Auto-activates for architecture decisions, refactoring, and decoupling concerns. Comprehensive coverage of all 23 GoF patterns with pseudocode examples.","bodyPreview":"# GoF Design Patterns Reference\n\nA comprehensive reference for the Gang of Four design patterns. This skill provides language-agnostic guidance with pseudocode examples that can be translated to any programming language.\n\n## When This Skill Activates\n\nThis skill automatically activates when you:\n- Ask about or need to implement a design pattern\n- Need to choose between patterns for a design problem\n- Are refactoring code and considering structural improvements\n- Discuss architecture, decoupling,","body":"# GoF Design Patterns Reference\n\nA comprehensive reference for the Gang of Four design patterns. This skill provides language-agnostic guidance with pseudocode examples that can be translated to any programming language.\n\n## When This Skill Activates\n\nThis skill automatically activates when you:\n- Ask about or need to implement a design pattern\n- Need to choose between patterns for a design problem\n- Are refactoring code and considering structural improvements\n- Discuss architecture, decoupling, or extensibility\n- Mention specific patterns: factory, singleton, observer, decorator, etc.\n\n## Quick Pattern Reference\n\n### Creational Patterns (Object Creation)\n| Pattern | Intent | Use When |\n|---------|--------|----------|\n| [Abstract Factory](gof-creational/abstract-factory.md) | Create families of related objects | Need platform/theme independence |\n| [Builder](gof-creational/builder.md) | Construct complex objects step-by-step | Object has many optional parts |\n| [Factory Method](gof-creational/factory-method.md) | Let subclasses decide which class to instantiate | Don''t know concrete types ahead of time |\n| [Prototype](gof-creational/prototype.md) | Clone existing objects | Object creation is expensive |\n| [Singleton](gof-creational/singleton.md) | Ensure single instance | Need exactly one shared instance |\n\n### Structural Patterns (Composition)\n| Pattern | Intent | Use When |\n|---------|--------|----------|\n| [Adapter](gof-structural/adapter.md) | Convert interface to expected interface | Integrating incompatible interfaces |\n| [Bridge](gof-structural/bridge.md) | Separate abstraction from implementation | Need to vary both independently |\n| [Composite](gof-structural/composite.md) | Treat individual and groups uniformly | Have tree structures |\n| [Decorator](gof-structural/decorator.md) | Add responsibilities dynamically | Need flexible extension |\n| [Facade](gof-structural/facade.md) | Simplified interface to subsystem | Complex subsystem needs simple API |\n| [Flyweight](gof-structural/flyweight.md) | Share common state efficiently | Many similar objects needed |\n| [Proxy](gof-structural/proxy.md) | Control access to object | Need lazy loading, access control, logging |\n\n### Behavioral Patterns (Communication)\n| Pattern | Intent | Use When |\n|---------|--------|----------|\n| [Chain of Responsibility](gof-behavioral/chain-of-responsibility.md) | Pass request along handler chain | Multiple handlers, unknown which handles |\n| [Command](gof-behavioral/command.md) | Encapsulate request as object | Need undo, queue, or log operations |\n| [Interpreter](gof-behavioral/interpreter.md) | Define grammar and interpret sentences | Have a simple language to parse |\n| [Iterator](gof-behavioral/iterator.md) | Sequential access without exposing internals | Need to traverse collections |\n| [Mediator](gof-behavioral/mediator.md) | Centralize complex communications | Many objects communicate in complex ways |\n| [Memento](gof-behavioral/memento.md) | Capture and restore object state | Need undo/snapshot functionality |\n| [Observer](gof-behavioral/observer.md) | Notify dependents of state changes | One-to-many dependency |\n| [State](gof-behavioral/state.md) | Alter behavior when state changes | Object behavior depends on state |\n| [Strategy](gof-behavioral/strategy.md) | Encapsulate interchangeable algorithms | Need to swap algorithms at runtime |\n| [Template Method](gof-behavioral/template-method.md) | Define skeleton, let subclasses fill in | Algorithm structure fixed, steps vary |\n| [Visitor](gof-behavioral/visitor.md) | Add operations without changing classes | Need to add many operations to stable structure |\n\n## Decision Guide\n\nSee [Pattern Selection Guide](pattern-selection.md) for help choosing the right pattern.\n\n## How to Use This Reference\n\n1. **Choosing a pattern**: Start with the decision guide or tables above\n2. **Learning a pattern**: Read the full documentation with examples\n3. **Quick reminder**: Use the tables above for at-a-glance reference\n4. **Implementation**: Follow the pseudocode, adapt to your language\n\n## Language Translation Notes\n\nThe pseudocode in this reference uses these conventions:\n- `class` for type definitions\n- `function` for methods/functions\n- `->` for method calls on objects\n- `//` for comments\n- Type hints shown as `name: Type`\n\nTranslate to your language:\n- **PHP**: `class`, `function`, `->`, `//`, type hints in docblocks or PHP 8+\n- **JavaScript/TypeScript**: `class`, `function`/arrow, `.`, `//`, TS types\n- **Python**: `class`, `def`, `.`, `#`, type hints\n- **Java/C#**: Direct mapping with `new`, generics\n\n---\n\n*Based on concepts from \"Design Patterns: Elements of Reusable Object-Oriented Software\" by Gamma, Helm, Johnson, and Vlissides (Gang of Four), 1994.*\n"},"lastSynced":"2026-03-08T02:02:38.179Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring comprehensive Gang of Four design pattern guidance and pseudocode examples","zh":"适用于需要全面 Gang of Four 设计模式指导和伪代码示例的代码审查代理","ja":"コードレビュー代理が包括的なGang of Four設計パターンガイダンスと疑似コードの例を必要とする場合に適しています","ko":"포괄적인 Gang of Four 디자인 패턴 가이드 및 의사 코드 예가 필요한 코드 리뷰 에이전트에 적합합니다","es":"Ideal para Agentes de Revisión de Código que requieren una guía integral de patrones de diseño de Gang of Four y ejemplos de pseudocódigo","fr":"Idéal pour les Agents de Revue de Code nécessitant une guidance complète sur les modèles de conception de Gang of Four et des exemples de pseudocode","de":"Ideal für Code-Review-Agents, die eine umfassende Anleitung zu Gang-of-Four-Entwurfsmustern und Pseudocode-Beispielen benötigen","pt":"Ideal para agentes de revisão de código que exigem orientação abrangente de padrões de design Gang of Four e exemplos de pseudocódigo","ru":"Идеально для агентов кодового обзора, требующих всестороннего руководства по шаблонам проектирования Gang of Four и примерам псевдокода","ar":"مثالي لعمال مراجعة الشفرة الذين يتطلبون إرشادات شاملة لنمط تصميم غانغ أوف فور وأمثلة على الكود الزائف"},"recommendation":{"en":"Empowers agents to implement and choose between creational, structural, and behavioral patterns using language-agnostic pseudocode, facilitating improved code architecture and decoupling through design pattern references and best practices","zh":"赋予代理实现和选择创建、结构和行为模式的能力，使用语言无关的伪代码，通过设计模式引用和最佳实践来实现改进的代码架构和解耦","ja":"エージェントに、言語非依存の疑似コードを使用して、創造、構造、動作パターンを実装し選択する能力を与え、設計パターンの参照とベストプラクティスを通じて、コードアーキテクチャと結合の解除を改善します","ko":"에이전트가 생성, 구조 및 행동 패턴을 구현 및 선택할 수 있는 능력을 부여하여 언어에 종속되지 않는 의사 코드를 사용하고, 디자인 패턴 참조 및 모범 사례를 통해 코드 아키텍처와 결합을 분리하여 개선합니다","es":"Habilita a los agentes a implementar y elegir entre patrones de creación, estructurales y de comportamiento utilizando pseudocódigo independiente del lenguaje, lo que facilita una mejor arquitectura de código y desconexión a través de referencias de patrones de diseño y mejores prácticas","fr":"Permet aux agents de mettre en œuvre et de choisir entre les modèles de création, structurels et de comportement en utilisant un pseudocode indépendant du langage, ce qui facilite une meilleure architecture de code et une découplage grâce aux références de modèles de conception et aux meilleures pratiques","de":"Ermächtigt die Agenten, Creational-, Structural- und Behavioral-Muster mithilfe von sprachunabhängigem Pseudocode zu implementieren und auszuwählen, was eine verbesserte Code-Architektur und Entkopplung durch Design-Muster-Referenzen und Best Practices ermöglicht","pt":"Habilita os agentes a implementar e escolher entre padrões criacionais, estruturais e comportamentais usando pseudocódigo independente de linguagem, facilitando uma arquitetura de código melhorada e desacoplamento por meio de referências de padrões de design e melhores práticas","ru":"Наделяет агентов возможностью реализовывать и выбирать между порождающими, структурными и поведенческими шаблонами с помощью языково-независимого псевдокода, облегчая улучшение архитектуры кода и разделение через ссылки на шаблоны проектирования и лучшие практики","ar":"يتمكن العمال من تنفيذ اختيار بين أنماط الإنشاء والهيكلية والسلوكية باستخدام كود زائف مستقل عن اللغة، مما يسهل تحسين هيكلية الشفرة وفصلها من خلال مرجع أنماط التصميم وأفضل الممارسات"},"useCases":{"en":["Implementing Singleton patterns for resource management","Refactoring code using Factory Method patterns for improved extensibility","Selecting optimal patterns for design problems"],"zh":["实现Singleton模式用于资源管理","使用Factory Method模式重构代码以提高可扩展性","选择设计问题的最佳模式"],"ja":["リソース管理のためにSingletonパターンを実装する","Factory Methodパターンを使用してコードをリファクタリングし、拡張性を高める","設計問題のための最適なパターンを選択する"],"ko":["리소스 관리를 위해 Singleton 패턴을 구현한다","Factory Method 패턴을 사용하여 코드를 리팩토링하여 확장성을 개선한다","디자인 문제에 최적의 패턴을 선택한다"],"es":["Implementar patrones Singleton para la gestión de recursos","Reestructurar el código utilizando patrones de método de fábrica para una mayor extensibilidad","Seleccionar patrones óptimos para problemas de diseño"],"fr":["Mettre en œuvre des modèles Singleton pour la gestion des ressources","Réorganiser le code en utilisant des modèles de méthode de fabrique pour une meilleure extensibilité","Sélectionner des modèles optimaux pour les problèmes de conception"],"de":["Implementierung von Singleton-Mustern für die Ressourcenverwaltung","Neustrukturierung des Codes unter Verwendung von Factory-Method-Mustern für eine verbesserte Erweiterbarkeit","Auswahl optimaler Muster für Entwurfsprobleme"],"pt":["Implementação de padrões Singleton para gerenciamento de recursos","Reestruturação de código usando padrões de método de fábrica para melhorar a extensibilidade","Seleção de padrões óptimos para problemas de design"],"ru":["Реализация шаблонов Singleton для управления ресурсами","Перестройка кода с помощью шаблонов метода фабрики для улучшения расширяемости","Выбор оптимальных шаблонов для задач проектирования"],"ar":["تنفيذ نمط Singleton لإدارة الموارد","إعادة هيكلة الشفرة باستخدام نمط طريقة المصنع لتحسين القابلية للتوسيع","اختيار الأنماط المثالية لمشاكل التصميم"]},"limitations":{"en":["Language-agnostic, requires translation of pseudocode to specific programming languages"],"zh":["语言无关，需要将伪代码翻译成特定的编程语言"],"ja":["言語非依存で、疑似コードを特定のプログラミング言語に翻訳する必要がある"],"ko":["언어에 종속되지 않지만, 의사 코드를 특정 프로그래밍 언어로 번역해야 하는 제한이 있다"],"es":["Independiente del lenguaje, requiere la traducción de pseudocódigo a lenguajes de programación específicos"],"fr":["Indépendant du langage, nécessite la traduction du pseudocode en langages de programmation spécifiques"],"de":["Sprachunabhängig, erfordert die Übersetzung von Pseudocode in bestimmte Programmiersprachen"],"pt":["Linguagem-agnóstico, requer tradução de pseudocódigo para linguagens de programação específicas"],"ru":["Языково-независимый, требует перевода псевдокода на конкретные языки программирования"],"ar":["متجاوز للغة، يتطلب ترجمة الكود الزائف إلى لغات برمجة محددة"]},"version":4},"contentHash":"90627ded5fee2428f28030d5ca82e7f35088d0344c2ca36b4ba7c20cccd17f55","qualityScore":29}');
