INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BaqiF2/Synapse-Agent/brainstorming', 'brainstorming', 'BaqiF2', 'Synapse-Agent', 'community', 'brainstorming BaqiF2 Synapse-Agent community The Brainstorming AI Agent helps developers turn ideas into validated requirements through natural dialogue, refining designs and producing formal PRD and BDD acceptance documents. AI智能头脑风暴工具帮助将想法转化为可验证的需求规格，通过自然协作对话实现设计的迭代验证 ブレーンストーミングAIエージェントは、アイデアを検証可能な要件仕様に変換するための自然なコラボレーションディアログを提供します 브레인스토밍 AI 에이전트는 아이디어를 검증 가능한 요구사항 명세로 변환하는 자연 협作 대화를 제공합니다 El brainstorming es un proceso que ayuda a convertir ideas en especificaciones de requisitos validadas a través del diálogo colaborativo Le brainstorming est un processus qui aide à transformer les idées en spécifications de exigences validées à travers un dialogue collaboratif Das Brainstorming ist ein Prozess, der hilft, Ideen in validierte Anforderungsspezifikationen durch einen kooperativen Dialog umzuwandeln O agente de IA de brainstorming ajuda a transformar ideias em especificações de requisitos validadas e testáveis através do diálogo colaborativo natural ИИ Агент для мозгового штурма помогает превратить идеи в проверяемые требования посредством естественного совместного диалога يُساعد جهاز العقل الإلكترونية في تحويل الأفكار إلى مواصفات متطلبات قابلة للتحقق والاختبار من خلال الحوار التعاوني الطبيعي how to use brainstorming for requirements gathering brainstorming vs mind mapping what is brainstorming in software development brainstorming install guide for AI Agents brainstorming setup for collaborative design brainstorming alternative for idea validation brainstorming tutorial for developers brainstorming best practices for AI Agents brainstorming for PRD and BDD document generation AI智能头脑风暴 需求规格 自然协作对话 设计迭代验证 PRD和BDD 项目背景理解 用户意图理解 AI工具 智能头脑风暴 Understands user intent through natural collaborative dialogue Explores approaches and refines design through incremental validation Produces formal PRD and BDD acceptance documents Starts with understanding the current project context Asks questions one at a time to refine the idea Validates design before producing formal documents Brainstorming is a collaborative process that turns ideas into validated, testable requirement specifications through incremental validation and refinement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KrystianYCSilva/hefesto-skill-generator/coding-agent-tools', 'community', 'KrystianYCSilva', 'hefesto-skill-generator', 'KrystianYCSilva/hefesto-skill-generator', 'coding-agent-tools', 0, 0, 29, '2026-03-08T01:57:15.329Z', '2026-03-08T02:03:08.994Z', 'c3c0ff7df66f9a2b514d464e9471567e65bc23f27de4989d4eed62d4f83639bb', '{"id":"KrystianYCSilva/hefesto-skill-generator/coding-agent-tools","name":"coding-agent-tools","description":{"en":"The coding-agent-tools skill guides the setup and usage of the modern AI Pair Programmer stack, helping developers choose the right tools based on interaction depth.","zh":"Coding Agent Tools是一个生成标准化AI Agent Skills的工具，支持多个CLI的IA，遵循agentskills.io标准","ja":"Coding Agent Toolsは、agentskills.io標準に基づいた多くのCLIのIAをサポートする標準化されたAI Agent Skillsを生成するツールです","ko":"Coding Agent Tools는 여러 CLI의 IA를 지원하는 표준화된 AI 에이전트 스킬을 생성하는 도구입니다","es":"Hefesto es un generador de habilidades que crea habilidades de agentes estandarizadas para múltiples interfaces de línea de comandos de IA, siguiendo el estándar abierto agentskills.io","fr":"Hefesto est un générateur de compétences qui crée des compétences d''agents standardisées pour plusieurs interfaces de ligne de commande d''IA, suivant la norme ouverte agentskills.io","de":"Hefesto ist ein Skill-Generator, der standardisierte Agent-Skills für mehrere KI-Command-Line-Interfaces erstellt, basierend auf dem offenen Standard agentskills.io","pt":"O Hefesto é um gerador de skills que cria Agent Skills padronizadas para múltiplos CLIs de IA. Aprenda a configurá-lo para codificação de agentes","ru":"Hefesto - это генератор навыков, создающий стандартизированные навыки агентов для нескольких CLI ИИ. Узнайте, как его настроить","ar":"Hefesto هو مولد مهارات يخلق مهارات وكلاء معيارية لأوامر متعددة من الإصطناع. تعلم كيفية إعداده"},"seo":{"title":{"en":"Coding-Agent-Tool